INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('28ce4462-a92a-404a-9625-2653a3178265', 'Neutral Wrist Roller', 'Arms', 'Bodyweight', '{"Forearms"}'::text[], '{}'::text[], 'Build grip strength and forearm size with this movement exercise. This bodyweight exercise requires no equipment and can be done anywhere. Dedicated arm training builds both strength and muscular definition. This variation is excellent for building mind-muscle connection.', '88821201', '88821201-Neutral-Wrist-Roller_Forearms_.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Set up in the starting position for Neutral Wrist Roller. 2. Execute the movement with proper form, focusing on your forearms. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'general_exercise', 'Neutral Wrist Roller', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('28d00b3d-e320-4434-83cb-81cfbc3bfa60', 'Cross Knee To Toe Touch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'A challenging plyometric exercise, the Cross Knee To Toe Touch builds reactive power and improves conditioning. Secondary activation of your hip flexors provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '64021201', '64021201-Cross-Knee-To-Toe-Touch-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:32.501166+00', '1. Set up in the starting position for Cross Knee To Toe Touch. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'toe_touch', 'Cross Knee To Toe Touch', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('28e2fe29-2568-4e73-8365-7a600731a47f', 'Incline Hammer Press (Band)', 'Chest', 'Resistance Band, Incline Bench', '{"Chest"}'::text[], '{}'::text[], 'This pressing exercise focuses on your pectorals for improved chest strength and development. The incline angle shifts emphasis toward the upper portion of the target muscles. Resistance bands provide accommodating resistance that increases through the range of motion. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '68751201', '68751201-Band-Incline-Hammer-Press_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:24.307972+00', '1. Secure the resistance band appropriately for Band Incline Hammer Press. 2. Use a hammer/neutral grip with palms facing each other throughout. 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'incline_press', 'Incline Hammer Press', 'bench_press, shoulder_press, chest_fly', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('28e8f9fb-220b-4fd9-a418-0b9a2654cb51', 'Sled Calf Raise - Forward Facing (Machine)', 'Legs', 'Machine', '{"Calves"}'::text[], '{}'::text[], 'Build stronger calves with this targeted raising exercise. Strong legs are the foundation for athletic performance and functional fitness. This is a great exercise for all fitness levels with proper scaling.', '7421201', '07421201-Sled-Forward-Angled-Calf-Raise_Calves_.mp4', 'male', FALSE, '2025-12-03 23:26:28.968567+00', '1. Lower your heels below the platform to get a full stretch. 2. Rise up onto your toes as high as possible, squeezing your calves. 3. Lower with control and repeat. 4. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'calf_raise', 'Sled Forward Angled Calf Raise', 'standing_calf_raise, seated_calf_raise, tibialis_raise', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('28f1ceea-c5b5-47f5-a9f9-ff7b78fb351a', 'Standing Crossover Raise - Underhand', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'The Standing Underhand Crossover Raise is a raising exercise that targets your chest for shoulder development. Secondary activation of your front delts provides additional muscle engagement. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. Shoulder development enhances both performance and upper body aesthetics.', '64481201', '64481201-Standing-Underhand-Crossover-Raise-(female)_Should.mp4', 'female', FALSE, '2025-12-03 23:26:38.992671+00', '1. Stand with feet about shoulder-width apart. 2. Use an underhand (supinated) grip with palms facing up/toward you. 3. Raise the weight in the prescribed direction for Standing Underhand Crossover Raise. 4. Lower with control, maintaining tension throughout. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'chest_fly', 'Standing Underhand Crossover Raise', 'Standing Crossover Raise - Underhand', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('28f321d3-ed4f-4f4c-8987-0c7642df4a53', 'Wood Chop Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build rotational power and define your waistline with the Bodyweight Wood Chop Squat. The shoulders assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '58821201', '58821201-Bodyweight-Wood-Chop-Squat_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:26.146796+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Keep the movement smooth and controlled.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 85, 9, 8, TRUE, TRUE, 'woodchop', 'Wood Chop Squat', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('28facae0-5e6e-468d-af54-404c8a87eaa5', 'Bent Over Knee Clockwise Rotation', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Use this stretch to open up your full body area and enhance overall flexibility. Bending over allows gravity to provide resistance in a different plane. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '105331201', '105331201-Bent-over-Knee-Clockwise-Rotation-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:30.292204+00', '1. Hinge at your hips, pushing them back while keeping your back flat. 2. Rotate your torso through the movement pattern for Bent Over Knee Clockwise Rotation. 3. Control the rotation in both directions—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Bent Over Knee Clockwise Rotation', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2908f281-3eb6-42cb-a64d-8dffc1317c17', 'Half Squat Wall Tip Toe (Wall)', 'Legs', 'Wall', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Half Squat Wall Tip Toe is a squatting exercise that primarily loads your quadriceps. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Strong legs are the foundation for athletic performance and functional fitness.', '76691201', '76691201-Half-Squat-Wall-Tip-Toe-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:28.851102+00', '1. Position yourself at the appropriate distance from a wall. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions. Start with lighter weight to perfect your form.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 77, 7, 8, TRUE, TRUE, 'calf_raise', 'Half Squat Wall Tip Toe', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('290a6a3d-90d6-434b-af63-9b4a95041f10', 'Seated Internal And External Shoulder Rotation', 'Shoulders', 'Bodyweight', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'This rotation exercise works your rotator cuff for improved shoulder strength and aesthetics. Being seated provides stability, allowing you to focus on the working muscles. Shoulder development enhances both performance and upper body aesthetics.', '89351201', '89351201-Seated-Internal-and-External-Shoulder-Rotation-(ma.mp4', 'male', FALSE, '2025-12-03 23:26:25.123298+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Rotate your torso through the movement pattern for Seated Internal And External Shoulder Rotation. 3. Control the rotation in both directions—avoid using momentum. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Seated Internal And External Shoulder Rotation', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2911f41e-da91-4d39-a844-46e9f3598746', 'Side To Side Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Side To Side Squat is a squatting exercise that primarily loads your quadriceps. Secondary activation of your glutes, hamstrings provides additional muscle engagement. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '54441201', '54441201-Side-to-Side-Squat-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:37.429219+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Keep your shoulders relaxed and away from your ears. A solid choice for legs day.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Side To Side Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('29138fb1-3c43-4bcb-95f0-f02ebc602f45', 'Rear Lunge (Smith Machine)', 'Legs', 'Smith Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This lunging movement emphasizes your quadriceps for stronger, more powerful legs. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. The fixed path allows you to focus purely on muscular effort. Leg training boosts metabolism and builds functional, real-world strength.', '8871201', '08871201-Smith-rear-lunge-(version-2)-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:38.153182+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Rear Lunge. 2. Step forward into a lunge until both knees are at about 90 degrees. 3. Push through your front/working leg to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'lunge', 'Smith Rear Lunge', 'Rear Lunge', FALSE, 'smith_machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('291dd07f-81e4-44d6-8a40-83fd10fc65f1', 'Lateral Raise (Machine)', 'Shoulders', 'Machine', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'This raising exercise works your lateral delts for improved shoulder strength and aesthetics. The fixed path allows you to focus purely on muscular effort. Strong shoulders improve overhead strength and support nearly all upper body movements.', '36291201', '36291201-Lever-Lateral-Raise-(female)_Shoulder.mp4', 'female', FALSE, '2025-12-03 23:26:34.724336+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Lateral Raise. 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 88, 5, 7, FALSE, TRUE, 'lateral_raise', 'Lever Lateral Raise', 'shoulder_press, front_raise, rear_delt', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('2922a1e4-799b-4076-8bae-7727f6119571', 'Half Wipers (Bent Leg)', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Half Wipers (bent Leg), focusing on your abs. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '64321201', '64321201-Half-Wipers-(bent-leg)-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:33.960339+00', '1. Set up in the starting position for Half Wipers. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_exercise', 'Half Wipers', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2922cc5c-2d9c-4f07-a350-52e03a620174', 'Seated Foot Taps (Chair) - Alternating', 'Core', 'Chair', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. Being seated provides stability, allowing you to focus on the working muscles. A strong core improves posture, protects your spine, and enhances all other lifts. Quality repetitions are more important than quantity.', '83081201', '83081201-Seated-Alternate-Foot-Taps-on-a-Chair-(male)_Waist.mp4', 'male', FALSE, '2025-12-03 23:26:26.507873+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Alternate between sides/arms/legs with each repetition. 4. Continue for your target rep count, maintaining good form throughout. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 37, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Foot Taps On A Chair - Alternating', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2923aa75-a369-4904-9d19-2a7fad46fde8', 'Reverse Crunch (Band)', 'Core', 'Resistance Band', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Band Reverse Crunch, focusing on your abs. Secondary activation of your hip flexors provides additional muscle engagement. Bands are joint-friendly and portable, perfect for any training environment. A strong core improves posture, protects your spine, and enhances all other lifts.', '70911201', '70911201-Band-Reverse-Crunch-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:30.887491+00', '1. Secure the resistance band appropriately for Band Reverse Crunch. 2. Lift your hips off the floor by contracting your lower abs. 3. Bring your knees toward your chest, then lower with control. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 75, 5, 7, FALSE, TRUE, 'crunch', 'Reverse Crunch', 'leg_raise, plank, russian_twist, v_up', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('293017b3-0f39-43dc-9900-2420bc2e4c5c', 'Hollow Body Hover', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. Secondary activation of your hip flexors provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities. Excellent for pre-exhausting the target muscle before compound lifts.', '76871201', '76871201-Hollow-Body-Hover-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:20.982555+00', '1. Set up in the starting position for Hollow Body Hover. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hollow_hold', 'Hollow Body Hover', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('2943f1c4-e81d-4ea9-a860-49267e7cefdb', 'Sprint (Against Wall)', 'Full Body', 'Wall', '{"Full Body"}'::text[], '{"Quads","Hamstrings"}'::text[], 'Build power and athleticism with this high-intensity movement exercise that challenges your entire body. Plyometric training builds explosive power that transfers to sports and daily activities.', '90401201', '90401201-Sprint-against-Wall-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:21.732034+00', '1. Position yourself at the appropriate distance from a wall. 2. Set up in the starting position for Sprint Against Wall. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 42, 7, 8, TRUE, TRUE, 'sprint', 'Sprint Against Wall', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('29464da5-745b-48b4-ad89-f8e407fef65e', 'Kneeling To Stand', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Build power and athleticism with this high-intensity movement exercise that challenges your entire body. Kneeling helps eliminate lower body momentum from the movement. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '107501201', '107501201-Kneeling-to-Stand-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:28.397686+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Set up in the starting position for Kneeling To Stand. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Kneeling To Stand', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2947e918-fc37-4d7c-8e57-81f2cf95a1b5', 'Diamond Push Up (On Knees)', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Diamond Push Up (on Knees) targets your triceps through a pushing motion. The chest assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Arm strength supports grip, pulling, and pushing in compound movements.', '70771201', '70771201-Diamond-Push-up-(on-knees)-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:32.624497+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Repeat for the prescribed number of repetitions. Start with lighter weight to perfect your form. An effective movement for your arms routine.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Diamond Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('295a1d4c-4b60-4d88-9b2c-7f6ff4cedf5f', 'Sumo Crab Walk', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Sumo Crab Walk is a lower body stepping exercise that targets your full body. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '85951201', '85951201-Sumo-Crab-Walk-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:21.732034+00', '1. Set up in the starting position for Sumo Crab Walk. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'walking', 'Sumo Crab Walk', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('29640e09-7020-42eb-a6ab-d29b0ce39c72', 'Standing Triceps Pushdown (Resistance Band)', 'Arms', 'Resistance Band, Anchor Point', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'Build stronger triceps with this pushing exercise for bigger arms. Performing this standing challenges your balance and core engagement. The band creates increasing tension as it stretches, challenging the lockout. Arm strength supports grip, pulling, and pushing in compound movements.', '91491201', '91491201-Resistance-Band-Standing-Triceps-Pushdown-(female).mp4', 'female', FALSE, '2025-12-03 23:26:36.266593+00', '1. Secure the resistance band appropriately for Resistance Band Standing Triceps Pushdown. 2. Stand tall with your feet firmly planted. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 57, 5, 7, FALSE, TRUE, 'tricep_pushdown', 'Standing Triceps Pushdown', 'tricep_extension, close_grip_bench, dip', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('2968155b-509b-4fec-9a58-05422422b64f', 'Step Out Side Bend', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'This dynamic stepping movement gets your heart rate up while developing explosive strength. The abs assist throughout the movement, making this a well-rounded exercise. Plyometric training builds explosive power that transfers to sports and daily activities.', '68551201', '68551201-Step-Out-Side-Bend-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.21093+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Step Out Side Bend. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'side_bend', 'Step Out Side Bend', 'stretch_hip, dynamic_warmup, yoga_pose', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('297343b7-181b-4f54-ae31-8fb012c936de', 'Leg Lift Double Hands Crunch - Alternating', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Alternate Leg Lift Double Hands Crunch is an explosive exercise that combines cardiovascular training with dynamic crunching movements. Your hip flexors work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '89101201', '89101201-Alternate-Leg-Lift-Double-Hands-Crunch-(male)_Plyo.mp4', 'male', FALSE, '2025-12-03 23:26:20.847006+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Alternate between sides/arms/legs with each repetition. 5. Complete all reps with control before resting. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Leg Lift Double Hands Crunch - Alternating', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('2982a9ff-9746-4a25-a56f-8ffac1e8624e', 'Seated Overhead Side And 45 Degrees Bend Forward', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Seated Overhead Side And 45 Degrees Bend Forward ( is a core movement exercise that primarily targets your core. The seated position helps isolate the target muscles by removing momentum. Building core stability helps with everything from heavy deadlifts to daily activities.', '81531201', '81531201-Seated-Overhead-Side-and-45-degrees-Bend-Forward-(.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Set up in the starting position for Seated Overhead Side And 45 Degrees Bend Forward (. 3. Execute the movement with proper form, focusing on your core. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Overhead Side And 45 Degrees Bend Forward (', 'russian_twist, woodchop, oblique_crunch', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('298eefd0-6dc9-45d4-a9b7-c698fabec831', 'Punch Twist', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Abs"}'::text[], 'The Punch Twist is an explosive exercise that combines cardiovascular training with dynamic twisting movements. Secondary activation of your abs provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities.', '45051201', '45051201-Punch-Twist_Plyometrics.mp4', 'male', FALSE, '2025-12-03 23:26:30.099411+00', '1. Rotate your torso through the movement pattern for Punch Twist. 2. Control the rotation in both directions—avoid using momentum. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'russian_twist', 'Punch Twist', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('299ae9b9-2a07-4ae6-87f8-5a3ab7f39564', 'Glute Bridge (Dumbbell)', 'Legs', 'Dumbbells', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Build stronger glutes with this bridging movement focused on hip extension. The hamstrings assist throughout the movement, making this a well-rounded exercise. Dumbbells allow each arm to work independently, helping correct imbalances. Strong legs are the foundation for athletic performance and functional fitness.', '34271201', '34271201-Dumbbell-Glute-Bridge-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:32.735372+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Glute Bridge. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'glute_bridge', 'Glute Bridge', 'hip_thrust, romanian_deadlift', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('299c31dd-9c19-4ad2-b355-e78821bad73c', 'Lateral Raise Plank (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Core","Abs"}'::text[], '{"Traps"}'::text[], 'This raising exercise engages your lateral delts for improved core stability and strength. Your shoulders, lower back work as secondary movers, adding to the training stimulus. Dumbbells allow each arm to work independently, helping correct imbalances. A strong core improves posture, protects your spine, and enhances all other lifts.', '82211201', '82211201-Dumbbell-Lateral-Raise-Plank-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.644637+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Lateral Raise Plank. 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'lateral_raise', 'Lateral Raise Plank', 'shoulder_press, front_raise, rear_delt', TRUE, 'dumbbell', TRUE, 3, 60, 2, 92, 90, 92, 90),
('299c417b-cf15-4dfe-8251-76930cb7225a', 'Superman Lat Pulldown And Leg Raise (Cable)', 'Back', 'Cables', '{"Lats"}'::text[], '{"Glutes","Upper Back"}'::text[], 'Build leg strength with this pulling movement focusing on your lats. Secondary activation of your biceps, upper back provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '96231201', '96231201-Superman-Lat-Pulldown-and-Leg-Raise-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Pull the bar/handle down toward your upper chest. 2. Drive your elbows down and back, squeezing your lats. 3. Control the weight back up without letting it yank your arms. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 80, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Superman Lat Pulldown And Leg Raise', 'pull_up, bent_over_row, cable_row, face_pull', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('299cc7d2-0579-4017-a1eb-e4c2cfcc22cc', 'YW Raise (TRX)', 'Shoulders', 'TRX', '{"Rear Delts"}'::text[], '{"Upper Back","Rotator Cuff"}'::text[], 'This raising exercise engages your abs for improved core stability and strength. The TRX allows you to adjust difficulty by changing your body angle. A strong core improves posture, protects your spine, and enhances all other lifts.', '75021201', '75021201-Suspender-YW-raise-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:39.623429+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender YW Raise. 2. Raise the weight in the prescribed direction for Suspender YW Raise. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 60, 5, 7, FALSE, TRUE, 'general_exercise', 'Suspender YW Raise', 'squat, bench_press, deadlift', FALSE, 'trx', FALSE, 3, 60, 2, 68, 85, 85, 70),
('29a59526-c0e0-4eb9-8949-b28c7cd6e0fa', 'Diver Plank Jack', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'This dynamic stabilization movement gets your heart rate up while developing explosive strength. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning.', '71471201', '71471201-Diver-Plank-Jack-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout. This variation specifically emphasizes the abs.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'plank', 'Diver Plank Jack', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('29a7b894-c512-4576-987c-62cf80e5132d', 'Side Shuffle Obliques Twist', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Build power and athleticism with this high-intensity twisting exercise that challenges your entire body. Your abs work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning. Works well as both a primary exercise or accessory movement.', '78481201', '78481201-Side-Shuffle-Obliques-Twist-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:23.288245+00', '1. Rotate your torso through the movement pattern for Side Shuffle Obliques Twist. 2. Control the rotation in both directions—avoid using momentum. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'shuffle', 'Side Shuffle Obliques Twist', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('29b4ef82-cba0-4e64-ac8a-86251cb1d8a4', 'Dynamic Half Child Pose', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Lower Back"}'::text[], 'Target your back with this movement stretch that helps restore range of motion. Secondary activation of your hips provides additional muscle engagement. Flexibility work like this enhances performance and prevents stiffness.', '84871201', '84871201-Dynamic-Half-Child-Pose-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. Move into the stretch position for Dynamic Half Child Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'back_stretch', 'Dynamic Half Child Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('29b552b5-a300-49a6-910d-cf9a83d64845', 'Lat Pulldown Full Range Of Motion (Cable)', 'Back', 'Cables', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This pulling exercise emphasizes your lats for improved back development. The biceps, upper back assist throughout the movement, making this a well-rounded exercise. Cable resistance creates smooth, continuous muscle engagement. A strong back improves posture, prevents injury, and balances pressing movements.', '23301201', '23301201-Cable-Lat-Pulldown-Full-Range-Of-Motion_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:25.233728+00', '1. Adjust the cable machine to the correct height and attachment for Cable Lat Pulldown Full Range Of Motion. 2. Pull the bar/handle down toward your upper chest. 3. Drive your elbows down and back, squeezing your lats. 4. Control the weight back up without letting it yank your arms. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 90, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Lat Pulldown Full Range Of Motion', 'pull_up, bent_over_row, cable_row, face_pull', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('29f2032d-20b7-40f9-b69e-c7c222fd741e', 'Side Lying Side Crunch', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Hip Flexors","Abs"}'::text[], 'This crunching exercise engages your abs for improved core stability and strength. Secondary activation of your abs provides additional muscle engagement. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '73961201', '73961201-Side-Lying-Side-Crunch-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:37.179953+00', '1. Lie on your side with your body aligned. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Side Lying Side Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('29f66d5e-c524-47ab-b23e-411819510d30', 'Front Plank With Arm And Leg Lift (Push Up Position)', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger chest with this pushing movement that develops pressing power. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '28971201', '28971201-Front-Plank-with-Arm-and-Leg-Lift-(push-up-positio.mp4', 'female', FALSE, '2025-12-03 23:26:33.640031+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Complete all reps with control before resting. Maintain a neutral spine throughout. An effective movement for your chest routine.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Front Plank With Arm And Leg Lift (push Up Positio', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2a05833f-07da-480b-8b2e-49ad7f1112c5', 'Fingers Extension (Resistance Band)', 'Arms', 'Resistance Band', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'The Resistance Band Fingers Extension targets your triceps through a extension motion. The band creates increasing tension as it stretches, challenging the lockout. Arm strength supports grip, pulling, and pushing in compound movements.', '88771201', '88771201-Resistance-Band-Fingers-Extension-(male)_Hands_.mp4', 'male', FALSE, '2025-12-03 23:26:26.93819+00', '1. Secure the resistance band appropriately for Resistance Band Fingers Extension. 2. Extend through the target joint(s) for Resistance Band Fingers Extension. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 75, 5, 7, FALSE, TRUE, 'general_exercise', 'Fingers Extension', 'squat, bench_press, deadlift', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('2a0fb753-1fb2-4263-b23e-9033ed9ccd59', 'High Knee Jump Rope (Jump Rope)', 'Full Body', 'Jump Rope', '{"Full Body"}'::text[], '{}'::text[], 'This cardio exercise keeps your heart rate elevated for improved cardiovascular fitness. You''ll also feel your hip flexors working to support the movement. Regular cardio training builds the aerobic base for better overall fitness. Excellent for pre-exhausting the target muscle before compound lifts.', '83701201', '83701201-High-Knee-Jump-Rope-(female)_Cardio_.mp4', 'female', FALSE, '2025-12-03 23:26:33.960339+00', '1. Set up in the starting position for High Knee Jump Rope. 2. Execute the movement with proper form, focusing on your cardio. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'high_knees', 'High Knee Jump Rope', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2a14aaec-76ea-4d1c-8bf5-0e2d8c217f5c', 'Assisted Lying Supine Hip Adduction (Stability Ball)', 'Legs', 'Stability Ball', '{"Inner Thighs"}'::text[], '{}'::text[], 'The Assisted Lying Supine Hip Adduction (stability Ball) is a lower body movement exercise that targets your adductors. Performing this lying down removes momentum for stricter form. The stability ball adds an instability challenge that activates more stabilizer muscles. Leg training boosts metabolism and builds functional, real-world strength.', '100141201', '100141201-Ball-Assisted-Lying-Supine-Hip-Adduction-(female).mp4', 'female', FALSE, '2025-12-03 23:26:30.685158+00', '1. Position the stability ball as needed for Assisted Lying Supine Hip Adduction. 2. Lie on your back with your body relaxed but ready. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 32, 7, 8, TRUE, TRUE, 'hip_adduction', 'Assisted Lying Supine Hip Adduction', 'hip_abduction, squat, lunge', FALSE, 'stability_ball', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2a1b2855-08e8-412e-9dd0-0bb00a79663e', 'Lying Calf Raise (Pilates Machine)', 'Legs', 'Pilates Machine', '{"Calves"}'::text[], '{}'::text[], 'This stretch specifically works on your calves, promoting flexibility and reducing muscle tightness. Performing this lying down removes momentum for stricter form. Machine exercises are great for isolating muscles and training to failure safely. Include this in your routine for better mobility and reduced muscle tension.', '106571201', '106571201-Pilates-Machine-Lying-Calf-Raise-(female)_Stretch.mp4', 'female', FALSE, '2025-12-03 23:26:35.667316+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Pilates Machine Lying Calf Raise. 2. Lie down in the appropriate position for Pilates Machine Lying Calf Raise. 3. Lower your heels below the platform to get a full stretch. 4. Rise up onto your toes as high as possible, squeezing your calves. 5. Lower with control and repeat.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 88, 5, 7, FALSE, TRUE, 'calf_raise', 'Pilates Lying Calf Raise', 'Pilates Lying Calf Raise', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('2a246020-094b-4eff-8579-18d9dc8c31af', 'Standing Single Arm Fly (Cable)', 'Chest', 'Cables', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Target your chest with the Cable Standing Single Arm Fly, an effective flying movement for upper body strength. The front delts assist throughout the movement, making this a well-rounded exercise. The standing position engages your core for stability. The cable setup allows you to adjust the angle of resistance. A well-developed chest contributes to upper body strength and aesthetics.', '107191201', '107191201-Cable-Standing-Single-Arm-Fly-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:32.054831+00', '1. Adjust the cable machine to the correct height and attachment for Cable Standing Single Arm Fly. 2. Begin in a standing position with good posture. 3. With a slight bend in your elbows, move the weight in a wide arc. 4. Squeeze your chest muscles at the center/top of the movement. 5. Return with control, feeling the stretch at the bottom. 6. Complete all reps on one side, then switch to the other side. 7. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 77, 5, 7, FALSE, TRUE, 'chest_fly', 'Standing Single Arm Fly', 'bench_press, incline_press, push_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('2a2b6cc5-a827-41c4-b208-38c34be55dc0', 'Heel To Toe Walk', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Heel To Toe Walk isolates your calf muscles through a stepping motion. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '107031201', '107031201-Heel-to-Toe-Walk-(female)_Calves_.mp4', 'female', FALSE, '2025-12-03 23:26:33.960339+00', '1. Set up in the starting position for Heel To Toe Walk. 2. Execute the movement with proper form, focusing on your calves. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'walking', 'Heel To Toe Walk', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2a37072f-c64a-4a80-890d-ba79978eb9a3', 'Standing Palm Slices', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Standing Palm Slices is an arm movement exercise targeting your full body. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. Dedicated arm training builds both strength and muscular definition.', '65771201', '65771201-Standing-Palm-Slices-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:38.870314+00', '1. Stand tall with your feet firmly planted. 2. Set up in the starting position for Standing Palm Slices. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'general_exercise', 'Standing Palm Slices', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2a41f7a3-0fec-48e4-b9da-4d446a3f1daa', 'Lying Floor Front Raise (Cable)', 'Shoulders', 'Cables', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'Target your front delts with the Cable Lying Floor Front Raise, an effective shoulder raising exercise. Performing this lying down removes momentum for stricter form. Cable resistance creates smooth, continuous muscle engagement. Strong shoulders improve overhead strength and support nearly all upper body movements.', '97051201', '97051201-Cable-Lying-Floor-Front-Raise-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:21.452942+00', '1. Adjust the cable machine to the correct height and attachment for Cable Lying Floor Front Raise. 2. Position yourself on the floor for Cable Lying Floor Front Raise. 3. Lie down in the appropriate position for Cable Lying Floor Front Raise. 4. Raise the weight in front of you to shoulder height. 5. Lower with control, maintaining tension throughout. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 75, 5, 7, FALSE, TRUE, 'front_raise', 'Lying Floor Front Raise', 'shoulder_press, lateral_raise, rear_delt_fly', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('2a4fa85a-93a1-4623-acfd-c4fee4346aaa', 'Chin Ups - Narrow Parallel Grip (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This rowing exercise emphasizes your lats for improved back development. Secondary activation of your biceps provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. A strong back improves posture, prevents injury, and balances pressing movements.', '2531201', '02531201-Chin-ups-(narrow-parallel-grip)_Back.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Use a close/narrow grip (hands closer than shoulder-width). 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Complete all reps with control before resting. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'Chin Ups', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2a6cab48-2cd0-4c4a-a5a0-a34e29c384d8', 'Lying Fly (Cable)', 'Chest', 'Cables', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'This flying exercise focuses on your pectorals for improved chest strength and development. You''ll also feel your front delts working to support the movement. The lying position provides back support and helps isolate the target muscles. Cable resistance creates smooth, continuous muscle engagement. A well-developed chest contributes to upper body strength and aesthetics.', '1851201', '01851201-Cable-Lying-Fly_Chest-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:27.384461+00', '1. Adjust the cable machine to the correct height and attachment for Cable Lying Fly. 2. Lie down in the appropriate position for Cable Lying Fly. 3. With a slight bend in your elbows, move the weight in a wide arc. 4. Squeeze your chest muscles at the center/top of the movement. 5. Return with control, feeling the stretch at the bottom. 6. Complete all reps with control before resting. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'chest_fly', 'Lying Fly', 'bench_press, incline_press, push_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('2a712be8-532e-49fd-aea4-a9a4e82c5b42', 'Single Leg Board Jump', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Elevate your training with this jumping exercise that develops speed, power, and coordination. Your quads, calves work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements. Maintain proper breathing - exhale during the effort phase.', '42451201', '42451201-Single-Leg-Board-Jump_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. Complete all reps on one side, then switch to the other side. 2. Set up in the starting position for Single Leg Board Jump. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 45, 9, 8, TRUE, TRUE, 'leg_exercise', 'Single Leg Board Jump', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('2a74707f-ba72-48ed-ad74-bf8fcd2af98e', 'Belt Squat (Machine)', 'Legs', 'Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. You''ll also feel your glutes, hamstrings working to support the movement. The machine guides your movement path for safer, more controlled repetitions. Lower body strength improves everything from walking to heavy compound lifts.', '96861201', '96861201-Lever-Belt-Squat-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:34.724336+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Belt Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 93, 7, 9, TRUE, FALSE, 'squat', 'Lever Belt Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'machine', FALSE, 4, 120, 5, 80, 75, 20, 88),
('2a78df00-7a1d-41b8-b2ce-897d35de87bf', 'Side Step Arm Circle', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Elevate your training with this stepping exercise that develops speed, power, and coordination. Plyometric training builds explosive power that transfers to sports and daily activities.', '88261201', '88261201-Side-Step-Arm-Circle-(VERSION-2)-(female)_Plyometr.mp4', 'female', FALSE, '2025-12-03 23:26:37.303932+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Side Step Arm Circle. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'arm_exercise', 'Side Step Arm Circle', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2a82b85a-d78c-4396-ba63-2efe0fa2842b', 'Single Arm Side Deadlift (Barbell)', 'Back', 'Barbell', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'Build leg strength with this hip hinge movement focusing on your hamstrings/glutes. The glutes, lower back assist throughout the movement, making this a well-rounded exercise. Using a barbell provides stability for progressive overload. Leg training boosts metabolism and builds functional, real-world strength. Works well as both a primary exercise or accessory movement.', '661201', '00661201-Barbell-One-Arm-Side-Deadlift_Thighs-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:25.233728+00', '1. Grip a barbell with hands at the appropriate width for Barbell One Arm Side Deadlift. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 92, 7, 9, TRUE, FALSE, 'deadlift', 'Single Arm Side Deadlift', 'romanian_deadlift, hip_thrust, leg_curl', TRUE, 'barbell', FALSE, 4, 120, 6, 95, 80, 65, 95),
('2a8dbb36-726f-4298-b85d-34f75dc50bc7', 'Single Leg Hip Thrust (Smith Machine)', 'Legs', 'Smith Machine', '{"Glutes"}'::text[], '{"Hamstrings","Core"}'::text[], 'The Smith Single Leg Hip Thrust is a hip-dominant thrusting exercise that targets your glutes. You''ll also feel your hamstrings working to support the movement. Machine exercises are great for isolating muscles and training to failure safely. Lower body strength improves everything from walking to heavy compound lifts.', '103991201', '103991201-Smith-Single-Leg-Hip-Thrust_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:23.172397+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Single Leg Hip Thrust. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 73, 7, 8, TRUE, TRUE, 'hip_thrust', 'Smith Single Leg Hip Thrust', 'Single Leg Hip Thrust', FALSE, 'smith_machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('2aad6bae-611b-46c6-b75a-5299194ae159', 'Lying Front Raise (Stick)', 'Shoulders', 'Bodyweight', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'The Stick Lying Front Raise is a raising exercise that targets your front delts for shoulder development. Performing this lying down removes momentum for stricter form. No equipment needed—your body provides all the resistance. Strong shoulders improve overhead strength and support nearly all upper body movements.', '105891201', '105891201-Stick-Lying-Front-Raise-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:25.87243+00', '1. Lie down in the appropriate position for Stick Lying Front Raise. 2. Raise the weight in front of you to shoulder height. 3. Lower with control, maintaining tension throughout. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'front_raise', 'Stick Lying Front Raise', 'shoulder_press, lateral_raise, rear_delt_fly', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('2ab7ff84-7f0c-4ca6-9b36-6ae43abd2c70', 'Run (equipment)', 'Full Body', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Run (equipment) is a cardiovascular exercise that improves endurance and heart health. Cardiovascular exercise improves heart health, endurance, and helps manage weight.', '6841201', '06841201-Run-(equipment)_Cardio.mp4', 'male', FALSE, '2025-12-03 23:26:24.099303+00', '1. Set up in the starting position for Run. 2. Execute the movement with proper form, focusing on your cardio. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'running', 'Run', 'cycling, rowing_cardio, jump_rope', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2ab91a0f-56ab-4451-ac4f-b63904c93edb', 'Lying Knee Extension on Toes (Pilates Machine)', 'Legs', 'Pilates Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Pilates Machine Lying Knee Extension On Toes is a extension exercise that primarily loads your quadriceps. The lying position provides back support and helps isolate the target muscles. The machine guides your movement path for safer, more controlled repetitions. Leg training boosts metabolism and builds functional, real-world strength.', '106541201', '106541201-Pilates-Machine-Lying-Knee-Extension-on-Toes-(fem.mp4', 'female', FALSE, '2025-12-03 23:26:35.667316+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Pilates Machine Lying Knee Extension On Toes. 2. Lie down in the appropriate position for Pilates Machine Lying Knee Extension On Toes. 3. Extend through the target joint(s) for Pilates Machine Lying Knee Extension On Toes. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 78, 5, 7, FALSE, TRUE, 'leg_extension', 'Pilates Lying Knee Extension On Toes', 'Pilates Lying Knee Extension On Toes', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('2ac7bbd7-93d3-4fbc-a213-82141c464d1e', 'Swan Dive Pilates', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Shoulders"}'::text[], 'The Swan Dive Pilates is a flexibility exercise that targets your lats, helping to release tension and improve range of motion. Your shoulders work as secondary movers, adding to the training stimulus. Flexibility work like this enhances performance and prevents stiffness.', '86991201', '86991201-Swan-Dive-Pilates-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:39.623429+00', '1. Move into the stretch position for Swan Dive Pilates. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_exercise', 'Swan Dive Pilates', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2ac9a736-9d61-4714-b590-c679c729916d', 'Incline Fly (Kettlebell)', 'Chest', 'Kettlebell, Incline Bench', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'The Kettlebell Incline Fly is a flying exercise that targets your chest muscles. Your front delts work as secondary movers, adding to the training stimulus. The incline angle shifts emphasis toward the upper portion of the target muscles. The kettlebell''s offset center of mass increases the stability challenge. A well-developed chest contributes to upper body strength and aesthetics.', '68201201', '68201201-Kettlebell-Incline-Fly_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:27.263406+00', '1. Select an appropriately weighted kettlebell for Kettlebell Incline Fly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 81, 5, 7, FALSE, TRUE, 'chest_fly', 'Incline Fly', 'bench_press, incline_press, push_up', FALSE, 'kettlebell', FALSE, 3, 60, 2, 75, 88, 88, 78),
('2acdcea9-50f0-4598-8107-af64e7d229a3', 'Frog Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Frog Crunch, focusing on your abs. Your hip flexors work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '25221201', '25221201-Frog-Crunch-(female)_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:33.640031+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Continue for your target rep count, maintaining good form throughout. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Frog Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('2ae2dc93-cef4-4351-b91d-74a15e216e13', 'Standing Overhead Press (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Target your delts with the Dumbbell Standing Overhead Press, an effective shoulder pressing exercise. The triceps assist throughout the movement, making this a well-rounded exercise. The standing position engages your core for stability. Dumbbells allow each arm to work independently, helping correct imbalances. Shoulder development enhances both performance and upper body aesthetics.', '4261201', '04261201-Dumbbell-Standing-Overhead-Press_shoulder.mp4', 'male', FALSE, '2025-12-03 23:26:23.466497+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Standing Overhead Press. 2. Stand tall with your feet firmly planted. 3. Start with the weight at shoulder level. 4. Press directly overhead until your arms are fully extended. 5. Lower back to shoulder level with control. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, 'Standing', NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 99, 7, 9, TRUE, FALSE, 'shoulder_press', 'Standing Overhead Press', 'lateral_raise, front_raise, rear_delt', FALSE, 'dumbbell', FALSE, 4, 120, 4, 92, 90, 92, 90),
('2aeb6071-30b7-4316-be4d-fcfab0fb4a48', 'Lying Toe Tap', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Lying Toe Tap is a lower body movement exercise that targets your full body. The lying position provides back support and helps isolate the target muscles. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '60031201', '60031201-Lying-Toe-Tap-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.38119+00', '1. Lie down in the appropriate position for Lying Toe Tap. 2. Set up in the starting position for Lying Toe Tap. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Toe Tap', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2aef95cc-3314-40ec-a6d9-cf38eca36b7b', 'Shoulder Press - Single Arm (Plate Loaded Machine)', 'Shoulders', 'Machine', '{"Shoulders"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Target your delts with the Lever One Arm Shoulder Press (plate Loaded), an effective shoulder pressing exercise. You''ll also feel your triceps working to support the movement. The machine guides your movement path for safer, more controlled repetitions. Shoulder development enhances both performance and upper body aesthetics.', '5901201', '05901201-Lever-One-Arm-Shoulder-Press-(plate-loaded)_Should.mp4', 'male', FALSE, '2025-12-03 23:26:22.417605+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever One Arm Shoulder Press. 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 83, 7, 8, TRUE, TRUE, 'shoulder_press', 'Lever Single Arm Shoulder Press', 'lateral_raise, front_raise, rear_delt', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('2af26fc4-82d0-41af-a626-c14ed52f58f6', 'Supine Plank (TRX)', 'Core', 'TRX', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'The Suspender Supine Plank is a core stabilization exercise that primarily targets your abs. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. Performing this lying down removes momentum for stricter form. The TRX allows you to adjust difficulty by changing your body angle. Building core stability helps with everything from heavy deadlifts to daily activities.', '11481201', '11481201-Suspender-Supine-Plank-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:39.623429+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Supine Plank. 2. Lie face up (supine position) for Suspender Supine Plank. 3. Hold your body in a straight line from head to heels. 4. Don''t let your hips sag or pike up—engage your core and glutes. 5. Breathe steadily while maintaining the position. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'plank', 'Suspender Supine Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'trx', TRUE, 3, 90, 4, 68, 85, 85, 70),
('2af6953d-3877-48f0-ac11-c708b3833fd3', 'Ring Swing (Gymnastic Rings)', 'Core', 'Gymnastic Rings', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Ring Swing is a core swinging exercise that primarily targets your abs. Building core stability helps with everything from heavy deadlifts to daily activities.', '75221201', '75221201-Ring-Swing-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:23.172397+00', '1. Hinge at your hips, letting the weight swing back between your legs. 2. Explosively drive hips forward, propelling the weight forward/up. 3. Let gravity bring it back as you hinge for the next rep. 4. Repeat for the prescribed number of repetitions. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 38, 7, 8, TRUE, TRUE, 'general_exercise', 'Ring Swing', 'squat, bench_press, deadlift', FALSE, 'gymnastic_rings', FALSE, 3, 90, 4, 68, 85, 85, 70),
('2b0129c4-2c92-4af3-be94-7629878aa27f', 'Seated Front Press (Cable)', 'Shoulders', 'Cables', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'The Cable Seated Front Press is a pressing exercise that targets your front delts for shoulder development. Being seated provides stability, allowing you to focus on the working muscles. The cable setup allows you to adjust the angle of resistance. Strong shoulders improve overhead strength and support nearly all upper body movements.', '93901201', '93901201-Cable-Seated-Front-Press-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:26.93819+00', '1. Adjust the cable machine to the correct height and attachment for Cable Seated Front Press. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Start with the weight at shoulder level. 4. Press directly overhead until your arms are fully extended. 5. Lower back to shoulder level with control. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Front Press', 'plank, crunch, leg_raise', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('2b018a7b-1359-49f3-9e91-938e280b0e49', 'Shrimp Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. Secondary activation of your glutes, hamstrings provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '33661201', '33661201-Shrimp-Squat-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:36.985772+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Ensure full range of motion on each rep. Works well for quads activation.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Shrimp Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2b023eb9-fdd3-44df-bd4a-d7f40c258775', 'Incline Push Up (Smith Machine)', 'Chest', 'Smith Machine', '{"Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'Build a stronger chest with this pushing movement that develops pressing power. You''ll also feel your triceps, front delts working to support the movement. Using an incline changes the angle of resistance for varied muscle recruitment. The fixed path allows you to focus purely on muscular effort. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '65501201', '65501201-Incline-Push-up-on-a-Smith-Bar-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:23.288245+00', '1. Set the Smith machine bar to the appropriate starting height for Incline Push Up On A Smith Bar. 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 81, 7, 8, TRUE, TRUE, 'push_up', 'Incline Push Up On A Smith Bar', 'Incline Push Up On A Bar', FALSE, 'smith_machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('2b1b62e6-71f5-426c-91aa-2f1297c4c2e7', 'Seated Hammer Curl (Dumbbell)', 'Arms', 'Dumbbells, Flat Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Dumbbell Seated Hammer Curl is a curling exercise that isolates your biceps. Your forearms work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. The dumbbell variation provides freedom of movement and greater range of motion. Dedicated arm training builds both strength and muscular definition.', '16781201', '16781201-Dumbbell-Seated-Hammer-Curl_Upper-Arms-FIX2_.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Seated Hammer Curl. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Use a hammer/neutral grip with palms facing each other throughout. 4. Keep your elbows in a fixed position throughout the movement. 5. Curl the weight up by contracting your biceps, squeezing at the top. 6. Lower with control, resisting the weight on the way down. 7. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 94, 5, 7, FALSE, TRUE, 'hammer_curl', 'Seated Hammer Curl', 'bicep_curl, preacher_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('2b25b7e9-1244-4769-a2cc-b28548cc32cf', 'Glute Bridge Two Legs On Bench', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Develop your posterior chain with this bridging movement that emphasizes the glutes. You''ll also feel your hamstrings working to support the movement. Strong legs are the foundation for athletic performance and functional fitness.', '24721201', '24721201-Glute-Bridge-Two-Legs-on-Bench-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:33.778367+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Complete all reps with control before resting. Focus on the mind-muscle connection. Perfect for targeting your glutes.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'glute_bridge', 'Glute Bridge Two Legs On Bench', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2b2943eb-876e-4f87-a2de-9d349be10234', 'Superman - Around the World', 'Back', 'Bodyweight', '{"Lower Back"}'::text[], '{"Glutes","Upper Back"}'::text[], 'Build leg strength with this movement movement focusing on your delts. Your chest work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Leg training boosts metabolism and builds functional, real-world strength.', '87591201', '87591201-Around-the-World-Superman-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:30.54809+00', '1. Set up in the starting position for Around The World Superman. 2. Execute the movement with proper form, focusing on your delts. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, 'Dynamic', 'Compound', 'Unilateral', NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, 'Neutral', 'Standard', 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'around_world', 'Around The World Superman', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2b355afb-df82-491e-862c-072027d9ad50', 'Lying Single Glute Lift', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Develop your posterior chain with this movement movement that emphasizes the glutes. Performing this lying down removes momentum for stricter form. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '64131201', '64131201-Lying-Single-Glute-Lift-(female)_Hips-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:35.38119+00', '1. Lie down in the appropriate position for Lying Single Glute Lift. 2. Set up in the starting position for Lying Single Glute Lift. 3. Execute the movement with proper form, focusing on your glutes. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'glute_exercise', 'Lying Single Glute Lift', 'hip_thrust, glute_bridge, leg_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2b35ab1d-bb62-4ff0-ba28-38af5ddc01b6', 'Invisible Equipment Swing', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Core"}'::text[], 'The Bodyweight Invisible Equipment Swing is a lower body swinging exercise that targets your full body. You''ll also feel your core working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '77551201', '77551201-Bodyweight-Invisible-Equipment-Swing-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:31.347577+00', '1. Hinge at your hips, letting the weight swing back between your legs. 2. Explosively drive hips forward, propelling the weight forward/up. 3. Let gravity bring it back as you hinge for the next rep. 4. Complete all reps with control before resting. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Invisible Equipment Swing', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2b37a773-9ab3-475f-bc98-bfdc9caadf2a', 'Seated Overhead Triceps Extension (Barbell)', 'Arms', 'Barbell, Flat Bench', '{"Triceps"}'::text[], '{"Shoulders"}'::text[], 'The Barbell Seated Overhead Triceps Extension targets your triceps through a extension motion. Being seated provides stability, allowing you to focus on the working muscles. Barbells enable bilateral loading for building raw strength. Arm strength supports grip, pulling, and pushing in compound movements.', '921201', '00921201-Barbell-Seated-Overhead-Triceps-Extension_Upper-Ar.mp4', 'male', FALSE, '2025-12-03 23:26:26.678791+00', '1. Grip a barbell with hands at the appropriate width for Barbell Seated Overhead Triceps Extension. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Extend at the elbow until your arm is straight, squeezing the tricep. 4. Lower with control, keeping your upper arm stationary. 5. Repeat for the prescribed number of repetitions.', NULL, 'Push', 'Isolation', 'Bilateral', NULL, 3, NULL, 5, 7, NULL, 6, 'Seated', NULL, 'Neutral', 'Narrow', 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 94, 5, 7, FALSE, TRUE, 'tricep_extension', 'Seated Overhead Triceps Extension', 'tricep_pushdown, close_grip_bench', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('2b3cc811-654a-4c95-b82d-9e6b94fb348c', 'Standing Lateral Stretch', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Lower Back"}'::text[], 'This stretch specifically works on your lats, promoting flexibility and reducing muscle tightness. Performing this standing challenges your balance and core engagement. Flexibility work like this enhances performance and prevents stiffness.', '43201201', '43201201-Standing-Lateral-Stretch-(female)_Back-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Stand with feet about shoulder-width apart. 2. Move into the stretch position for Standing Lateral Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'stretch_general', 'Standing Lateral Stretch', 'stretch_hip, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('2b41083b-6166-4d28-ae21-52b42abc2bb4', 'Lateral Hit (Resistance Band)', 'Chest', 'Resistance Band', '{"Chest"}'::text[], '{}'::text[], 'This movement exercise focuses on your pectorals for improved chest strength and development. Resistance bands provide accommodating resistance that increases through the range of motion. A well-developed chest contributes to upper body strength and aesthetics.', '105941201', '105941201-Resistance-Band-Lateral-Hit-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Secure the resistance band appropriately for Resistance Band Lateral Hit. 2. Set up in the starting position for Resistance Band Lateral Hit. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'back_exercise', 'Lateral Hit', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('2b5efb7c-f296-4867-8a73-8b2ad3adbc4e', 'Marching Kick On Spot', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build your aerobic capacity with this steady-state cardio movement. Secondary activation of your hip flexors provides additional muscle engagement. Cardiovascular exercise improves heart health, endurance, and helps manage weight.', '84001201', '84001201-Marching-Kick-On-Spot-(female)_Cardio_.mp4', 'female', FALSE, '2025-12-03 23:26:35.38119+00', '1. Set up in the starting position for Marching Kick On Spot. 2. Execute the movement with proper form, focusing on your cardio. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'marching', 'Marching Kick On Spot', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('2b61d2c7-b2e2-4d08-99a7-319b9694a5cd', 'Curl To Press (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Target your delts with the Dumbbell Curl To Press, an effective shoulder pressing exercise. Your forearms work as secondary movers, adding to the training stimulus. Dumbbells allow each arm to work independently, helping correct imbalances. Strong shoulders improve overhead strength and support nearly all upper body movements.', '33471201', '33471201-Dumbbell-Curl-to-Press_Shoulders.mp4', 'female', FALSE, '2025-12-03 23:26:32.735372+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Curl To Press. 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'general_exercise', 'Curl To Press', 'tricep_pushdown, tricep_extension, hammer_curl, preacher_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('2b719497-2c6f-4863-976c-ead9fd94de54', 'Lying Split Abductor', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build leg strength with this movement movement focusing on your glute med/abductors. Your glutes work as secondary movers, adding to the training stimulus. Performing this lying down removes momentum for stricter form. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts.', '96521201', '96521201-Lying-Split-Abductor-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:20.982555+00', '1. Lie down in the appropriate position for Lying Split Abductor. 2. Set up in the starting position for Lying Split Abductor. 3. Execute the movement with proper form, focusing on your glute med/abductors. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_abduction', 'Lying Split Abductor', 'hip_adduction, glute_bridge, clamshell', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2b724fed-2fe1-4c9a-a9a0-40dbbaeabc58', 'Single Leg Split Squat With The Ring (Dumbbell)', 'Legs', 'Dumbbells, Gymnastic Rings', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Using dumbbells requires more stabilization than barbell variations. Lower body strength improves everything from walking to heavy compound lifts. Start with lighter weight to master the movement pattern.', '66811201', '66811201-Dumbbell-Single-Leg-Split-Squat-with-the-Ring_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:29.483269+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout. Keep tension on the target muscles throughout.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 80, 7, 9, TRUE, FALSE, 'split_squat', 'Single Leg Split Squat With The Ring', 'lunge, bulgarian_split_squat, squat', TRUE, 'dumbbell', FALSE, 4, 120, 5, 92, 90, 92, 90),
('2b900260-5aad-4e6d-b7ed-402bc631b887', 'Hip Raise (Smith Machine)', 'Core', 'Smith Machine', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Smith Hip Raise, focusing on your abs. Machine exercises are great for isolating muscles and training to failure safely. Core strength is foundational for athletic performance and injury prevention.', '7561201', '07561201-Smith-Hip-Raise_waist.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Hip Raise. 2. Raise the weight in the prescribed direction for Smith Hip Raise. 3. Lower with control, maintaining tension throughout. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 78, 5, 7, FALSE, TRUE, 'glute_exercise', 'Smith Hip Raise', 'Hip Raise', FALSE, 'smith_machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('2ba50c27-9078-4539-8f16-1cbe4be7cf0a', 'Punch Step Forward', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Punch Step Forward is an explosive exercise that combines cardiovascular training with dynamic stepping movements. Your shoulders work as secondary movers, adding to the training stimulus. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '60281201', '60281201-Punch-Step-Forward-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:35.801913+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Punch Step Forward. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Punch Step Forward', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2ba7a55a-651c-489c-b822-b357ab990e28', 'Frog Stance Deadlift (Barbell)', 'Back', 'Barbell', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'Build leg strength with this hip hinge movement focusing on your hamstrings/glutes. Secondary activation of your glutes, lower back provides additional muscle engagement. Using a barbell provides stability for progressive overload. Lower body strength improves everything from walking to heavy compound lifts.', '96961201', '96961201-Barbell-Frog-Stance-Deadlift-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:24.422129+00', '1. Grip a barbell with hands at the appropriate width for Barbell Frog Stance Deadlift. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'deadlift', 'Frog Stance Deadlift', 'romanian_deadlift, hip_thrust, leg_curl', TRUE, 'barbell', FALSE, 4, 120, 6, 95, 80, 65, 95),
('2ba90113-d18b-4847-ba32-4d0b22e90c89', 'Incline Hammer Press (Dumbbell)', 'Chest', 'Dumbbells, Incline Bench', '{"Chest"}'::text[], '{}'::text[], 'This pressing exercise focuses on your pectorals for improved chest strength and development. The incline angle shifts emphasis toward the upper portion of the target muscles. Using dumbbells requires more stabilization than barbell variations. Chest strength improves pushing power for sports, daily tasks, and other lifts. Control the negative portion for maximum muscle engagement.', '25041201', '25041201-Dumbbell-Incline-Hammer-Press-(female)_Chest.mp4', 'female', FALSE, '2025-12-03 23:26:32.914483+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Incline Hammer Press. 2. Use a hammer/neutral grip with palms facing each other throughout. 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'incline_press', 'Incline Hammer Press', 'bench_press, shoulder_press, chest_fly', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('2bb375a8-07fb-4d9d-9d14-3420c981aa0c', 'Weighted Standing Curl', 'Arms', 'Bodyweight', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. Secondary activation of your forearms provides additional muscle engagement. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. Dedicated arm training builds both strength and muscular definition.', '36261201', '36261201-Weighted-Standing-Curl-(female)_Forearms.mp4', 'female', FALSE, '2025-12-03 23:26:40.037451+00', '1. Stand tall with your feet firmly planted. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps with control before resting. Focus on the mind-muscle connection.', 'Curl', 'Pull', NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'bicep_curl', 'Weighted Standing Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('2bda0a5e-8188-4c8c-b10a-6f4767419eeb', 'Upright Row (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Side Delts"}'::text[], '{"Traps","Front Delts"}'::text[], 'Build stronger shoulders with this rowing movement focusing on your delts. You''ll also feel your traps working to support the movement. Using dumbbells requires more stabilization than barbell variations. Strong shoulders improve overhead strength and support nearly all upper body movements.', '4371201', '04371201-Dumbbell-Upright-Row_Shoulders-FIX.mp4', 'male', FALSE, '2025-12-03 23:26:24.307972+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Upright Row. 2. Pull the weight straight up along your body, leading with your elbows. 3. Raise until elbows reach shoulder height, then lower with control. 4. Repeat for the prescribed number of repetitions. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 82, 7, 9, TRUE, FALSE, 'upright_row', 'Upright Row', 'lateral_raise, shoulder_press, shrug', TRUE, 'dumbbell', FALSE, 4, 120, 4, 92, 90, 92, 90),
('2bee4ada-5fda-4ea6-a2c7-137b397647b2', 'Seated Woodchopper (Chair)', 'Core', 'Chair', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Seated Woodchopper On A Chair targets your obliques through a movement motion, building rotational core strength. Being seated provides stability, allowing you to focus on the working muscles. Core strength is foundational for athletic performance and injury prevention.', '81991201', '81991201-Sitting-Woodchopper-on-a-Chair-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Repeat for the prescribed number of repetitions. Focus on maintaining proper breathing throughout. Works well for obliques activation.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 35, 9, 8, TRUE, TRUE, 'woodchop', 'Seated Woodchopper On A Chair', 'russian_twist, pallof_press, cable_crunch', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('2bfdfaa3-0723-4abe-baa2-5a12a46d5105', 'High Knee Tap', 'Legs', 'Bodyweight', '{"Hip Flexors"}'::text[], '{"Quads","Calves"}'::text[], 'The High Knee Tap is an explosive exercise that combines cardiovascular training with dynamic movement movements. Secondary activation of your hip flexors provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '60951201', '60951201-High-Knee-Tap-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:33.960339+00', '1. Set up in the starting position for High Knee Tap. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'high_knees', 'High Knee Tap', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('2c078827-54ee-4eef-afa6-58592dd00423', 'Lying Floor Row Hold With Bent Knee', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Lying Floor Row Hold With Bent Knee is a rowing exercise that builds thickness in your upper back. Your biceps, rear delts work as secondary movers, adding to the training stimulus. The lying position provides back support and helps isolate the target muscles. No equipment needed—your body provides all the resistance. Back development is crucial for pulling strength and overall upper body function.', '90291201', '90291201-Lying-Floor-Row-Hold-with-Bent-Knee_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:27.805708+00', '1. Position yourself on the floor for Lying Floor Row Hold With Bent Knee. 2. Lie down in the appropriate position for Lying Floor Row Hold With Bent Knee. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Hold the position for the prescribed time, maintaining tension.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Floor Row Hold With Bent Knee', 'squat, leg_extension, lunge', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('2c0b9e96-b50c-4a7a-982a-8d22b1aa7e03', 'Standing Diagonal Punch - Alternating', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Shoulders"}'::text[], 'The Standing Alternating Diagonal Punch is a core movement exercise that primarily targets your full body. You''ll also feel your shoulders working to support the movement. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '100641201', '100641201-Standing-Alternating-Diagonal-Punch-(female)_Wais.mp4', 'female', FALSE, '2025-12-03 23:26:38.285955+00', '1. Begin in a standing position with good posture. 2. Alternate between sides/arms/legs with each repetition. 3. Repeat for the prescribed number of repetitions. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'boxing', 'Standing Diagonal Punch - Alternating', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2c1c2dd9-0682-40e4-aca5-ff5a06fc5241', 'Standing Front Raise - Neutral Grip (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'This raising exercise works your front delts for improved shoulder strength and aesthetics. Performing this standing challenges your balance and core engagement. Using dumbbells requires more stabilization than barbell variations. Strong shoulders improve overhead strength and support nearly all upper body movements.', '98581201', '98581201-Dumbbell-Standing-Neutral-Grip-Front-Raises_Should.mp4', 'male', FALSE, '2025-12-03 23:26:24.577164+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Standing Neutral Grip Front Raises. 2. Stand tall with your feet firmly planted. 3. Use a neutral grip with palms facing each other. 4. Raise the weight in front of you to shoulder height. 5. Lower with control, maintaining tension throughout. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 84, 5, 7, FALSE, TRUE, 'front_raise', 'Standing Front Raise - Neutral Grip', 'Standing Front Raises - Neutral Grip', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('2c1cf2a6-1fe0-4ffa-a9f1-ed6eb2d03ce5', 'Seated Chest Fly (Cable)', 'Chest', 'Cables', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Build a stronger chest with this flying movement that develops pressing power. The front delts assist throughout the movement, making this a well-rounded exercise. Being seated provides stability, allowing you to focus on the working muscles. The cable setup allows you to adjust the angle of resistance. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '97481201', '97481201-Cable-Seated-Chest-Fly-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:32.054831+00', '1. Adjust the cable machine to the correct height and attachment for Cable Seated Chest Fly. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. With a slight bend in your elbows, move the weight in a wide arc. 4. Squeeze your chest muscles at the center/top of the movement. 5. Return with control, feeling the stretch at the bottom. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'chest_fly', 'Seated Chest Fly', 'bench_press, incline_press, push_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('2c2bcf45-54ed-4be3-9855-59db0970c6bb', 'Bent Knee Lying Twist (Stability Ball)', 'Core', 'Stability Ball', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Build a stronger core with the Bent Knee Lying Twist (stability Ball), focusing on your abs. The abs assist throughout the movement, making this a well-rounded exercise. The lying position provides back support and helps isolate the target muscles. The stability ball adds an instability challenge that activates more stabilizer muscles. A strong core improves posture, protects your spine, and enhances all other lifts.', '1311201', '01311201-Bent-knee-Lying-Twist-(On-Stability-Ball)_Waist-FI.mp4', 'female', FALSE, '2025-12-03 23:26:31.347577+00', '1. Position the stability ball as needed for Bent Knee Lying Twist. 2. Lie down in the appropriate position for Bent Knee Lying Twist. 3. Rotate your torso through the movement pattern for Bent Knee Lying Twist. 4. Control the rotation in both directions—avoid using momentum. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 42, 5, 7, FALSE, TRUE, 'russian_twist', 'Bent Knee Lying Twist', 'squat, leg_extension, lunge', FALSE, 'stability_ball', FALSE, 3, 60, 2, 70, 88, 95, 65),
('2c35823c-b584-4697-bba4-9d66d9709df9', 'Straight Arm Pulldown - Rope (Cable)', 'Back', 'Cables', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'The Cable Straight Arm Pulldown (with Rope Attachment) is a pulling exercise that targets your latissimus dorsi for a wider back. Cables provide constant tension throughout the full range of motion. Back development is crucial for pulling strength and overall upper body function.', '82971201', '82971201-Cable-Straight-Arm-Pulldown-(with-rope-attachment).mp4', 'male', FALSE, '2025-12-03 23:26:23.987963+00', '1. Adjust the cable machine to the correct height and attachment for Cable Straight Arm Pulldown. 2. Pull the bar/handle down toward your upper chest. 3. Drive your elbows down and back, squeezing your lats. 4. Control the weight back up without letting it yank your arms. 5. Repeat for the prescribed number of repetitions. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Straight Arm Pulldown', 'pull_up, bent_over_row, cable_row, face_pull', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('2c3764d5-5276-4e78-af93-85eaa86bc63b', 'Russian Twist', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'This twisting movement focuses on your obliques for a complete core workout. Secondary activation of your abs provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '6871201', '06871201-Russian-Twist_waist.mp4', 'male', FALSE, '2025-12-03 23:26:29.61214+00', '1. Rotate your torso through the movement pattern for Russian Twist. 2. Control the rotation in both directions—avoid using momentum. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'russian_twist', 'Russian Twist', 'crunch, plank, leg_raise, wood_chop', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('2c41bdb3-fbc6-4bf2-98f2-12f787b89d0a', 'Seated Lotus Pose Twist', 'Core', 'Bodyweight', '{"Glutes","Hamstrings"}'::text[], '{"Abs"}'::text[], 'Work your side abdominals with this twisting exercise that strengthens your obliques. Secondary activation of your abs provides additional muscle engagement. The seated position helps isolate the target muscles by removing momentum. Core strength is foundational for athletic performance and injury prevention.', '61661201', '61661201-Sitting-Lotus-Pose-Twist-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:37.756436+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Rotate your torso through the movement pattern for Seated Lotus Pose Twist. 3. Control the rotation in both directions—avoid using momentum. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'russian_twist', 'Seated Lotus Pose Twist', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('2c5738ed-fc65-4a83-8560-9d321efcc887', 'Reverse Plank', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Build a stronger back with this stabilization movement targeting your abs. You''ll also feel your shoulders, lower back working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Back development is crucial for pulling strength and overall upper body function.', '8671201', '08671201-Reverse-plank_Back.mp4', 'male', FALSE, '2025-12-03 23:26:24.941834+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Continue for your target rep count, maintaining good form throughout. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Reverse Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('2c5c5d42-15a9-4050-9463-d3b22b61c749', 'Kickback (Dumbbell)', 'Arms', 'Dumbbells', '{"Triceps"}'::text[], '{"Rear Delts"}'::text[], 'Build stronger triceps with this kicking exercise for bigger arms. Secondary activation of your hamstrings provides additional muscle engagement. Dumbbells allow each arm to work independently, helping correct imbalances. Dedicated arm training builds both strength and muscular definition.', '3331201', '03331201-Dumbbell-Kickback_Upper-Arms.mp4', 'male', FALSE, '2025-12-03 23:26:26.146796+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Kickback. 2. Keep your upper arm stationary and extend your forearm back. 3. Squeeze at full extension, then return with control. 4. Continue for your target rep count, maintaining good form throughout. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 62, 5, 7, FALSE, TRUE, 'tricep_kickback', 'Kickback', 'lat_pulldown, bent_over_row, pull_up', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('2c7b7f5b-0ab4-421e-89c0-ee8ea363fbc9', 'Seated Crunch - Hand on Pad (Machine)', 'Core', 'Machine', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Lever Seated Crunch (hands Pad), focusing on your abs. Your hip flexors work as secondary movers, adding to the training stimulus. Being seated provides stability, allowing you to focus on the working muscles. The machine guides your movement path for safer, more controlled repetitions. Core strength is foundational for athletic performance and injury prevention.', '70181201', '70181201-Lever-Seated-Crunch-(hands-pad)-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:34.724336+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Seated Crunch. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Curl your shoulders off the floor by contracting your abs. 4. Don''t pull on your neck—focus on the abdominal contraction. 5. Lower with control, maintaining some tension. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'crunch', 'Lever Seated Crunch', 'leg_raise, plank, russian_twist, v_up', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('2c8081bb-4bb5-458d-854a-9af23e9cfd35', 'Rear Lateral Raise (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'The Dumbbell Rear Lateral Raise is a raising exercise that targets your rear delts for shoulder development. Dumbbells allow each arm to work independently, helping correct imbalances. Strong shoulders improve overhead strength and support nearly all upper body movements.', '3801201', '03801201-Dumbbell-Rear-Lateral-Raise_Shoulders-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:22.536005+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Rear Lateral Raise. 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Repeat for the prescribed number of repetitions. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'lateral_raise', 'Rear Lateral Raise', 'shoulder_press, front_raise, rear_delt', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('2c84e56a-56b5-442a-9df0-2051040d7eeb', 'Seated Back Shift', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. The seated position helps isolate the target muscles by removing momentum. Core strength is foundational for athletic performance and injury prevention. Keep your core engaged throughout the exercise.', '81211201', '81211201-Seated-Back-Shift-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:36.581585+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Set up in the starting position for Seated Back Shift. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'back_exercise', 'Seated Back Shift', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2c8de3dc-ac74-48ad-97f0-61406f65ff01', 'Side To Side Slam (Medicine Ball)', 'Full Body', 'Medicine Ball', '{"Full Body"}'::text[], '{}'::text[], 'A challenging plyometric exercise, the Medicine Ball Side To Side Slam builds reactive power and improves conditioning. Great for improving athletic performance, burning calories, and building conditioning.', '76131201', '76131201-Medicine-Ball-Side-to-Side-Slam-(male)_Plyometrics.mp4', 'male', FALSE, '2025-12-03 23:26:23.172397+00', '1. Hold a medicine ball at the appropriate position for Medicine Ball Side To Side Slam. 2. Set up in the starting position for Medicine Ball Side To Side Slam. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Medicine Ball Side To Side Slam', 'squat, bench_press, deadlift', FALSE, 'medicine_ball', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2c925941-b7c4-40cf-bf2b-da1fefe58b3f', 'Half Kneeling External Rotation Press (Cable)', 'Shoulders', 'Cables', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'The Cable Half Kneeling External Rotation Press is a pressing exercise that targets your rotator cuff for shoulder development. Kneeling helps eliminate lower body momentum from the movement. Cable resistance creates smooth, continuous muscle engagement. Strong shoulders improve overhead strength and support nearly all upper body movements.', '88791201', '88791201-Cable-Half-Kneeling-External-Rotation-Press-(male).mp4', 'male', FALSE, '2025-12-03 23:26:26.271124+00', '1. Adjust the cable machine to the correct height and attachment for Cable Half Kneeling External Rotation Press. 2. Get into a half-kneeling position (one knee down, opposite foot forward). 3. Start with the weight at shoulder level. 4. Press directly overhead until your arms are fully extended. 5. Lower back to shoulder level with control. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 80, 7, 8, TRUE, TRUE, 'external_rotation', 'Half Kneeling External Rotation Press', 'squat, bench_press, deadlift', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('2cac9233-7958-4ed1-920c-ae000ed3601c', 'Straight Back Stiff Leg Deadlift (Band)', 'Legs', 'Resistance Band', '{"Hamstrings"}'::text[], '{"Glutes","Lower Back"}'::text[], 'The Band Straight Back Stiff Leg Deadlift is a lower body hip hinge exercise that targets your hamstrings/glutes. Your glutes, lower back work as secondary movers, adding to the training stimulus. Resistance bands provide accommodating resistance that increases through the range of motion. Lower body strength improves everything from walking to heavy compound lifts.', '10231201', '10231201-Band-straight-back-stiff-leg-deadlift_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:21.732034+00', '1. Secure the resistance band appropriately for Band Straight Back Stiff Leg Deadlift. 2. Push your hips back, lowering the weight along your legs with a flat back. 3. Lower until you feel a stretch in your hamstrings. 4. Drive hips forward to stand, squeezing glutes at the top. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 90, 7, 8, TRUE, TRUE, 'romanian_deadlift', 'Straight Back Stiff Leg Deadlift', 'deadlift, leg_curl, hip_thrust', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50);
INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('2caed12e-aa0c-4385-bcbf-3025e0838740', 'Kneeling Upper Back Rotation', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger back with this rotation movement targeting your core. The kneeling position adds a core stability challenge. No equipment needed—your body provides all the resistance. A strong back improves posture, prevents injury, and balances pressing movements.', '73141201', '73141201-Kneeling-Upper-Back-Rotation-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:34.487002+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Rotate your torso through the movement pattern for Kneeling Upper Back Rotation. 3. Control the rotation in both directions—avoid using momentum. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_exercise', 'Kneeling Upper Back Rotation', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2cb5fe5b-eb35-47c4-a539-7ad1eb825ac3', 'Side Step Row', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'A challenging plyometric exercise, the Side Step Row builds reactive power and improves conditioning. You''ll also feel your quads working to support the movement. Plyometric training builds explosive power that transfers to sports and daily activities.', '86321201', '86321201-Side-Step-Row-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:26.93819+00', '1. Set up a box or step platform at the appropriate height. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Continue for your target rep count, maintaining good form throughout. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'general_exercise', 'Side Step Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2cc6a1b1-43ec-4531-ac74-c35c30a59a18', 'Duck Walk', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Elevate your training with this stepping exercise that develops speed, power, and coordination. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '84151201', '84151201-Duck-Walk-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:32.624497+00', '1. Set up in the starting position for Duck Walk. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'walking', 'Duck Walk', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2cce835c-2ba5-428f-8bd6-257942ec2736', 'Top Bottom Punch Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'A challenging plyometric exercise, the Top Bottom Punch Squat builds reactive power and improves conditioning. You''ll also feel your glutes, hamstrings working to support the movement. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '71641201', '71641201-Top-Bottom-Punch-Squat-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.623429+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Maintain consistent tempo throughout the set. This variation specifically emphasizes the quads.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Top Bottom Punch Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2cd20097-4ca7-4c86-9919-873a54073e2b', 'Snatch Grip Deadlift (Barbell)', 'Back', 'Barbell', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'The Barbell Snatch Grip Deadlift is a lower body hip hinge exercise that targets your hamstrings/glutes. Secondary activation of your glutes, lower back provides additional muscle engagement. Using a barbell provides stability for progressive overload. Leg training boosts metabolism and builds functional, real-world strength.', '72381201', '72381201-Barbell-Snatch-grip-Deadlift-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:23.586683+00', '1. Grip a barbell with hands at the appropriate width for Barbell Snatch Grip Deadlift. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'deadlift', 'Snatch Grip Deadlift', 'romanian_deadlift, hip_thrust, leg_curl', TRUE, 'barbell', FALSE, 4, 120, 6, 95, 80, 65, 95),
('2cdd9443-baf0-4b36-b7bb-2903529eb5c3', 'Quick Feet', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Glutes","Hamstrings","Quads"}'::text[], 'This cardio exercise keeps your heart rate elevated for improved cardiovascular fitness. Cardiovascular exercise improves heart health, endurance, and helps manage weight. Quality repetitions are more important than quantity.', '54941201', '54941201-Quick-Feet-(VERSION-2)-(female)_Cardio_.mp4', 'female', FALSE, '2025-12-03 23:26:35.936279+00', '1. Set up in the starting position for Quick Feet. 2. Execute the movement with proper form, focusing on your cardio. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Quick Feet', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2ce11f03-8bac-4608-87b0-f298671d1203', 'Seated Core Tight Rotation', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This rotation movement focuses on your obliques for a complete core workout. Being seated provides stability, allowing you to focus on the working muscles. Core strength is foundational for athletic performance and injury prevention.', '69681201', '69681201-Sitting-Core-Tight-Rotation-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:37.628647+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Rotate your torso through the movement pattern for Seated Core Tight Rotation. 3. Control the rotation in both directions—avoid using momentum. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'core_exercise', 'Seated Core Tight Rotation', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2cf32b5b-d41f-4e8b-80be-a4e449875263', 'Standing Back Rotation Stretch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Standing Back Rotation Stretch provides a deep stretch for your back, ideal for recovery and mobility work. Performing this standing challenges your balance and core engagement. Include this in your routine for better mobility and reduced muscle tension.', '43161201', '43161201-Standing-Back-Rotation-Stretch-(female)_Back-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Begin in a standing position with good posture. 2. Rotate your torso through the movement pattern for Standing Back Rotation Stretch. 3. Control the rotation in both directions—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'stretch_general', 'Standing Back Rotation Stretch', 'stretch_hip, stretch_hamstring, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('2cf41cfe-c74b-439c-a4dd-41898c4f9462', 'Standing Supinated Face Pull - Rope (Cable)', 'Shoulders', 'Cables', '{"Rear Delts"}'::text[], '{"Upper Back","Rotator Cuff"}'::text[], 'Build stronger shoulders with this pulling movement focusing on your rear delts. Your upper back, rotator cuff work as secondary movers, adding to the training stimulus. Performing this standing challenges your balance and core engagement. The cable setup allows you to adjust the angle of resistance. Strong shoulders improve overhead strength and support nearly all upper body movements.', '77441201', '77441201-Cable-Standing-Supinated-Face-Pull-(with-rope)_Sho.mp4', 'male', FALSE, '2025-12-03 23:26:23.586683+00', '1. Adjust the cable machine to the correct height and attachment for Cable Standing Supinated Face Pull. 2. Stand with feet about shoulder-width apart. 3. Use an underhand (supinated) grip with palms facing up/toward you. 4. Pull the rope toward your face, separating your hands as you pull. 5. Squeeze your rear delts and upper back at peak contraction. 6. Return with control, maintaining cable tension. 7. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 84, 7, 8, TRUE, TRUE, 'face_pull', 'Standing Supinated Face Pull', 'rear_delt_fly, bent_over_row, lateral_raise', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('2cfea7a5-420a-48a0-ab27-1c3eaed7dc88', 'Seated Thoracic Rotation (Chair) - Alternating', 'Core', 'Chair', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Seated Alternate Thoracic Rotation On A Chair, focusing on your core. Being seated provides stability, allowing you to focus on the working muscles. Core strength is foundational for athletic performance and injury prevention.', '87881201', '87881201-Seated-Alternate-Thoracic-Rotation-on-a-Chair-(mal.mp4', 'male', FALSE, '2025-12-03 23:26:27.263406+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Rotate your torso through the movement pattern for Seated Alternate Thoracic Rotation On A Chair. 4. Control the rotation in both directions—avoid using momentum. 5. Alternate between sides/arms/legs with each repetition. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 37, 7, 8, TRUE, TRUE, 'spinal_stretch', 'Seated Thoracic Rotation On A Chair - Alternating', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2d10fbc2-1f7a-4772-8edf-57a22cfaccaa', 'Squat Side Pendulum Leg', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic squatting movement gets your heart rate up while developing explosive strength. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '76561201', '76561201-Squat-Side-Pendulum-Leg-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:38.285955+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Focus on squeezing the target muscle at peak contraction. Include this in your plyometrics training.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Squat Side Pendulum Leg', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2d1cceda-0445-4d77-9c81-2f233de28aba', 'Seated Under Ankle Tap (Against Wall) - Alternating', 'Full Body', 'Wall', '{"Glutes","Hamstrings","Quads"}'::text[], '{"Abs"}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. Great for improving athletic performance, burning calories, and building conditioning.', '89581201', '89581201-Alternate-Ankle-Tap-Under-Sit-agains-Wall-(male)_H.mp4', 'male', FALSE, '2025-12-03 23:26:28.079801+00', '1. Position yourself at the appropriate distance from a wall. 2. Alternate between sides/arms/legs with each repetition. 3. Repeat for the prescribed number of repetitions. Focus on the mind-muscle connection.', 'Hold', 'Static', 'Compound', 'Bilateral (Alternating)', NULL, 2, NULL, 7, 7, NULL, 5, 'Seated (Against Wall)', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 42, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Under Ankle Tap - Alternating', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2d1cf362-247b-4171-a8b5-e32de1cfbba7', 'Bent Knee Back To Side Kick', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Bent Knee Back To Side Kick is a lower body kicking exercise that targets your full body. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '46921201', '46921201-Bent-Knee-Back-to-Side-Kick-(male)_Hips.mp4', 'male', FALSE, '2025-12-03 23:26:28.079801+00', '1. Set up in the starting position for Bent Knee Back To Side Kick. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_exercise', 'Bent Knee Back To Side Kick', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2d207000-cd16-4e3d-a464-0e57fcdf5b59', 'Kneeling Outward Circle Leg On Bench', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'The Kneeling Outward Circle Leg On Bench is a lower body movement exercise that targets your delts. Kneeling helps eliminate lower body momentum from the movement. Lower body strength improves everything from walking to heavy compound lifts.', '98331201', '98331201-Kneeling-Outward-Circle-Leg-on-bench-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:34.487002+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Set up in the starting position for Kneeling Outward Circle Leg On Bench. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_exercise', 'Kneeling Outward Circle Leg On Bench', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2d2a79fd-9d5d-4ebd-8345-796c1f68e11b', 'Seated Single Arm Concentration Curl', 'Arms', 'Bodyweight', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Bodyweight Seated Single Arm Concentration Curl is a curling exercise that isolates your biceps. Your forearms work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. Dedicated arm training builds both strength and muscular definition.', '79281201', '79281201-Bodyweight-Seated-Single-Arm-Concentration-Curl_Up.mp4', 'male', FALSE, '2025-12-03 23:26:29.61214+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions. Keep your shoulders relaxed and away from your ears.', 'Curl', 'Pull', NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 77, 5, 7, FALSE, TRUE, 'concentration_curl', 'Seated Single Arm Concentration Curl', 'tricep_pushdown, tricep_extension, bicep_curl, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('2d2f095f-8dd7-4052-832e-955daf90b406', 'Side Step Fly', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Side Step Fly is an explosive exercise that combines cardiovascular training with dynamic flying movements. The quads assist throughout the movement, making this a well-rounded exercise. Plyometric training builds explosive power that transfers to sports and daily activities.', '55341201', '55341201-Side-Step-Fly_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:24.698781+00', '1. Set up a box or step platform at the appropriate height. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Repeat for the prescribed number of repetitions. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'chest_fly', 'Side Step Fly', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('2d30abdc-a6c1-4693-a133-97b9431bcca0', 'Front Lateral Raise (Band)', 'Shoulders', 'Resistance Band', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'This raising exercise works your lateral delts for improved shoulder strength and aesthetics. Bands are joint-friendly and portable, perfect for any training environment. Shoulder development enhances both performance and upper body aesthetics. This is a great exercise for all fitness levels with proper scaling.', '9771201', '09771201-Band-front-lateral-raise_Shoulders.mp4', 'male', FALSE, '2025-12-03 23:26:22.417605+00', '1. Secure the resistance band appropriately for Band Front Lateral Raise. 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'lateral_raise', 'Front Lateral Raise', 'shoulder_press, front_raise, rear_delt', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('2d3524da-0391-46fa-8a0f-908951a3715b', 'Half Burpee', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Chest","Quads","Core"}'::text[], 'A challenging plyometric exercise, the Half Burpee builds reactive power and improves conditioning. The chest, quads assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '103371201', '103371201-Half-Burpee-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:33.778367+00', '1. Squat down and place hands on the floor, jump feet back to plank. 2. Jump feet back toward hands, then explosively jump up with arms overhead. 3. Land softly and immediately begin the next rep. 4. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection. This exercise is excellent for full body development.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'burpee', 'Half Burpee', 'mountain_climber, box_jump, jumping_jack', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('2d3e0c6a-df38-41f7-9657-d6607a773960', 'Roll Peroneal (single Leg) Side Lying On Floor', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build a stronger core with the Roll Peroneal (single Leg) Side Lying On Floor, focusing on your core. Performing this lying down removes momentum for stricter form. This bodyweight exercise requires no equipment and can be done anywhere. Core strength is foundational for athletic performance and injury prevention.', '54411201', '54411201-Roll-Peroneal-(Single-Leg)-Side-Lying-on-Floor-(fe.mp4', 'female', FALSE, '2025-12-03 23:26:36.38616+00', '1. Position yourself on the floor for Roll PeronealSide Lying On Floor. 2. Lie on your side with your body aligned. 3. Complete all reps on one side, then switch to the other side. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 40, 7, 8, TRUE, TRUE, 'leg_exercise', 'Roll Peroneal Side Lying On Floor', 'Roll Peroneal Side Lying On Floor', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2d4914c0-2493-434d-b4cb-a7b8270603f0', 'Standing Palm To Elbow - Alternating', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{}'::text[], 'This movement exercise focuses on your pectorals for improved chest strength and development. The standing position engages your core for stability. No equipment needed—your body provides all the resistance. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '85571201', '85571201-Standing-Alternating-Palm-to-Elbow-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:38.285955+00', '1. Begin in a standing position with good posture. 2. Alternate between sides/arms/legs with each repetition. 3. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'general_exercise', 'Standing Palm To Elbow - Alternating', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2d568e4b-e665-49ec-8bfe-72ea9c509ce2', 'Inverted Row (TRX)', 'Back', 'TRX', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. Secondary activation of your biceps provides additional muscle engagement. The TRX allows you to adjust difficulty by changing your body angle. Back development is crucial for pulling strength and overall upper body function.', '10801201', '10801201-Suspender-Inverted-Row-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:39.472701+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Inverted Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'general_exercise', 'Suspender Inverted Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('2d5919e0-e1ea-43d1-b515-c69650093026', 'Lat Stretch (Chair)', 'Back', 'Chair', '{"Lats"}'::text[], '{"Lower Back"}'::text[], 'The Lat Stretch With Chair is a stretching exercise that targets your latissimus dorsi for a wider back. Back development is crucial for pulling strength and overall upper body function.', '73071201', '73071201-Lat-Stretch-with-Chair-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:34.603963+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Set up in the starting position for Lat Stretch With Chair. 3. Execute the movement with proper form, focusing on your lats. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 25, 2, 6, FALSE, TRUE, 'lat_stretch', 'Lat Stretch With Chair', 'stretch_hip, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('2d5a9c4c-a585-4335-bcb7-8b143ef25eed', 'Plank Leg Lift Mountain Climber', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Strengthen your midsection with this stabilization movement that works your abs. Your hip flexors, shoulders work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Core strength is foundational for athletic performance and injury prevention.', '98211201', '98211201-Plank-Leg-Lift-Mountain-Climber-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Repeat for the prescribed number of repetitions. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'mountain_climber', 'Plank Leg Lift Mountain Climber', 'crunch, leg_raise, russian_twist, dead_bug', TRUE, 'bodyweight', TRUE, 3, 60, 4, 70, 88, 95, 65),
('2d612afe-84ad-4561-8e79-e047b929bd4b', 'Skier (Barbell)', 'Shoulders', 'Barbell', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Target your delts with the Barbell Skier, an effective shoulder movement exercise. Using a barbell provides stability for progressive overload. Strong shoulders improve overhead strength and support nearly all upper body movements.', '28171201', '28171201-Barbell-Skier-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:31.133197+00', '1. Grip a barbell with hands at the appropriate width for Barbell Skier. 2. Set up in the starting position for Barbell Skier. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'general_exercise', 'Skier', 'squat, bench_press, deadlift', FALSE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('2d65b017-a15a-4e1a-b11f-1e7f848ef31b', 'Knee To Box Calf Stretch (Plyo Box)', 'Legs', 'Plyo Box', '{"Calves"}'::text[], '{}'::text[], 'This stretch specifically works on your calves, promoting flexibility and reducing muscle tightness. Include this in your routine for better mobility and reduced muscle tension.', '105631201', '105631201-Knee-to-Box-Calf-Stretch-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:28.52454+00', '1. Set up a box or step platform at the appropriate height. 2. Move into the stretch position for Knee To Box Calf Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'calf_stretch', 'Knee To Box Calf Stretch', 'stretch_hip, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('2d79710a-37c3-43d8-9353-31e42682bd72', 'Ring Pull Up (Gymnastic Rings)', 'Back', 'Gymnastic Rings', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'Build lat width and pulling strength with this pulling movement. Secondary activation of your biceps, upper back provides additional muscle engagement. Back development is crucial for pulling strength and overall upper body function.', '55221201', '55221201-Ring-Pull-Up_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:27.263406+00', '1. Pull yourself up by driving your elbows down and back. 2. Continue until your chin clears the bar, then lower with control to a full hang. 3. Continue for your target rep count, maintaining good form throughout. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'pull_up', 'Ring Pull Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'gymnastic_rings', FALSE, 3, 90, 4, 68, 85, 85, 70),
('2d8827cf-0791-4c87-88b9-ed308d913754', 'Step Up Single Leg Balance With Bicep Curl (Dumbbell)', 'Arms', 'Dumbbells, Step Platform', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build stronger quads with this stepping movement that develops leg drive and power. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Using dumbbells requires more stabilization than barbell variations. Strong legs are the foundation for athletic performance and functional fitness.', '16841201', '16841201-Dumbbell-Step-Up-Single-Leg-Balance-with-Bicep-Cur.mp4', 'male', FALSE, '2025-12-03 23:26:21.890719+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Set up a box or step platform at the appropriate height. 3. Step one foot onto the elevated surface. 4. Drive through that foot to lift your body up onto the platform. 5. Step back down with control and repeat. 6. Complete all reps on one side, then switch to the other side. 7. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 67, 7, 8, TRUE, TRUE, 'step_up', 'Step Up Single Leg Balance With Biceps Cur', 'lunge, split_squat, squat', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('2d8e5260-d9f9-4fd1-bded-a8bde7364751', 'Slight Bend Elbow Touch', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{}'::text[], 'This movement exercise focuses on your pectorals for improved chest strength and development. This bodyweight exercise requires no equipment and can be done anywhere. A well-developed chest contributes to upper body strength and aesthetics. A staple exercise that belongs in most training programs. Consistency with this movement will yield noticeable results.', '94811201', '94811201-Slight-Bend-Elbow-Touch-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:37.99429+00', '1. Set up in the starting position for Slight Bend Elbow Touch. 2. Execute the movement with proper form, focusing on your chest. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Slight Bend Elbow Touch', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2d91d564-c490-4861-a8dc-74767c7fc160', 'Bird Dog (Resistance Band)', 'Core', 'Resistance Band', '{"Core"}'::text[], '{"Lower Back","Glutes"}'::text[], 'The Resistance Band Bird Dog is a lower body movement exercise that targets your lower back. Your glutes, abs work as secondary movers, adding to the training stimulus. Resistance bands provide accommodating resistance that increases through the range of motion. Lower body strength improves everything from walking to heavy compound lifts.', '35111201', '35111201-Resistance-Band-Bird-Dog-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.936279+00', '1. Secure the resistance band appropriately for Resistance Band Bird Dog. 2. Set up in the starting position for Resistance Band Bird Dog. 3. Execute the movement with proper form, focusing on your lower back. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'bird_dog', 'Bird Dog', 'dead_bug, plank, back_extension', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('2d9514f8-9ac6-44fa-aef3-6aabaa5b69f7', 'Lying Down Hip Internal External Rotation', 'Shoulders', 'Bodyweight', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'The Lying Down Hip Internal External Rotation is a rotation exercise that targets your rotator cuff for shoulder development. The lying position provides back support and helps isolate the target muscles. No equipment needed—your body provides all the resistance. Strong shoulders improve overhead strength and support nearly all upper body movements.', '84901201', '84901201-Lying-Down-Hip-Internal-External-Rotation-(female).mp4', 'female', FALSE, '2025-12-03 23:26:35.133808+00', '1. Lie down in the appropriate position for Lying Down Hip Internal External Rotation. 2. Rotate your torso through the movement pattern for Lying Down Hip Internal External Rotation. 3. Control the rotation in both directions—avoid using momentum. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'external_rotation', 'Lying Down Hip Internal External Rotation', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2d9524a0-0c7e-4c77-9b8b-17d66e92e881', 'Side Lunge Rock (advanced)', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Inner Thighs"}'::text[], 'Build stronger quads with this lunging movement that develops leg drive and power. You''ll also feel your glutes, hamstrings working to support the movement. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts.', '80681201', '80681201-Side-Lunge-Rock-(advanced)-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:36.985772+00', '1. Step to the side, bending that knee while keeping the other leg straight. 2. Push through your front/working leg to return to the starting position. 3. Repeat for the prescribed number of repetitions. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'lunge', 'Side Lunge Rock', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2d983340-fcaa-448c-99e2-904275d8cbf2', 'Kneeling Shoulder Tap', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{}'::text[], 'Build a stronger chest with this movement movement that develops pressing power. The kneeling position adds a core stability challenge. This bodyweight exercise requires no equipment and can be done anywhere. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '45061201', '45061201-Kneeling-Shoulder-Tap_Chest.mp4', 'male', FALSE, '2025-12-03 23:26:20.392006+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Set up in the starting position for Kneeling Shoulder Tap. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Kneeling Shoulder Tap', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2da9a2a5-bef6-422b-a2ec-865e7b1c0b08', 'Leg Raise With Head Up - Alternating', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this raising movement that works your abs. Secondary activation of your hip flexors provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Core strength is foundational for athletic performance and injury prevention.', '42731201', '42731201-Alternate-Leg-Raise-with-Head-up-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Keeping legs mostly straight, raise them toward the ceiling. 2. Lower with control, stopping just before touching down. 3. Alternate between sides/arms/legs with each repetition. 4. Complete all reps with control before resting. Start with lighter weight to perfect your form.', NULL, 'Static', 'Compound', 'Bilateral (Alternating)', NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Leg Raise With Head Up - Alternating', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('2daa0c5e-6d1c-4663-9a37-e3aac2811998', 'Incline Fly (Cable)', 'Chest', 'Cables', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'The Cable Incline Fly is a flying exercise that targets your chest muscles. The front delts assist throughout the movement, making this a well-rounded exercise. Using an incline changes the angle of resistance for varied muscle recruitment. The cable setup allows you to adjust the angle of resistance. A well-developed chest contributes to upper body strength and aesthetics.', '1711201', '01711201-Cable-Incline-Fly_Chest-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:22.536005+00', '1. Adjust the cable machine to the correct height and attachment for Cable Incline Fly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 83, 5, 7, FALSE, TRUE, 'chest_fly', 'Incline Fly', 'bench_press, incline_press, push_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('2db024a4-59d9-4988-8a3d-75af3106187c', 'Decline Triceps Extension (Dumbbell)', 'Arms', 'Dumbbells, Decline Bench', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'Build stronger triceps with this extension exercise for bigger arms. Declining shifts the emphasis to hit the muscles from a different angle. Dumbbells allow each arm to work independently, helping correct imbalances. Dedicated arm training builds both strength and muscular definition.', '26731201', '26731201-Dumbbell-Decline-Triceps-Extension-(female)_Upper-.mp4', 'female', FALSE, '2025-12-03 23:26:32.735372+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Decline Triceps Extension. 2. Extend at the elbow until your arm is straight, squeezing the tricep. 3. Lower with control, keeping your upper arm stationary. 4. Continue for your target rep count, maintaining good form throughout. Focus on maintaining proper breathing throughout.', 'Push', NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 95, 5, 7, FALSE, TRUE, 'tricep_extension', 'Decline Triceps Extension', 'tricep_pushdown, close_grip_bench', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('2dbe2229-07c7-416e-bf6d-1895975e0670', 'Supine Reverse Fly (Cable)', 'Shoulders', 'Cables', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'This flying exercise works your rear delts for improved shoulder strength and aesthetics. You''ll also feel your upper back working to support the movement. The lying position provides back support and helps isolate the target muscles. The cable setup allows you to adjust the angle of resistance. Strong shoulders improve overhead strength and support nearly all upper body movements.', '2401201', '02401201-Cable-Supine-Reverse-Fly_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:23.987963+00', '1. Adjust the cable machine to the correct height and attachment for Cable Supine Reverse Fly. 2. Lie face up (supine position) for Cable Supine Reverse Fly. 3. With a slight bend in your elbows, move the weight in a wide arc. 4. Squeeze your chest muscles at the center/top of the movement. 5. Return with control, feeling the stretch at the bottom. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'rear_delt', 'Supine Reverse Fly', 'bench_press, incline_bench_press, push_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('2dd3ce0b-971c-4bae-b823-740f8f3e3cfa', 'Hip Thrust (Bench, Barbell)', 'Legs', 'Barbell', '{"Glutes"}'::text[], '{"Hamstrings","Core"}'::text[], 'This thrusting exercise isolates your glutes for improved hip strength and power. You''ll also feel your hamstrings working to support the movement. Using a barbell provides stability for progressive overload. Strong legs are the foundation for athletic performance and functional fitness.', '22161201', '22161201-Barbell-Hip-Thrust-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:31.013316+00', '1. Grip a barbell with hands at the appropriate width for Barbell Hip Thrust. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Continue for your target rep count, maintaining good form throughout. Keep your core engaged for stability.', 'Hip Extension', 'Push', 'Compound', 'Bilateral', NULL, 3, NULL, 7, 8, NULL, 5, 'Seated/Supported', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 74, 7, 8, TRUE, TRUE, 'hip_thrust', 'Hip Thrust', 'glute_bridge, romanian_deadlift, leg_curl', TRUE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('2dd7c25d-4174-4e2a-a768-53bd64b7491a', 'Twisting Crunch Shin Touch', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Work your side abdominals with this crunching exercise that strengthens your obliques. Secondary activation of your hip flexors provides additional muscle engagement. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention.', '105821201', '105821201-Twisting-Crunch-Shin-Touch-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:21.732034+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Repeat for the prescribed number of repetitions. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 62, 5, 7, FALSE, TRUE, 'crunch', 'Twisting Crunch Shin Touch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('2df02ede-aeb8-4e59-80ee-4522ce84f04b', 'Seated Single Leg Knee Extension', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Seated Single Leg Knee Extension is a extension exercise that primarily loads your quadriceps. Being seated provides stability, allowing you to focus on the working muscles. Strong legs are the foundation for athletic performance and functional fitness.', '105371201', '105371201-Seated-Single-Leg-Knee-Extension-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:21.608253+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Extend your legs until straight, squeezing your quads at the top. 3. Lower with control back to the starting position. 4. Complete all reps on one side, then switch to the other side. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 67, 5, 7, FALSE, TRUE, 'leg_extension', 'Seated Single Leg Knee Extension', 'squat, leg_press, lunge', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('2df493dd-ba85-40ab-bcc9-6f84a13a9c59', 'Half Push Up Max Rep', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pushing exercise focuses on your pectorals for improved chest strength and development. Your triceps, front delts work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Chest strength improves pushing power for sports, daily tasks, and other lifts. Can be modified for beginners or progressed for advanced athletes.', '90311201', '90311201-Half-Push-up-Max-Rep-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Complete all reps with control before resting. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Half Push Up Max Rep', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2e09f95e-eff9-4ddc-a19c-68dba1a55b84', 'Clean And Push Press (Kettlebell)', 'Full Body', 'Kettlebell', '{"Full Body"}'::text[], '{"Shoulders","Quads","Hamstrings"}'::text[], 'Build total body strength and coordination with this multi-joint pressing movement. You''ll also feel your shoulders, legs working to support the movement. Kettlebells are excellent for building functional, real-world strength. Full body exercises are time-efficient and build functional, real-world strength.', '88221201', '88221201-Kettlebell-Clean-and-Push-Press-(male)_Weightlifti.mp4', 'male', FALSE, '2025-12-03 23:26:24.422129+00', '1. Select an appropriately weighted kettlebell for Kettlebell Clean And Push Press. 2. Execute the pressing motion for Kettlebell Clean And Push Press, extending through the target muscles. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'clean', 'Clean And Push Press', 'squat, bench_press, deadlift', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('2e0d2eac-84a3-45dd-a8e8-a84310082cc8', 'Lying Floor Abduction Adduction', 'Legs', 'Bodyweight', '{"Inner Thighs"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build leg strength with this movement movement focusing on your adductors. Performing this lying down removes momentum for stricter form. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '52951201', '52951201-Lying-Floor-Abduction-Adduction-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.133808+00', '1. Position yourself on the floor for Lying Floor Abduction Adduction. 2. Lie down in the appropriate position for Lying Floor Abduction Adduction. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'hip_adduction', 'Lying Floor Abduction Adduction', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2e0e1f30-d82b-4bda-933a-4393c7991761', 'Seated Behind Neck Triceps Extension - Close Grip (Barbell)', 'Arms', 'Barbell, Flat Bench', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'Build stronger triceps with this extension exercise for bigger arms. The seated position helps isolate the target muscles by removing momentum. Using a barbell provides stability for progressive overload. Dedicated arm training builds both strength and muscular definition.', '17181201', '17181201-Barbell-Seated-Close-Grip-Behind-Neck-Triceps-Exte.mp4', 'male', FALSE, '2025-12-03 23:26:20.982555+00', '1. Grip a barbell with hands at the appropriate width for Barbell Seated Close Grip Behind Neck Triceps Extension. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Use a close/narrow grip (hands closer than shoulder-width). 4. Extend at the elbow until your arm is straight, squeezing the tricep. 5. Lower with control, keeping your upper arm stationary. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 84, 5, 7, FALSE, TRUE, 'tricep_extension', 'Seated Behind Neck Triceps Extension - Close Grip', 'Seated Behind Neck Triceps Extension - Close Grip', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('2e10d5c2-756e-48a6-972a-6e9ec169b8b9', 'Explosive Dynamic Plank', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Build a stronger core with the Explosive Dynamic Plank, focusing on your abs. You''ll also feel your shoulders, lower back working to support the movement. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention.', '78591201', '78591201-Explosive-Dynamic-Plank-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:27.805708+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Perform the concentric (lifting) phase explosively with maximum effort. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Explosive Dynamic Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('2e328c27-e05e-465b-9ed6-f05d94ff25da', 'Lying Raised Shoulders Windshield Wiper Leg Extens', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This raising exercise engages your core for improved core stability and strength. The lying position provides back support and helps isolate the target muscles. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '78531201', '78531201-Lying-Raised-Shoulders-Windshield-Wiper-Leg-Extens.mp4', 'male', FALSE, '2025-12-03 23:26:23.466497+00', '1. Lie down in the appropriate position for Lying Raised Shoulders Windshield Wiper Leg Extens. 2. Set up in the starting position for Lying Raised Shoulders Windshield Wiper Leg Extens. 3. Execute the movement with proper form, focusing on your core. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'shoulder_exercise', 'Lying Raised Shoulders Windshield Wiper Leg Extens', 'lateral_raise, shoulder_press, front_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('2e3aa612-50e2-4cb3-8ff2-5296b7ec549c', 'Serratus Wall Slide (Resistance Band)', 'Shoulders', 'Resistance Band, Wall', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Build a stronger back with this movement movement targeting your rotator cuff. The upper back assist throughout the movement, making this a well-rounded exercise. Bands are joint-friendly and portable, perfect for any training environment. A strong back improves posture, prevents injury, and balances pressing movements.', '50241201', '50241201-Resistance-Band-Serratus-Wall-Slide_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:23.056255+00', '1. Secure the resistance band appropriately for Resistance Band Serratus Wall Slide. 2. Position yourself at the appropriate distance from a wall. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 47, 7, 8, TRUE, TRUE, 'serratus', 'Serratus Wall Slide', 'squat, bench_press, deadlift', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('2e3dcc0b-5666-47f9-9c96-fe98b7ec72e1', 'Sittiing W Pose', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This stretch specifically works on your full body, promoting flexibility and reducing muscle tightness. Flexibility work like this enhances performance and prevents stiffness. This variation is excellent for building mind-muscle connection.', '63231201', '63231201-Sittiing-W-Pose-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:37.628647+00', '1. Move into the stretch position for Sittiing W Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 50, 2, 6, FALSE, TRUE, 'general_exercise', 'Sittiing W Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('2e480e78-103d-401e-a297-10105a5e1333', 'Calf Raise Clap', 'Legs', 'Bodyweight', '{"Calves"}'::text[], '{}'::text[], 'Build stronger calves with this targeted raising exercise. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '56191201', '56191201-Calf-Raise-Clap-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:32.166461+00', '1. Lower your heels below the platform to get a full stretch. 2. Rise up onto your toes as high as possible, squeezing your calves. 3. Lower with control and repeat. 4. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection. Works well for calves activation.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'calf_raise', 'Calf Raise Clap', 'standing_calf_raise, seated_calf_raise, tibialis_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('2e5faacf-4f36-4ee0-98c4-06e624dae463', 'Crunch Back', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this crunching movement that works your abs. Your hip flexors work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '66261201', '66261201-Crunch---Back-(WRONG-RIGHT)-(female)_.mp4', 'female', FALSE, '2025-12-03 23:26:32.501166+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Repeat for the prescribed number of repetitions. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Crunch Back', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('2e64f6dc-506f-4165-a716-984a3f4336b0', 'Seated Single Leg Hugging Knee Fl (Resistance Band)', 'Legs', 'Resistance Band', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build a stronger core with the Resistance Band Seated Single Leg Hugging Knee Fl, focusing on your core. The seated position helps isolate the target muscles by removing momentum. Bands are joint-friendly and portable, perfect for any training environment. A strong core improves posture, protects your spine, and enhances all other lifts.', '105911201', '105911201-Resistance-Band-Seated-Single-Leg-Hugging-Knee-Fl.mp4', 'male', FALSE, '2025-12-03 23:26:24.307972+00', '1. Secure the resistance band appropriately for Resistance Band Seated Single Leg Hugging Knee Fl. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Complete all reps on one side, then switch to the other side. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 42, 7, 8, TRUE, TRUE, 'leg_exercise', 'Seated Single Leg Hugging Knee Fl', 'squat, leg_extension, lunge', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('2e733a77-85ff-4c5f-be05-f33a30bc1efd', 'Bridge Walk', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'The Bridge Walk is a hip-dominant bridging exercise that targets your glutes. The hamstrings assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '64911201', '64911201-Bridge-Walk-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:24.941834+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Repeat for the prescribed number of repetitions. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'walking', 'Bridge Walk', 'hip_thrust, romanian_deadlift, leg_curl', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2e745773-6a0d-41b9-9df2-a743509173da', 'Seated Chest Press (Machine)', 'Chest', 'Machine', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger chest with this pressing movement that develops pressing power. You''ll also feel your triceps, front delts working to support the movement. Being seated provides stability, allowing you to focus on the working muscles. The fixed path allows you to focus purely on muscular effort. A well-developed chest contributes to upper body strength and aesthetics.', '106711201', '106711201-Lever-Stack-Seated-Chest-Press-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:24.307972+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Stack Seated Chest Press. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 80, 7, 8, TRUE, TRUE, 'bench_press', 'Lever Stack Seated Chest Press', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('2e77b8d7-44a6-48a2-bdfb-4919dfd8dfae', 'Side Squat Step (Kettlebell)', 'Legs', 'Kettlebell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Kettlebell Side Squat Step is a squatting exercise that primarily loads your quadriceps. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. The kettlebell''s offset center of mass increases the stability challenge. Strong legs are the foundation for athletic performance and functional fitness.', '45241201', '45241201-Kettlebell-Side-Squat-Step-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:34.196858+00', '1. Select an appropriately weighted kettlebell for Kettlebell Side Squat Step. 2. Set up a box or step platform at the appropriate height. 3. Push your hips back and bend your knees to lower your body. 4. Keep your chest up and knees tracking over your toes. 5. Drive through your heels to stand back up, squeezing your glutes at the top. 6. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 93, 7, 8, TRUE, TRUE, 'squat', 'Side Squat Step', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('2e7a04c0-7aee-4c5d-80fc-2d14adc0c82b', 'Windmill (Chair)', 'Core', 'Chair', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Windmill On Chair, focusing on your abs. Core strength is foundational for athletic performance and injury prevention.', '66341201', '66341201-Windmill-on-Chair-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:28.52454+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Set up in the starting position for Windmill On Chair. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'windmill', 'Windmill On Chair', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2e80c02a-030c-4860-b230-8b3b620eafad', 'Standing Row Switching Palms', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. Your biceps, rear delts work as secondary movers, adding to the training stimulus. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. A strong back improves posture, prevents injury, and balances pressing movements.', '72221201', '72221201-Standing-Row-Switching-Palms-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:38.870314+00', '1. Begin in a standing position with good posture. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 72, 7, 8, TRUE, TRUE, 'general_exercise', 'Standing Row Switching Palms', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2e9b8eb8-101d-493e-a072-bafa90a0fda0', 'Squat Lunge - Alternating', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Squat Alternating Lunge is a squatting exercise that primarily loads your quadriceps. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '94451201', '94451201-Squat-Alternating-Lunge-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:38.153182+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Repeat for the prescribed number of repetitions. Maintain consistent tempo throughout the set. Include this in your legs training.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Squat Lunge - Alternating', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2ea8381c-acc1-4425-9529-1d827008b6e4', 'Seated Single Arm Row (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. Your biceps, rear delts work as secondary movers, adding to the training stimulus. Being seated provides stability, allowing you to focus on the working muscles. Cables provide constant tension throughout the full range of motion. Back development is crucial for pulling strength and overall upper body function.', '70591201', '70591201-Cable-Seated-Single-Arm-Row-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:32.054831+00', '1. Adjust the cable machine to the correct height and attachment for Cable Seated Single Arm Row. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Complete all reps on one side, then switch to the other side. 7. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 77, 7, 8, TRUE, TRUE, 'dumbbell_row', 'Seated Single Arm Row', 'bent_over_row, lat_pulldown, face_pull', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('2ebf37a0-7ae6-4111-97f9-938bdb15b72d', 'Leg Raise Hip Lift', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Leg Raise Hip Lift is a core raising exercise that primarily targets your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Core strength is foundational for athletic performance and injury prevention.', '18521201', '18521201-Leg-Raise-Hip-Lift_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:34.603963+00', '1. Keeping legs mostly straight, raise them toward the ceiling. 2. Lower with control, stopping just before touching down. 3. Repeat for the prescribed number of repetitions. Maintain a neutral spine throughout. Include this in your core training.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Leg Raise Hip Lift', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('2ec2d36f-6aed-4e85-b7e2-f9a27c60e0af', 'Roll Shoulder Blade Reach Lying On Floor', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Roll Shoulder Blade Reach Lying On Floor is a core movement exercise that primarily targets your core. Performing this lying down removes momentum for stricter form. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '54241201', '54241201-Roll-Shoulder-Blade-Reach-Lying-on-Floor-(female)_.mp4', 'female', FALSE, '2025-12-03 23:26:36.38616+00', '1. Position yourself on the floor for Roll Shoulder Blade Reach Lying On Floor. 2. Lie down in the appropriate position for Roll Shoulder Blade Reach Lying On Floor. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Roll Shoulder Blade Reach Lying On Floor', 'lateral_raise, shoulder_press, front_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2ed95e8f-ffe9-450e-bb67-5a80edb9cb84', 'Over Bench Single Arm Reverse Wrist Curl (Dumbbell)', 'Arms', 'Dumbbells', '{"Forearms"}'::text[], '{}'::text[], 'Build grip strength and forearm size with this curling exercise. You''ll also feel your forearms working to support the movement. Using dumbbells requires more stabilization than barbell variations. Arm strength supports grip, pulling, and pushing in compound movements.', '14411201', '14411201-Dumbbell-Over-Bench-One-Arm-Reverse-Wrist-Curl_For.mp4', 'male', FALSE, '2025-12-03 23:26:25.341124+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting. Engage your stabilizer muscles for better control. Include this in your arms training.', 'Curl', 'Pull', NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 77, 5, 7, FALSE, TRUE, 'wrist_curl', 'Over Bench Single Arm Reverse Wrist Curl', 'hammer_curl, wrist_curl, bicep_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('2edfef21-b5d1-4fc0-8da5-d3976aeb05dd', 'Hammer Press (Stability Ball, Dumbbell)', 'Chest', 'Dumbbells, Stability Ball', '{"Chest"}'::text[], '{"Triceps"}'::text[], 'Target your chest with the Dumbbell Hammer Press On Exercise Ball, an effective pressing movement for upper body strength. You''ll also feel your triceps working to support the movement. Using dumbbells requires more stabilization than barbell variations. A well-developed chest contributes to upper body strength and aesthetics.', '98141201', '98141201-Dumbbell-Hammer-Press-on-Exercise-Ball_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:26.271124+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Hammer Press On Exercise Ball. 2. Use a hammer/neutral grip with palms facing each other throughout. 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 74, 7, 8, TRUE, TRUE, 'squeeze_press', 'Hammer Press On Exercise Ball', 'squat, bench_press, deadlift', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('2eec990a-ce18-41ff-aa6a-e59bf1be8730', 'Forward Bend Back Stretch', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Lower Back"}'::text[], 'The Forward Bend Back Stretch provides a deep stretch for your back, ideal for recovery and mobility work. The shoulders assist throughout the movement, making this a well-rounded exercise. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '89521201', '89521201-Forward-Bend-Back-Stretch-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:25.87243+00', '1. Move into the stretch position for Forward Bend Back Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'back_stretch', 'Forward Bend Back Stretch', 'stretch_hip, stretch_hamstring, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('2eee1f74-4e53-46db-b5f4-179ee5200998', 'Kneeling Reverse Palm Nudges', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Kneeling Reverse Palm Nudges is an arm movement exercise targeting your core. The kneeling position adds a core stability challenge. A versatile bodyweight movement perfect for home or gym training. Arm strength supports grip, pulling, and pushing in compound movements.', '69751201', '69751201-Kneeling-Reverse-Palm-Nudges-(male)_Forearms_.mp4', 'male', FALSE, '2025-12-03 23:26:21.452942+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Set up in the starting position for Kneeling Reverse Palm Nudges. 3. Execute the movement with proper form, focusing on your core. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Kneeling Reverse Palm Nudges', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2ef679f7-ba24-4a0f-b9cd-987965077b52', 'Anti Gravity Press (EZ Bar)', 'Shoulders', 'EZ Bar', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'This pressing exercise works your delts for improved shoulder strength and aesthetics. Using a barbell provides stability for progressive overload. Shoulder development enhances both performance and upper body aesthetics.', '4451201', '04451201-EZ-Barbell-Anti-Gravity-Press_Shoulders-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:28.397686+00', '1. Grip a barbell with hands at the appropriate width for EZ Barbell Anti Gravity Press. 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Continue for your target rep count, maintaining good form throughout. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'shoulder_press', 'EZ Anti Gravity Press', 'EZ Anti Gravity Press', FALSE, 'ez_bar', FALSE, 3, 90, 4, 95, 80, 65, 95),
('2efbaa26-2541-4f82-99e0-620025a13874', 'Worlds Greatest Stretch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Designed to lengthen your full body, the Worlds Greatest Stretch helps improve mobility and prevent stiffness. Include this in your routine for better mobility and reduced muscle tension.', '46331201', '46331201-Worlds-Greatest-Stretch_Stretching.mp4', 'male', FALSE, '2025-12-03 23:26:25.87243+00', '1. Move into the stretch position for Worlds Greatest Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Worlds Greatest Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('2f0d0c6c-f98b-4b61-8a14-e4241e7475a0', 'Woodchopper (TRX)', 'Core', 'TRX', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'This movement movement focuses on your obliques for a complete core workout. The TRX allows you to adjust difficulty by changing your body angle. Building core stability helps with everything from heavy deadlifts to daily activities.', '75001201', '75001201-Suspender-Woodchopper-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:39.623429+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Woodchopper. 2. Set up in the starting position for Suspender Woodchopper. 3. Execute the movement with proper form, focusing on your obliques. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 40, 9, 8, TRUE, TRUE, 'woodchop', 'Suspender Woodchopper', 'russian_twist, pallof_press, cable_crunch', FALSE, 'trx', FALSE, 3, 60, 4, 68, 85, 85, 70),
('2f1d5267-ffc5-439f-b512-6c2e7fd38a31', 'Standing Shrug', 'Back', 'Bodyweight', '{"Traps"}'::text[], '{"Upper Back"}'::text[], 'Build a stronger back with this shrugging movement targeting your traps. Performing this standing challenges your balance and core engagement. No equipment needed—your body provides all the resistance. A strong back improves posture, prevents injury, and balances pressing movements.', '48721201', '48721201-Bodyweight-Standing-Shrug-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:31.475486+00', '1. Begin in a standing position with good posture. 2. Shrug your shoulders straight up toward your ears. 3. Hold briefly at the top, then lower with control. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'shrug', 'Standing Shrug', 'deadlift, bent_over_row, face_pull', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('2f228493-8265-4a46-ad1c-f9cb3ac02f26', 'Ab Coaster Crunch (Machine)', 'Core', 'Machine', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Lever Ab Coaster Crunch, focusing on your abs. Secondary activation of your hip flexors provides additional muscle engagement. The machine guides your movement path for safer, more controlled repetitions. A strong core improves posture, protects your spine, and enhances all other lifts.', '73821201', '73821201-Lever-Ab-Coaster-Crunch-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:23.79417+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Ab Coaster Crunch. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Continue for your target rep count, maintaining good form throughout. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 78, 5, 7, FALSE, TRUE, 'crunch', 'Lever Ab Coaster Crunch', 'leg_raise, plank, russian_twist, v_up', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('2f27713b-ad2c-403c-9e26-329335735ab6', 'Skipping', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'The Bodyweight Skipping is an explosive exercise that combines cardiovascular training with dynamic movement movements. Secondary activation of your calves provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '81851201', '81851201-Bodyweight-Skipping-(VERSION-2)-(female)_Plyometri.mp4', 'female', FALSE, '2025-12-03 23:26:31.475486+00', '1. Set up in the starting position for Bodyweight Skipping. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'skip', 'Skipping', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('2f2c18d6-7cba-47c3-a770-54280e016c7c', 'Front Hop Back Hop', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. No equipment needed—your body provides all the resistance. Develops fast-twitch muscle fibers for quicker, more powerful movements. A staple exercise that belongs in most training programs.', '76441201', '76441201-Front-Hop-Back-Hop-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:27.384461+00', '1. Set up in the starting position for Front Hop Back Hop. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'hop', 'Front Hop Back Hop', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('2f2c1b13-f885-41c3-90f7-1887afd3b663', 'Jumping Single Leg Lunge', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build power and athleticism with this high-intensity lunging exercise that challenges your entire body. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '71611201', '71611201-Jumping-Single-Leg-Lunge-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:34.196858+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Complete all reps on one side, then switch to the other side. 4. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 65, 9, 8, TRUE, TRUE, 'lunge', 'Jumping Single Leg Lunge', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('2f4fd753-d4d2-4fb4-890c-e3b50609a2ad', 'Incline Hammer Press (Kettlebell)', 'Chest', 'Kettlebell, Incline Bench', '{"Chest"}'::text[], '{}'::text[], 'Build a stronger chest with this pressing movement that develops pressing power. The incline angle shifts emphasis toward the upper portion of the target muscles. The kettlebell''s offset center of mass increases the stability challenge. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '68211201', '68211201-Kettlebell-Incline-Hammer-Press_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:23.288245+00', '1. Select an appropriately weighted kettlebell for Kettlebell Incline Hammer Press. 2. Use a hammer/neutral grip with palms facing each other throughout. 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 81, 7, 8, TRUE, TRUE, 'incline_press', 'Incline Hammer Press', 'bench_press, shoulder_press, chest_fly', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('2f533ecd-da13-486b-acdb-fa01a8dd1a59', 'Triceps Pushdown (Resistance Band)', 'Arms', 'Resistance Band, Anchor Point', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This pushing movement isolates your triceps for improved arm development. The band creates increasing tension as it stretches, challenging the lockout. Arm strength supports grip, pulling, and pushing in compound movements. Perfect for including in both strength and hypertrophy programs.', '52681201', '52681201-Resistance-Band-Triceps-Pushdown-(female)_Upper-Ar.mp4', 'female', FALSE, '2025-12-03 23:26:36.266593+00', '1. Secure the resistance band appropriately for Resistance Band Triceps Pushdown. 2. Set up in the starting position for Resistance Band Triceps Pushdown. 3. Execute the movement with proper form, focusing on your triceps. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 55, 5, 7, FALSE, TRUE, 'tricep_pushdown', 'Triceps Pushdown', 'tricep_extension, close_grip_bench, dip', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('2f53b821-53ba-45f9-b80f-1ac2f8124f7a', 'Weighted Bench Dip (Flat Bench)', 'Chest', 'Flat Bench', '{"Lower Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This dipping movement isolates your triceps for improved arm development. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. Arm strength supports grip, pulling, and pushing in compound movements.', '8301201', '08301201-Weighted-Bench-Dip_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:28.71819+00', '1. Lower your body by bending your elbows to about 90 degrees. 2. Push back up until your arms are fully extended. 3. Complete all reps with control before resting. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'dip', 'Weighted Bench Dip', 'bench_press, tricep_pushdown, push_up', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2f56b332-ef3d-46cf-a43a-c7313ebb3f63', 'Burpee Arm Leg Raise - Alternating', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'A challenging plyometric exercise, the Burpee Alternate Arm Leg Raise builds reactive power and improves conditioning. You''ll also feel your hip flexors working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '71841201', '71841201-Burpee-Alternate-Arm-Leg Raise-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:20.392006+00', '1. Squat down and place hands on the floor, jump feet back to plank. 2. Jump feet back toward hands, then explosively jump up with arms overhead. 3. Land softly and immediately begin the next rep. 4. Alternate between sides/arms/legs with each repetition. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'leg_raise', 'Burpee Arm Leg Raise - Alternating', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('2f65ba7b-7dcf-4931-8899-bac5f25eb8e4', 'Single Leg Lateral Hop', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities. This variation is excellent for building mind-muscle connection.', '74551201', '74551201-Single-Leg-Lateral-Hop-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:22.644637+00', '1. Complete all reps on one side, then switch to the other side. 2. Set up in the starting position for Single Leg Lateral Hop. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 45, 9, 8, TRUE, TRUE, 'hop', 'Single Leg Lateral Hop', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('2f65c0bf-9d6f-4186-966c-66ec3ffc8607', 'Shoulder Adduction (Resistance Band)', 'Shoulders', 'Resistance Band', '{"Inner Thighs"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Resistance Band Shoulder Adduction is a movement exercise that develops back strength and muscle. The band creates increasing tension as it stretches, challenging the lockout. Back development is crucial for pulling strength and overall upper body function.', '64371201', '64371201-Resistance-Band-Shoulder-Adduction-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band Shoulder Adduction. 2. Set up in the starting position for Resistance Band Shoulder Adduction. 3. Execute the movement with proper form, focusing on your adductors. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'hip_adduction', 'Shoulder Adduction', 'lateral_raise, shoulder_press, front_raise', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('2f6a2bfb-1c16-4938-8c6d-80c3733bb486', 'Burpee Jump Box', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Chest","Quads","Core"}'::text[], 'Elevate your training with this jumping exercise that develops speed, power, and coordination. The chest, quads assist throughout the movement, making this a well-rounded exercise. Plyometric training builds explosive power that transfers to sports and daily activities.', '87041201', '87041201-Burpee-Jump-Box-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:24.307972+00', '1. Set up a box or step platform at the appropriate height. 2. Squat down and place hands on the floor, jump feet back to plank. 3. Jump feet back toward hands, then explosively jump up with arms overhead. 4. Land softly and immediately begin the next rep. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'burpee', 'Burpee Jump Box', 'mountain_climber, box_jump, jumping_jack', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('2f6d0c05-daa2-4b91-bd8d-0e4c8cdaadd2', 'Bench Press (EZ Bar)', 'Chest', 'EZ Bar, Flat Bench', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Target your chest with the EZ Barbell Bench Press, an effective pressing movement for upper body strength. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. Using a barbell provides stability for progressive overload. A well-developed chest contributes to upper body strength and aesthetics.', '88181201', '88181201-EZ-Barbell-Bench-Press_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:21.995567+00', '1. Load a barbell and set it on a bench rack at the appropriate height. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Complete all reps with control before resting. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'bench_press', 'EZ Bench Press', 'EZ Bench Press', TRUE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('2f7da4ce-7152-49a8-bdc8-0ccb1aa0dd9e', 'Goblet Squat Jump (Kettlebell)', 'Legs', 'Kettlebell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Kettlebell Goblet Squat Jump is a squatting exercise that primarily loads your quadriceps. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Kettlebells are excellent for building functional, real-world strength. Strong legs are the foundation for athletic performance and functional fitness.', '31871201', '31871201-Kettlebell-Goblet-Squat-Jump-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:34.196858+00', '1. Select an appropriately weighted kettlebell for Kettlebell Goblet Squat Jump. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Explode upward from the bottom, jumping as high as possible. 5. Land softly with bent knees and immediately descend into the next rep. 6. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 93, 9, 8, TRUE, TRUE, 'goblet_squat', 'Goblet Squat Jump', 'squat, front_squat, lunge', FALSE, 'kettlebell', FALSE, 3, 60, 4, 75, 88, 88, 78),
('2f81b000-b7af-4b16-a97d-a2cf06ee4daa', 'Bent Over Single Arm Kickback - Neutral Grip (Cable)', 'Arms', 'Cables', '{"Triceps"}'::text[], '{"Rear Delts"}'::text[], 'Build stronger glutes with this kicking movement focused on hip extension. Secondary activation of your hamstrings provides additional muscle engagement. The bent over position requires core engagement to maintain a neutral spine. Cables provide constant tension throughout the full range of motion. Strong legs are the foundation for athletic performance and functional fitness.', '97241201', '97241201-Cable-Bent-Over-Single-Arm-Neutral-Grip-Kickback-w.mp4', 'female', FALSE, '2025-12-03 23:26:31.723232+00', '1. Adjust the cable machine to the correct height and attachment for Cable Bent Over Single Arm Neutral Grip Kickback. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Use a neutral grip with palms facing each other. 4. Keep your upper arm stationary and extend your forearm back. 5. Squeeze at full extension, then return with control. 6. Complete all reps on one side, then switch to the other side. 7. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 55, 5, 7, FALSE, TRUE, 'tricep_kickback', 'Bent Over Single Arm Kickback - Neutral Grip', 'Bent Over Single Arm Kickback - Neutral Grip', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('2f9a5200-770a-4980-9cdb-dac84264e3ea', 'Triceps Dip (Dip Bars)', 'Arms', 'Dip Bars', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This dipping movement isolates your triceps for improved arm development. Secondary activation of your triceps, front delts provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Arm strength supports grip, pulling, and pushing in compound movements.', '8141201', '08141201-Triceps-Dip_Upper-Arms-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:21.608253+00', '1. Lower your body by bending your elbows to about 90 degrees. 2. Push back up until your arms are fully extended. 3. Complete all reps with control before resting. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'dip', 'Triceps Dip', 'bench_press, tricep_pushdown, push_up', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2fa055d3-5c01-4b53-8b40-d2be0c24174c', 'Bicycle', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This stretch specifically works on your obliques, promoting flexibility and reducing muscle tightness. Your abs work as secondary movers, adding to the training stimulus. Flexibility work like this enhances performance and prevents stiffness.', '28381201', '28381201-Bicycle_Pilates_.mp4', 'female', FALSE, '2025-12-03 23:26:31.347577+00', '1. Move into the stretch position for Bicycle. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'cycling', 'Bicycle', 'running, elliptical, rowing_cardio', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2fb74bbb-317d-4820-b4ad-88b16ea83e85', 'Calf Forward Jump', 'Legs', 'Bodyweight', '{"Calves"}'::text[], '{"Glutes"}'::text[], 'A challenging plyometric exercise, the Calf Forward Jump builds reactive power and improves conditioning. Your quads, calves work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '107561201', '107561201-Calf-Forward-Jump-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:32.166461+00', '1. Set up in the starting position for Calf Forward Jump. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'general_exercise', 'Calf Forward Jump', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('2fb7699b-19e9-4e1f-aecc-533e4a95ac1c', 'Seated Reverse Fly (Chair)', 'Shoulders', 'Chair', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'Build stronger shoulders with this flying movement focusing on your rear delts. The upper back assist throughout the movement, making this a well-rounded exercise. The seated position helps isolate the target muscles by removing momentum. Strong shoulders improve overhead strength and support nearly all upper body movements.', '104791201', '104791201-Seated-Reverse-Fly-on-Chair-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:23.586683+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. With a slight bend in your elbows, move the weight in a wide arc. 4. Squeeze your chest muscles at the center/top of the movement. 5. Return with control, feeling the stretch at the bottom. 6. Complete all reps with control before resting. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 57, 5, 7, FALSE, TRUE, 'rear_delt', 'Seated Reverse Fly On Chair', 'bench_press, incline_bench_press, push_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('2fc48608-0493-4aea-81ec-92b88fff8871', 'Bicep Curl - Single Arm (TRX)', 'Arms', 'TRX', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Suspender One Arm Biceps Curl is a curling exercise that isolates your biceps. The forearms assist throughout the movement, making this a well-rounded exercise. Suspension training adds instability, increasing core activation throughout. Dedicated arm training builds both strength and muscular definition.', '11231201', '11231201-Suspender-One-Arm-Biceps-Curl-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:39.472701+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender One Arm Biceps Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 65, 5, 7, FALSE, TRUE, 'bicep_curl', 'Suspender Single Arm Biceps Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'trx', FALSE, 3, 60, 2, 68, 85, 85, 70),
('2fd41933-a8e2-4850-b33f-3ad56b6ded6d', 'Incline Rear Fly (Dumbbell)', 'Shoulders', 'Dumbbells, Incline Bench', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'The Dumbbell Incline Rear Fly is a flying exercise that targets your rear delts for shoulder development. The front delts assist throughout the movement, making this a well-rounded exercise. The incline angle shifts emphasis toward the upper portion of the target muscles. The dumbbell variation provides freedom of movement and greater range of motion. Strong shoulders improve overhead strength and support nearly all upper body movements.', '25001201', '25001201-Dumbbell-Incline-Rear-Fly-(female)_Shoulders.mp4', 'female', FALSE, '2025-12-03 23:26:32.914483+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Incline Rear Fly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'rear_delt', 'Incline Rear Fly', 'incline_bench_press, chest_fly, shoulder_press', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('2fdc1a2a-c9dc-4a99-9a8f-792f4fefbfe7', 'Lying Triceps Extension - Low (Cable)', 'Arms', 'Cables', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'The Cable Lying Triceps Extension (low) targets your triceps through a extension motion. The lying position provides back support and helps isolate the target muscles. The cable setup allows you to adjust the angle of resistance. Arm strength supports grip, pulling, and pushing in compound movements.', '52621201', '52621201-Cable-Lying-Triceps-Extension-(Low)-(female)_Upper.mp4', 'female', FALSE, '2025-12-03 23:26:31.931873+00', '1. Set the cable pulley to the lowest position and attach your preferred handle. 2. Lie down in the appropriate position for Cable Lying Triceps Extension. 3. Extend at the elbow until your arm is straight, squeezing the tricep. 4. Lower with control, keeping your upper arm stationary. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'tricep_extension', 'Lying Triceps Extension', 'tricep_pushdown, close_grip_bench', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('30075aab-642a-4a1c-9660-b640e5abe174', 'Single Arm Triceps Extension On Bench (Dumbbell)', 'Arms', 'Dumbbells', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This extension movement isolates your triceps for improved arm development. Using dumbbells requires more stabilization than barbell variations. Dedicated arm training builds both strength and muscular definition.', '3621201', '03621201-Dumbbell-One-Arm-Triceps-Extension-(on-bench)_Upper-Arms.mp4', 'male', FALSE, '2025-12-03 23:26:23.987963+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Extend at the elbow until your arm is straight, squeezing the tricep. 3. Lower with control, keeping your upper arm stationary. 4. Complete all reps on one side, then switch to the other side. 5. Complete all reps with control before resting. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 79, 5, 7, FALSE, TRUE, 'tricep_extension', 'Single Arm Triceps Extension', 'tricep_pushdown, close_grip_bench', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('301c34d7-d0e6-41e8-8e95-a891d1e9d06c', 'Standing Side Tap Back Tap', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. The standing position engages your core for stability. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities. Focus on controlled form throughout each repetition.', '88641201', '88641201-Standing-Side-Tap-Back-Tap-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:38.870314+00', '1. Begin in a standing position with good posture. 2. Set up in the starting position for Standing Side Tap Back Tap. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'back_exercise', 'Standing Side Tap Back Tap', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3023ec7d-e6c7-4ae5-b777-fa08f0f32770', 'Pulsing Squat Step Back', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Pulsing Squat Step Back is a squatting exercise that primarily loads your quadriceps. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Lower body strength improves everything from walking to heavy compound lifts.', '96341201', '96341201-Pulsing-Squat-Step-Back-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.801913+00', '1. Set up a box or step platform at the appropriate height. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps with control before resting. Keep tension on the target muscles throughout.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'pulse', 'Pulsing Squat Step Back', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('303d1a56-368e-40bf-a6a9-d6ae93040b16', 'Lying Air Cycles', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Hamstrings"}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. The lying position provides back support and helps isolate the target muscles. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '49251201', '49251201-Lying-Air-Cycles-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:35.010404+00', '1. Lie down in the appropriate position for Lying Air Cycles. 2. Set up in the starting position for Lying Air Cycles. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Air Cycles', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('30505d95-7cb5-4263-a9f0-aaf0e1eb4784', 'Decline Bent Arm Pullover (Barbell)', 'Chest', 'Barbell, Decline Bench', '{"Chest","Lower Chest"}'::text[], '{"Lats","Triceps","Traps"}'::text[], 'The Barbell Decline Bent Arm Pullover is a pulling exercise that develops back strength and muscle. Your lats, triceps work as secondary movers, adding to the training stimulus. The decline position targets the lower portion of the muscles more intensely. Using a barbell provides stability for progressive overload. A strong back improves posture, prevents injury, and balances pressing movements.', '341201', '00341201-Barbell-Decline-Bent-Arm-Pullover_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:27.504261+00', '1. Grip a barbell with hands at the appropriate width for Barbell Decline Bent Arm Pullover. 2. With arms slightly bent, lower the weight behind your head in an arc. 3. Pull the weight back over your chest, squeezing your lats and chest. 4. Complete all reps with control before resting.', 'Pull', NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 65, 7, 8, TRUE, TRUE, 'pullover', 'Decline Bent Arm Pullover', 'bicep_curl, face_pull, lat_pulldown', FALSE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('305d787f-a667-43b7-9cc4-6dde2fdb977e', 'Easy Downward Dog Yoga Pose', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Hamstrings","Shoulders"}'::text[], 'This stretch specifically works on your full body, promoting flexibility and reducing muscle tightness. You''ll also feel your hamstrings, calves, shoulders working to support the movement. Flexibility work like this enhances performance and prevents stiffness.', '97641201', '97641201-Easy-Downward-Dog-Yoga-Pose-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. Move into the stretch position for Easy Downward Dog Yoga Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'yoga', 'Easy Downward Dog Yoga Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('306281d9-480d-4dbd-8f97-eae1bcda1163', 'Forward Backward Lunge (Kettlebell)', 'Legs', 'Kettlebell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this lunging exercise for quad development. You''ll also feel your glutes, hamstrings working to support the movement. The kettlebell''s offset center of mass increases the stability challenge. Leg training boosts metabolism and builds functional, real-world strength.', '86401201', '86401201-Kettlebell-Forward-Backward-Lunge-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:24.422129+00', '1. Select an appropriately weighted kettlebell for Kettlebell Forward Backward Lunge. 2. Step backward, lowering your back knee toward the floor. 3. Push through your front/working leg to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'lunge', 'Forward Backward Lunge', 'split_squat, step_up, squat', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('30641a6a-f073-41c4-bd6b-0d39e6d41d68', 'Push Up Plank Jack Burpee', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Elevate your training with this pushing exercise that develops speed, power, and coordination. You''ll also feel your triceps, front delts working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '86271201', '86271201-Push-up-Plank-Jack-Burpee-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:22.755209+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Complete all reps with control before resting. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'push_up', 'Push Up Plank Jack Burpee', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('30816a50-44f4-4796-882c-1a88a52395db', 'Lying Flat Hip Raise', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Lying Flat Hip Raise is a core raising exercise that primarily targets your abs. Performing this lying down removes momentum for stricter form. A versatile bodyweight movement perfect for home or gym training. Core strength is foundational for athletic performance and injury prevention.', '48861201', '48861201-Lying-Flat-Hip-Raise-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.133808+00', '1. Lie down in the appropriate position for Lying Flat Hip Raise. 2. Raise the weight in the prescribed direction for Lying Flat Hip Raise. 3. Lower with control, maintaining tension throughout. 4. Repeat for the prescribed number of repetitions. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'back_exercise', 'Lying Flat Hip Raise', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('308dfd6e-1156-40a1-a0ad-6ce14ab9465a', 'Goblet Split Squat Front Foot Elevated (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. Secondary activation of your glutes, hamstrings provides additional muscle engagement. The dumbbell variation provides freedom of movement and greater range of motion. Leg training boosts metabolism and builds functional, real-world strength.', '29561201', '29561201-Dumbbell-Goblet-Split-Squat-Front-Foot-Elevanted_T.mp4', 'male', FALSE, '2025-12-03 23:26:23.586683+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Goblet Split Squat Front Foot Elevanted. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps with control before resting. Engage your stabilizer muscles for better control.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'split_squat', 'Goblet Split Squat Front Foot Elevanted', 'squat, front_squat, lunge', TRUE, 'dumbbell', FALSE, 4, 120, 5, 92, 90, 92, 90),
('308e4ad5-deb5-49ae-ac7c-294e5d927261', 'Side Step Arm Stretched', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Build power and athleticism with this high-intensity stretching exercise that challenges your entire body. Plyometric training builds explosive power that transfers to sports and daily activities.', '93671201', '93671201-Side-Step-Arm-Stretched-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.303932+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Side Step Arm Stretched. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Side Step Arm Stretched', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('30952b5c-156f-4e73-ad11-28d0576a857e', 'Tricep Extension (Machine)', 'Arms', 'Machine', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This extension movement isolates your triceps for improved arm development. Machine exercises are great for isolating muscles and training to failure safely. Arm strength supports grip, pulling, and pushing in compound movements.', '28201201', '28201201-Lever-Triceps-Extension-(VERSION-2)-(female)_Upper-Arms.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Triceps Extension. 2. Extend at the elbow until your arm is straight, squeezing the tricep. 3. Lower with control, keeping your upper arm stationary. 4. Complete all reps with control before resting. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 88, 5, 7, FALSE, TRUE, 'tricep_extension', 'Lever Triceps Extension', 'tricep_pushdown, close_grip_bench', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88);
INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('309f31d9-900d-4523-af66-b36d6f70abb0', 'Standing Hip Horizontal And Saggital Rotation', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'Build total body strength and coordination with this multi-joint rotation movement. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. Compound movements like this develop coordination, power, and overall fitness.', '53201201', '53201201-Standing-Hip-Horizontal-and-Saggital-Rotation-(fem.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Stand with feet about shoulder-width apart. 2. Rotate your torso through the movement pattern for Standing Hip Horizontal And Saggital Rotation. 3. Control the rotation in both directions—avoid using momentum. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'glute_exercise', 'Standing Hip Horizontal And Saggital Rotation', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('30aaebe6-6cdb-44c1-87c3-a47049cc99ca', 'Single Leg Calf Jump Stepbox Supported (Step Platform)', 'Legs', 'Step Platform', '{"Calves"}'::text[], '{}'::text[], 'Elevate your training with this jumping exercise that develops speed, power, and coordination. Your quads, calves work as secondary movers, adding to the training stimulus. Plyometric training builds explosive power that transfers to sports and daily activities.', '107551201', '107551201-Single-Leg-Calf-Jump-StepBox-Supported-(female)_P.mp4', 'female', FALSE, '2025-12-03 23:26:37.429219+00', '1. Set up a box or step platform at the appropriate height. 2. Complete all reps on one side, then switch to the other side. 3. Complete all reps with control before resting. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 45, 9, 8, TRUE, TRUE, 'calf_raise', 'Single Leg Calf Jump Stepbox Supported', 'lunge, split_squat, squat', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('30b52cac-ee96-4f45-8f1b-31025baddb85', 'Standing Fly - Neutral Grip (Cable)', 'Arms', 'Cables', '{"Forearms"}'::text[], '{}'::text[], 'This flying exercise focuses on your pectorals for improved chest strength and development. You''ll also feel your front delts working to support the movement. The standing position engages your core for stability. Cable resistance creates smooth, continuous muscle engagement. A well-developed chest contributes to upper body strength and aesthetics.', '74161201', '74161201-Cable-Standing-Neutral-grip-Fly-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:29.61214+00', '1. Adjust the cable machine to the correct height and attachment for Cable Standing Neutral Grip Fly. 2. Stand tall with your feet firmly planted. 3. Use a neutral grip with palms facing each other. 4. With a slight bend in your elbows, move the weight in a wide arc. 5. Squeeze your chest muscles at the center/top of the movement. 6. Return with control, feeling the stretch at the bottom. 7. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'chest_fly', 'Standing Fly - Neutral Grip', 'Standing Fly - Neutral Grip', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('30bdc4f0-4e15-4e2f-90b0-49fb2d5f0157', 'Triceps Extension Stepback', 'Arms', 'Bodyweight', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'The Triceps Extension Stepback is an explosive exercise that combines cardiovascular training with dynamic extension movements. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '55491201', '55491201-Triceps-Extension-Stepback-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.79101+00', '1. Set up a box or step platform at the appropriate height. 2. Raise your torso by extending at the lower back/hips. 3. Lower with control, maintaining tension. 4. Repeat for the prescribed number of repetitions. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'tricep_extension', 'Triceps Extension Stepback', 'tricep_pushdown, close_grip_bench', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('30c0f601-93c8-43b4-bfdb-f55c9cac004b', 'Lying Leg Raise And Hold', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build leg strength with this raising movement focusing on your abs. Your hip flexors work as secondary movers, adding to the training stimulus. Performing this lying down removes momentum for stricter form. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '12451201', '12451201-Lying-Leg-Raise-and-Hold_Hips.mp4', 'male', FALSE, '2025-12-03 23:26:25.87243+00', '1. Lie down in the appropriate position for Lying Leg Raise And Hold. 2. Keeping legs mostly straight, raise them toward the ceiling. 3. Lower with control, stopping just before touching down. 4. Hold the position for the prescribed time, maintaining tension. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 65, 5, 7, FALSE, TRUE, 'leg_raise', 'Lying Leg Raise And Hold', 'crunch, plank, v_up', FALSE, 'bodyweight', TRUE, 3, 60, 2, 70, 88, 95, 65),
('30ce7db4-888d-436c-a9de-dee040eac3ae', 'Lateral Hurdle Jump (Hurdles)', 'Legs', 'Hurdles', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'This dynamic jumping movement gets your heart rate up while developing explosive strength. Your quads, calves work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '69581201', '69581201-Lateral-Hurdle-Jump-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:27.67144+00', '1. Set up in the starting position for Lateral Hurdle Jump. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'romanian_deadlift', 'Lateral Hurdle Jump', 'deadlift, leg_curl, hip_thrust', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('30d8e00e-8633-4453-bea2-e629332f376f', 'Seated Forearms Stretch', 'Arms', 'Bodyweight', '{"Forearms"}'::text[], '{}'::text[], 'The Seated Forearms Stretch is a flexibility exercise that targets your forearms, helping to release tension and improve range of motion. Your wrists work as secondary movers, adding to the training stimulus. Being seated provides stability, allowing you to focus on the working muscles. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '67631201', '67631201-Seated-Forearms-Stretch-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:28.968567+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Forearms Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'stretch_general', 'Seated Forearms Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('30f5ade5-c551-4d0c-b94c-4d5936427efc', 'Seated Open Up And Under Swing (Chair)', 'Core', 'Chair', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Target your chest with the Seated Open Up And Under Swing On A Chair, an effective swinging movement for upper body strength. The seated position helps isolate the target muscles by removing momentum. A well-developed chest contributes to upper body strength and aesthetics.', '86531201', '86531201-Seated-Open-Up-and-Under-Swing-on-a-Chair-(male)_C.mp4', 'male', FALSE, '2025-12-03 23:26:27.263406+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Hinge at your hips, letting the weight swing back between your legs. 4. Explosively drive hips forward, propelling the weight forward/up. 5. Let gravity bring it back as you hinge for the next rep. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 37, 7, 8, TRUE, TRUE, 'dynamic_warmup', 'Seated Open Up And Under Swing On A Chair', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('31082d3d-b31b-4ad6-a6df-81dcf40ca5bf', 'Front Raise - Single (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'Build stronger shoulders with this raising movement focusing on your front delts. Dumbbells allow each arm to work independently, helping correct imbalances. Strong shoulders improve overhead strength and support nearly all upper body movements.', '86471201', '86471201-Dumbbell-Front-Raise-(VERSION-3)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:27.504261+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Front Raise. 2. Raise the weight in front of you to shoulder height. 3. Lower with control, maintaining tension throughout. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'front_raise', 'Front Raise', 'shoulder_press, lateral_raise, rear_delt_fly', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('3109fca6-593c-4428-a500-a85cde2ed74a', 'Row In Doorway (Door Frame)', 'Back', 'Door Frame', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Bodyweight Row In Doorway is a rowing exercise that builds thickness in your upper back. You''ll also feel your biceps, rear delts working to support the movement. No equipment needed—your body provides all the resistance. A strong back improves posture, prevents injury, and balances pressing movements.', '35061201', '35061201-Bodyweight-Row-in-Doorway_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Pull the weight toward your torso, leading with your elbow(s). 2. Squeeze your shoulder blades together at the peak contraction. 3. Extend back out with control, feeling the stretch in your back. 4. Repeat for the prescribed number of repetitions. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'general_exercise', 'Row In Doorway', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('310ce0e6-0985-43b2-9325-20cb681ed3e7', 'Bicycle Recline Walk', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Enhance your stamina and burn calories with this effective cardio movement. You''ll also feel your abs working to support the movement. Cardiovascular exercise improves heart health, endurance, and helps manage weight.', '24281201', '24281201-Bicycle-Recline-Walk-(female)_Cardio_.mp4', 'female', FALSE, '2025-12-03 23:26:31.347577+00', '1. Set up in the starting position for Bicycle Recline Walk. 2. Execute the movement with proper form, focusing on your cardio. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'cycling', 'Bicycle Recline Walk', 'running, elliptical, rowing_cardio', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('310f8a74-9008-4068-a851-252851cc0b6b', 'Incline Jack Plank', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Build a stronger core with the Incline Jack Plank, focusing on your abs. You''ll also feel your shoulders, lower back working to support the movement. The incline angle shifts emphasis toward the upper portion of the target muscles. Core strength is foundational for athletic performance and injury prevention.', '105931201', '105931201-Incline-Jack-Plank-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:26.93819+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Continue for your target rep count, maintaining good form throughout. Keep your core engaged for stability. This exercise is excellent for abs development.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 73, 9, 8, TRUE, TRUE, 'plank', 'Incline Jack Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('3120277c-9f4b-4a58-80d2-69fb57a2badf', 'Bulgarian Split Squat With Support (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. You''ll also feel your glutes, hamstrings working to support the movement. Dumbbells allow each arm to work independently, helping correct imbalances. Leg training boosts metabolism and builds functional, real-world strength.', '84461201', '84461201-Dumbbell-Bulgarian-Split-Squat-with-Support-(male).mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Bulgarian Split Squat With Support. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'split_squat', 'Bulgarian Split Squat With Support', 'split_squat, lunge, leg_press', FALSE, 'dumbbell', FALSE, 4, 120, 5, 92, 90, 92, 90),
('31227a69-646f-42b5-a162-616bc042f548', 'Seated Shoulder Anti Clockwise Circle', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Build a stronger back with this movement movement targeting your delts. The seated position helps isolate the target muscles by removing momentum. Back development is crucial for pulling strength and overall upper body function.', '88671201', '88671201-Seated-Shoulder-Anti-Clockwise-Circle-(female)_Bac.mp4', 'female', FALSE, '2025-12-03 23:26:36.848698+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Set up in the starting position for Seated Shoulder Anti Clockwise Circle. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Seated Shoulder Anti Clockwise Circle', 'lateral_raise, shoulder_press, front_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3124c7b2-9d81-414f-bef7-3afcab1748d0', 'Farmers Carry (Trap Bar)', 'Full Body', 'Trap Bar', '{"Forearms"}'::text[], '{"Traps","Core","Quads","Hamstrings"}'::text[], 'The Trap Bar Farmers Carry is a lower body movement exercise that targets your forearms. You''ll also feel your traps working to support the movement. Lower body strength improves everything from walking to heavy compound lifts.', '57591201', '57591201-Trap-Bar-Farmers-Carry-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:39.79101+00', '1. Set up in the starting position for Trap Bar Farmers Carry. 2. Execute the movement with proper form, focusing on your forearms. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'arm_exercise', 'Farmers Carry', 'deadlift, shrug, suitcase_carry', FALSE, 'barbell', TRUE, 3, 90, 4, 95, 80, 65, 95),
('31325895-529c-45d7-b0de-25f82c9ae9b0', 'Quarter Sit Up', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Quarter Sit Up is a core movement exercise that primarily targets your abs. You''ll also feel your hip flexors working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '32611201', '32611201-Quarter-Sit-up-(female)_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:35.936279+00', '1. Set up in the starting position for Quarter Sit Up. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Quarter Sit Up', 'leg_raise, plank, russian_twist, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('313ac832-ca06-48d0-aba0-d73921c35174', 'Lying Straight Leg Marches', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Lying Straight Leg Marches, focusing on your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. Performing this lying down removes momentum for stricter form. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '100681201', '100681201-Lying-Straight-Leg-Marches-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.38119+00', '1. Lie down in the appropriate position for Lying Straight Leg Marches. 2. Set up in the starting position for Lying Straight Leg Marches. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'romanian_deadlift', 'Lying Straight Leg Marches', 'deadlift, leg_curl, hip_thrust', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('314c9398-d0db-466d-8818-34433bfb5439', 'Lying Knee Hugs Circle', 'Hips', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'The Lying Knee Hugs Circle is a lower body movement exercise that targets your delts. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts.', '81501201', '81501201-Lying-Knee-Hugs-Circle-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.250398+00', '1. Lie down in the appropriate position for Lying Knee Hugs Circle. 2. Set up in the starting position for Lying Knee Hugs Circle. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Knee Hugs Circle', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('316781cd-79a6-4c2d-8548-7bfc67bc07cc', 'Finger Raise Plank', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'The Finger Raises Plank is an arm raising exercise targeting your abs. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Dedicated arm training builds both strength and muscular definition.', '65801201', '65801201-Finger-Raises-Plank-(male)_Forearms_.mp4', 'male', FALSE, '2025-12-03 23:26:29.971345+00', '1. Raise the weight in the prescribed direction for Finger Raises Plank. 2. Lower with control, maintaining tension throughout. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'plank', 'Finger Raise Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 60, 2, 70, 88, 95, 65),
('31696ba7-5d6c-4fae-8e03-fb5aa6ba6501', 'Standing Archer Arm Row - Alternating', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. You''ll also feel your biceps, rear delts working to support the movement. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. A strong back improves posture, prevents injury, and balances pressing movements.', '72251201', '72251201-Standing-Archer-Alternate-Arm-Row-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Begin in a standing position with good posture. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Alternate between sides/arms/legs with each repetition. 6. Continue for your target rep count, maintaining good form throughout. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 72, 7, 8, TRUE, TRUE, 'arm_exercise', 'Standing Archer Arm Row - Alternating', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('316b9fc9-3a95-4f0c-b813-19f9e5f232db', 'Hyperextension (TRX)', 'Back', 'TRX, Hyperextension Bench', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Suspender Hyperextension is a extension exercise that develops back strength and muscle. You''ll also feel your hamstrings, lower back working to support the movement. Suspension training adds instability, increasing core activation throughout. Back development is crucial for pulling strength and overall upper body function.', '10791201', '10791201-Suspender-Hyperextension-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:39.472701+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Hyperextension. 2. Raise your torso by extending at the lower back/hips. 3. Lower with control, maintaining tension. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 60, 5, 7, FALSE, TRUE, 'back_extension', 'Suspender Hyperextension', 'good_morning, bird_dog, superman', FALSE, 'trx', FALSE, 3, 60, 2, 68, 85, 85, 70),
('31867a05-6b79-4060-b67d-6bc8d85f1f50', 'Step Up (Step Platform)', 'Legs', 'Step Platform', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this stepping movement that develops leg drive and power. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Strong legs are the foundation for athletic performance and functional fitness.', '8011201', '08011201-Step-up-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:39.21093+00', '1. Set up a box or step platform at the appropriate height. 2. Step one foot onto the elevated surface. 3. Drive through that foot to lift your body up onto the platform. 4. Step back down with control and repeat. 5. Complete all reps with control before resting. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'step_up', 'Step Up', 'lunge, split_squat, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('31b0d088-6a7d-4887-a4b6-cba34e477829', 'Plate Pullover (Stability Ball)', 'Chest', 'Stability Ball, Weight Plate', '{"Chest"}'::text[], '{"Lats","Triceps"}'::text[], 'The Weighted Plate Pullover On Stability Ball is a pulling exercise that develops back strength and muscle. Secondary activation of your lats, triceps provides additional muscle engagement. The stability ball adds an instability challenge that activates more stabilizer muscles. A strong back improves posture, prevents injury, and balances pressing movements.', '83211201', '83211201-Weighted-Plate-Pullover-on-Stability-Ball-(male)_B.mp4', 'male', FALSE, '2025-12-03 23:26:26.39056+00', '1. Position the stability ball as needed for Weighted Plate Pullover On Stability Ball. 2. With arms slightly bent, lower the weight behind your head in an arc. 3. Pull the weight back over your chest, squeezing your lats and chest. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 42, 7, 8, TRUE, TRUE, 'pullover', 'Weighted Plate Pullover On Stability Ball', 'bicep_curl, face_pull, lat_pulldown', FALSE, 'plate', FALSE, 3, 90, 4, 70, 88, 95, 65),
('31c33356-2020-493e-a52e-974fc16152f9', 'Standing Hip Saggital Rotation With Hands Overhead', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'Build total body strength and coordination with this multi-joint rotation movement. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. Full body exercises are time-efficient and build functional, real-world strength. Quality repetitions are more important than quantity.', '53221201', '53221201-Standing-Hip-Saggital-Rotation-with-Hands-Overhead.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Begin in a standing position with good posture. 2. Rotate your torso through the movement pattern for Standing Hip Saggital Rotation With Hands Overhead. 3. Control the rotation in both directions—avoid using momentum. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'glute_exercise', 'Standing Hip Saggital Rotation With Hands Overhead', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('31c73124-5dc0-497e-900c-d6a91344d4e0', 'Rocking Happy Baby', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Use this stretch to open up your hips area and enhance overall flexibility. The lower back, adductors assist throughout the movement, making this a well-rounded exercise. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '62811201', '62811201-Rocking-Happy-Baby-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:36.38616+00', '1. Move into the stretch position for Rocking Happy Baby. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 15, 7, 8, TRUE, TRUE, 'yoga', 'Rocking Happy Baby', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('31cc4b68-cb14-47f0-b037-c7b423b26aaf', 'Low Plank Leg Raise', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Strengthen your midsection with this raising movement that works your abs. You''ll also feel your hip flexors working to support the movement. No equipment needed—your body provides all the resistance. Building core stability helps with everything from heavy deadlifts to daily activities.', '74421201', '74421201-Low-Plank-Leg-Raise-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Repeat for the prescribed number of repetitions. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Low Plank Leg Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', TRUE, 3, 60, 2, 70, 88, 95, 65),
('31d73b9b-d4f3-4615-8db6-9098d9cf1e1a', 'Lying Stretch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Target your full body with this stretching stretch that helps restore range of motion. Performing this lying down removes momentum for stricter form. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '85671201', '85671201-Lying-Stretch-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:35.38119+00', '1. Lie down in the appropriate position for Lying Stretch. 2. Move into the stretch position for Lying Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Lying', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Lying Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('31f1ef42-2419-4fdc-87b5-a3542eca43e9', 'Leg Kickback (Resistance Band)', 'Legs', 'Resistance Band', '{"Glutes"}'::text[], '{"Rear Delts"}'::text[], 'Develop your posterior chain with this kicking movement that emphasizes the glutes. You''ll also feel your hamstrings working to support the movement. Bands are joint-friendly and portable, perfect for any training environment. Leg training boosts metabolism and builds functional, real-world strength.', '21561201', '21561201-Resistance-Band-Leg-Kickback_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band Leg Kickback. 2. Keep your upper arm stationary and extend your forearm back. 3. Squeeze at full extension, then return with control. 4. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 55, 5, 7, FALSE, TRUE, 'tricep_kickback', 'Leg Kickback', 'squat, lunge, leg_press', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('31f2dbff-7c17-40b9-b993-cf14456d046d', 'Inverted Row With Straps', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. Secondary activation of your biceps provides additional muscle engagement. No equipment needed—your body provides all the resistance. Back development is crucial for pulling strength and overall upper body function.', '38971201', '38971201-Inverted-Row-with-Straps-(female)_back.mp4', 'female', FALSE, '2025-12-03 23:26:34.073704+00', '1. Pull the weight toward your torso, leading with your elbow(s). 2. Squeeze your shoulder blades together at the peak contraction. 3. Extend back out with control, feeling the stretch in your back. 4. Complete all reps with control before resting. Exhale during the exertion phase of the movement. Perfect for targeting your upper back.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'general_exercise', 'Inverted Row With Straps', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('31f76f3c-2702-49cf-b765-687ccc9646ec', 'Seated Arms Rotation - Alternating', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Seated Alternate Arms Rotation provides a deep stretch for your full body, ideal for recovery and mobility work. The seated position helps isolate the target muscles by removing momentum. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '82371201', '82371201-Seated-Alternate-Arms-Rotation-(female)_Stretching.mp4', 'female', FALSE, '2025-12-03 23:26:36.581585+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Rotate your torso through the movement pattern for Seated Alternate Arms Rotation. 3. Control the rotation in both directions—avoid using momentum. 4. Alternate between sides/arms/legs with each repetition.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'arm_exercise', 'Seated Arms Rotation - Alternating', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('32161da6-4c69-4d77-81ea-75f6113b3e4c', 'One Legged Diagonal Kick Hamstring (Stability Ball)', 'Core', 'Stability Ball, Gymnastic Rings', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This kicking exercise engages your core for improved core stability and strength. The stability ball adds an instability challenge that activates more stabilizer muscles. A strong core improves posture, protects your spine, and enhances all other lifts.', '28251201', '28251201-Exercise-Ball-One-Legged-Diagonal-Kick-Hamstring-C.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Position the stability ball as needed for One Legged Diagonal Kick Hamstring. 2. Complete all reps on one side, then switch to the other side. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 15, 7, 8, TRUE, TRUE, 'leg_exercise', 'One Legged Diagonal Kick Hamstring', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'gymnastic_rings', FALSE, 3, 90, 4, 68, 85, 85, 70),
('3224aa4c-c21c-4cc9-af9f-71fd003fe12e', 'Lying Femoral (Dumbbell)', 'Core', 'Dumbbells, Flat Bench', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build leg strength with this movement movement focusing on your core. Performing this lying down removes momentum for stricter form. Dumbbells allow each arm to work independently, helping correct imbalances. Lower body strength improves everything from walking to heavy compound lifts.', '3391201', '03391201-Dumbbell-Lying-Femoral_Thighs.mp4', 'male', FALSE, '2025-12-03 23:26:20.392006+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Lying Femoral. 2. Lie down in the appropriate position for Dumbbell Lying Femoral. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Femoral', 'squat, bench_press, deadlift', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('3245756a-aac3-49f8-a527-cf5e27e92106', 'Standing Double Arm Crossover And Double Prayer Pu', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'The Standing Double Arm Crossover And Double Prayer Pu is a movement exercise that targets your chest muscles. Secondary activation of your front delts provides additional muscle engagement. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. A well-developed chest contributes to upper body strength and aesthetics.', '94341201', '94341201-Standing-Double-Arm-Crossover-and-Double-Prayer-Pu.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Begin in a standing position with good posture. 2. Set up in the starting position for Standing Double Arm Crossover And Double Prayer Pu. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 37, 7, 8, TRUE, TRUE, 'chest_fly', 'Standing Double Arm Crossover And Double Prayer Pu', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3245f77d-ab76-4aab-b5e0-2501847f8c08', 'Seated Finger Clap', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Seated Finger Clap is an arm movement exercise targeting your core. The seated position helps isolate the target muscles by removing momentum. Dedicated arm training builds both strength and muscular definition.', '82481201', '82481201-Seated-Finger-Clap-(female)_Forearms_.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Set up in the starting position for Seated Finger Clap. 3. Execute the movement with proper form, focusing on your core. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Finger Clap', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('324825f8-f903-47d4-91f5-b1056a594503', 'Russian Twist Chop', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'This twisting movement focuses on your obliques for a complete core workout. Your abs work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Core strength is foundational for athletic performance and injury prevention.', '73771201', '73771201-Russian-Twist-Chop-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.123147+00', '1. Rotate your torso through the movement pattern for Russian Twist Chop. 2. Control the rotation in both directions—avoid using momentum. 3. Continue for your target rep count, maintaining good form throughout. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'russian_twist', 'Russian Twist Chop', 'crunch, plank, leg_raise, wood_chop', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('324ba061-56dc-4d77-9d74-471601daa5cd', 'Upright Row (Barbell)', 'Shoulders', 'Barbell', '{"Side Delts"}'::text[], '{"Traps","Front Delts"}'::text[], 'Build stronger shoulders with this rowing movement focusing on your delts. Secondary activation of your traps provides additional muscle engagement. Barbells enable bilateral loading for building raw strength. Strong shoulders improve overhead strength and support nearly all upper body movements.', '1201201', '01201201-Barbell-Upright-Row_shoulder.mp4', 'male', FALSE, '2025-12-03 23:26:24.099303+00', '1. Grip a barbell with hands at the appropriate width for Barbell Upright Row. 2. Pull the weight straight up along your body, leading with your elbows. 3. Raise until elbows reach shoulder height, then lower with control. 4. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 82, 7, 9, TRUE, FALSE, 'upright_row', 'Upright Row', 'lateral_raise, shoulder_press, shrug', FALSE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('324c55b8-688c-466e-8100-3356c141bd0a', 'Squat - On Knees (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Barbell Squat (on Knees) is a squatting exercise that primarily loads your quadriceps. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Barbells enable bilateral loading for building raw strength. Leg training boosts metabolism and builds functional, real-world strength.', '1021201', '01021201-Barbell-Squat-(on-knees)_Thighs-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:23.288245+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 89, 7, 9, TRUE, FALSE, 'squat', 'Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', TRUE, 'barbell', FALSE, 4, 120, 5, 95, 80, 65, 95),
('3253e4b7-20d3-437f-9896-2a067dfd7668', 'Horizontal Pallof Press (Band)', 'Core', 'Resistance Band, Anchor Point', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Band Horizontal Pallof Press is a core pressing exercise that primarily targets your abs. Resistance bands provide accommodating resistance that increases through the range of motion. Core strength is foundational for athletic performance and injury prevention.', '9791201', '09791201-Band-Horizontal-Pallof-Press_Waist.mp4', 'male', FALSE, '2025-12-03 23:26:27.263406+00', '1. Secure the resistance band appropriately for Band Horizontal Pallof Press. 2. Execute the pressing motion for Band Horizontal Pallof Press, extending through the target muscles. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'pallof_press', 'Horizontal Pallof Press', 'woodchop, plank, dead_bug', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('3254865f-8fca-4a07-9569-1e1c615c3f63', 'Double Hang Clean (Kettlebell) - Alternating', 'Shoulders', 'Kettlebell', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'This movement exercise works your delts for improved shoulder strength and aesthetics. You''ll also feel your quads, glutes, traps working to support the movement. The kettlebell''s offset center of mass increases the stability challenge. Strong shoulders improve overhead strength and support nearly all upper body movements.', '5261201', '05261201-Kettlebell-Double-Alternating-Hang-Clean_Shoulders.mp4', 'male', FALSE, '2025-12-03 23:26:28.968567+00', '1. Position two kettlebells for Kettlebell Double Alternating Hang Clean. 2. Explosively pull the weight upward from the starting position. 3. Pull yourself under the weight and catch it at shoulder level. 4. Stand to complete the lift, then lower with control. 5. Alternate between sides/arms/legs with each repetition. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'clean', 'Double Hang Clean - Alternating', 'power_clean, clean, front_squat', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('3255312e-a329-4748-96b3-988166995c31', 'Leg Raise Hip Lift', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This raising exercise engages your abs for improved core stability and strength. Secondary activation of your hip flexors provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '72841201', '72841201-Leg-Raise-Hip-Lift-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.644637+00', '1. Keeping legs mostly straight, raise them toward the ceiling. 2. Lower with control, stopping just before touching down. 3. Complete all reps with control before resting. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Leg Raise Hip Lift', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('325630d1-18c0-4df2-85cc-cc7470b92798', 'Decline Sit Up (Decline Bench)', 'Core', 'Decline Bench', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Decline Sit Up is a core movement exercise that primarily targets your abs. You''ll also feel your hip flexors working to support the movement. Declining shifts the emphasis to hit the muscles from a different angle. A strong core improves posture, protects your spine, and enhances all other lifts.', '55151201', '55151201-Decline-Sit-Up-(VERSION-3)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.536005+00', '1. Set up in the starting position for Decline Sit Up. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 73, 5, 7, FALSE, TRUE, 'crunch', 'Decline Sit Up', 'leg_raise, plank, russian_twist, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('3259583b-29b8-4cb5-be3a-2afbf4bdd0dc', 'Front Scoops', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'The Front Scoops is a movement exercise that targets your front delts for shoulder development. This bodyweight exercise requires no equipment and can be done anywhere. Strong shoulders improve overhead strength and support nearly all upper body movements.', '53581201', '53581201-Front-Scoops-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:33.640031+00', '1. Set up in the starting position for Front Scoops. 2. Execute the movement with proper form, focusing on your front delts. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Front Scoops', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('32664564-77f6-4978-981a-25bbf7e3c911', 'Bench Pull Ups (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This pulling exercise emphasizes your lats for improved back development. Your biceps, upper back work as secondary movers, adding to the training stimulus. Back development is crucial for pulling strength and overall upper body function.', '30201201', '30201201-Bench-Pull-ups-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:31.133197+00', '1. Pull yourself up by driving your elbows down and back. 2. Continue until your chin clears the bar, then lower with control to a full hang. 3. Complete all reps with control before resting. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'Bench Pull Ups', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('326d04f8-5ca3-4eb5-bbc8-e7ee1a907149', 'Landmine Squat (Landmine)', 'Legs', 'Landmine Attachment, Barbell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. You''ll also feel your glutes, hamstrings working to support the movement. Strong legs are the foundation for athletic performance and functional fitness.', '76261201', '76261201-Landmine-Squat-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:23.288245+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Repeat for the prescribed number of repetitions. Focus on squeezing the target muscle at peak contraction.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 85, 7, 9, TRUE, FALSE, 'squat', 'Landmine Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', TRUE, 'barbell', FALSE, 4, 120, 5, 95, 80, 65, 95),
('326d8111-719f-453f-89c9-337ac0614088', 'Fly (Stability Ball, Dumbbell)', 'Chest', 'Dumbbells, Stability Ball, Flat Bench', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Target your chest with the Dumbbell Fly (stability Ball), an effective flying movement for upper body strength. Your front delts work as secondary movers, adding to the training stimulus. Dumbbells allow each arm to work independently, helping correct imbalances. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '26201201', '26201201-Dumbbell-Fly-on-Exercise-Ball-(female)_Chest.mp4', 'female', FALSE, '2025-12-03 23:26:32.735372+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Fly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Continue for your target rep count, maintaining good form throughout. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 66, 5, 7, FALSE, TRUE, 'general_exercise', 'Fly', 'bench_press, incline_bench_press, push_up', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('3277d293-5548-4b68-a3d2-dde2d7bc23d3', 'Feet Front Tap', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities. Focus on controlled form throughout each repetition.', '86281201', '86281201-Feet-Front-Tap-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:24.577164+00', '1. Set up in the starting position for Feet Front Tap. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Feet Front Tap', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3290c31d-7599-4392-872a-43449c846d65', 'Seated High Row - V Bar (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Cable Seated High Row (V Bar) is a rowing exercise that builds thickness in your upper back. The biceps, rear delts assist throughout the movement, making this a well-rounded exercise. Being seated provides stability, allowing you to focus on the working muscles. The cable setup allows you to adjust the angle of resistance. Back development is crucial for pulling strength and overall upper body function.', '2131201', '02131201-Cable-Seated-High-Row-(V-bar)_Back.mp4', 'male', FALSE, '2025-12-03 23:26:24.099303+00', '1. Set the cable pulley to the highest position and attach your preferred handle. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 74, 7, 8, TRUE, TRUE, 'cable_row', 'Seated High Row', 'bent_over_row, lat_pulldown, face_pull', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('32931d4d-68f5-4409-82b2-10bffbf5e2b1', 'Standing Boat Row', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Standing Boat Row is a core rowing exercise that primarily targets your abs. You''ll also feel your biceps, rear delts working to support the movement. Performing this standing challenges your balance and core engagement. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention.', '66551201', '66551201-Standing-Boat-Row-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:23.466497+00', '1. Stand with feet about shoulder-width apart. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 72, 7, 8, TRUE, TRUE, 'dumbbell_row', 'Standing Boat Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('329ea72f-aaf3-4ef4-9224-750eab0fe812', 'Vertical Pallof Press (Cable)', 'Core', 'Cables', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Cable Vertical Pallof Press, focusing on your abs. Cables provide constant tension throughout the full range of motion. Building core stability helps with everything from heavy deadlifts to daily activities.', '12131201', '12131201-Cable-Vertical-Pallof-Press_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.417605+00', '1. Adjust the cable machine to the correct height and attachment for Cable Vertical Pallof Press. 2. Execute the pressing motion for Cable Vertical Pallof Press, extending through the target muscles. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 80, 7, 8, TRUE, TRUE, 'pallof_press', 'Vertical Pallof Press', 'woodchop, plank, dead_bug', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('32a50f3e-6d66-4aa2-9a5e-76053743edb7', 'Standing W Pose', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Build stronger shoulders with this movement movement focusing on your delts. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. Strong shoulders improve overhead strength and support nearly all upper body movements.', '86011201', '86011201-Bodyweight-Standing-W-Pose-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:31.60311+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Bodyweight Standing W Pose. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 52, 2, 6, FALSE, TRUE, 'general_exercise', 'Standing W Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('32c01803-1ed7-482f-9873-9fced160f49a', 'Scapula Elevation Depression', 'Back', 'Bodyweight', '{"Traps"}'::text[], '{}'::text[], 'Build a stronger back with this pressing movement targeting your traps. No equipment needed—your body provides all the resistance. Back development is crucial for pulling strength and overall upper body function.', '31301201', '31301201-Scapula-Elevation-Depression_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:28.968567+00', '1. Execute the pressing motion for Scapula Elevation Depression, extending through the target muscles. 2. Set up in the starting position for Scapula Elevation Depression. 3. Execute the movement with proper form, focusing on your traps. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'general_exercise', 'Scapula Elevation Depression', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('32c096c2-e24e-4dc5-8b44-127f33067334', 'W To Y Superman', 'Back', 'Bodyweight', '{"Lower Back"}'::text[], '{"Glutes","Upper Back"}'::text[], 'The W To Y Superman is a lower body movement exercise that targets your lower back. Secondary activation of your glutes provides additional muscle engagement. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '55451201', '55451201-W-to-Y-Superman-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:39.91585+00', '1. Set up in the starting position for W To Y Superman. 2. Execute the movement with proper form, focusing on your lower back. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_extension', 'W To Y Superman', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('32c17747-f8e1-4f71-b8af-19141015badb', 'Protraction Plank Jack', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Build a stronger core with the Protraction Plank Jack, focusing on your abs. Your shoulders, lower back work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Core strength is foundational for athletic performance and injury prevention.', '71961201', '71961201-Protraction-Plank-Jack-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:29.61214+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Continue for your target rep count, maintaining good form throughout. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'plank', 'Protraction Plank Jack', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('32c1d8e0-3cdb-4ae5-be46-3d0ce59df6c9', 'Knee Tap Sky Reach', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '83931201', '83931201-Knee-Tap-Sky-Reach-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:22.536005+00', '1. Set up in the starting position for Knee Tap Sky Reach. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'shoulder_stretch', 'Knee Tap Sky Reach', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('32c43475-7443-42e1-a362-b0b0cb7cfeb2', 'Lying Double Glute Lift', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'This movement exercise isolates your glutes for improved hip strength and power. The lying position provides back support and helps isolate the target muscles. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '64151201', '64151201-Lying-Double-Glute-Lift-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.133808+00', '1. Lie down in the appropriate position for Lying Double Glute Lift. 2. Set up in the starting position for Lying Double Glute Lift. 3. Execute the movement with proper form, focusing on your glutes. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'glute_exercise', 'Lying Double Glute Lift', 'hip_thrust, glute_bridge, leg_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('32c91fd5-af14-48c7-ad5c-8ddbf2215e44', 'Superman Arm Crossover', 'Back', 'Bodyweight', '{"Lower Back"}'::text[], '{"Glutes","Upper Back"}'::text[], 'Build leg strength with this movement movement focusing on your chest. Secondary activation of your front delts provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '96251201', '96251201-Superman-Arm-Crossover-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Set up in the starting position for Superman Arm Crossover. 2. Execute the movement with proper form, focusing on your chest. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'chest_fly', 'Superman Arm Crossover', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('32f2c83b-5119-49af-bfc0-968a5c715327', 'Incline Row - Reverse Grip (Dumbbell)', 'Back', 'Dumbbells, Incline Bench', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Dumbbell Reverse Grip Incline Row is a rowing exercise that builds thickness in your upper back. The biceps, rear delts assist throughout the movement, making this a well-rounded exercise. The incline angle shifts emphasis toward the upper portion of the target muscles. The dumbbell variation provides freedom of movement and greater range of motion. A strong back improves posture, prevents injury, and balances pressing movements.', '25111201', '25111201-Dumbbell-Reverse-Grip-Incline-Row-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:33.034396+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Reverse Grip Incline Row. 2. Use a reverse grip (opposite of the standard grip for this exercise). 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 85, 7, 9, TRUE, FALSE, 'dumbbell_row', 'Incline Row - Reverse Grip', 'Incline Row - Reverse Grip', TRUE, 'dumbbell', FALSE, 4, 120, 4, 92, 90, 92, 90),
('32f5c04f-6bcf-456f-9584-617f25e494d8', 'Curl - Reverse Grip (EZ Bar)', 'Arms', 'EZ Bar', '{"Forearms"}'::text[], '{"Biceps"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. The forearms assist throughout the movement, making this a well-rounded exercise. Barbells enable bilateral loading for building raw strength. Arm strength supports grip, pulling, and pushing in compound movements. Quality repetitions are more important than quantity.', '24981201', '24981201-EZ-Barbell-Reverse-Grip-Curl-(female)_Forearms.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Grip a barbell with hands at the appropriate width for EZ Barbell Reverse Grip Curl. 2. Use a reverse grip (opposite of the standard grip for this exercise). 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Continue for your target rep count, maintaining good form throughout. Maintain consistent tempo throughout the set.', 'Curl', 'Pull', NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'general_exercise', 'EZ Curl - Reverse Grip', 'EZ Curl - Reverse Grip', FALSE, 'ez_bar', FALSE, 3, 60, 2, 95, 80, 65, 95),
('32fa33d2-a324-4993-bc17-e5b400599e75', 'Low Lunge Stretch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Low Lunge Stretch is a flexibility exercise that targets your quads, helping to release tension and improve range of motion. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Include this in your routine for better mobility and reduced muscle tension.', '103531201', '103531201-Low-Lunge-Stretch-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:26.39056+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Move into the stretch position for Low Lunge Stretch. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 60, 2, 6, FALSE, TRUE, 'hip_stretch', 'Low Lunge Stretch', 'squat, split_squat, step_up, leg_press', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('330855af-da39-48d4-91ce-44c2e5f0457e', 'Groin Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Groin Crunch, focusing on your abs. You''ll also feel your hip flexors working to support the movement. No equipment needed—your body provides all the resistance. Building core stability helps with everything from heavy deadlifts to daily activities.', '4691201', '04691201-Groin-Crunch_waist.mp4', 'male', FALSE, '2025-12-03 23:26:24.577164+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Complete all reps with control before resting. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Groin Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('33104693-e2b7-4906-9798-260c446450f4', 'Swing (Kettlebell) - Alternating', 'Full Body', 'Kettlebell', '{"Full Body"}'::text[], '{"Glutes","Core"}'::text[], 'Build leg strength with this swinging movement focusing on your full body. You''ll also feel your glutes, core working to support the movement. Kettlebells are excellent for building functional, real-world strength. Leg training boosts metabolism and builds functional, real-world strength.', '98421201', '98421201-Kettlebell-Alternating-Swing-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:24.203368+00', '1. Select an appropriately weighted kettlebell for Kettlebell Alternating Swing. 2. Hinge at your hips, letting the weight swing back between your legs. 3. Explosively drive hips forward, propelling the weight forward/up. 4. Let gravity bring it back as you hinge for the next rep. 5. Alternate between sides/arms/legs with each repetition. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'general_exercise', 'Swing - Alternating', 'squat, bench_press, deadlift', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('3319c926-ec60-4009-9b95-bfac248ea97d', 'Weighted Hanging Leg Hip Raise (Pull-Up Bar)', 'Core', 'Pull-Up Bar', '{"Lower Abs"}'::text[], '{"Hip Flexors","Forearms"}'::text[], 'This raising exercise engages your abs for improved core stability and strength. Your hip flexors, grip work as secondary movers, adding to the training stimulus. Hanging adds a grip and core stability component to the exercise. No equipment needed—your body provides all the resistance. Building core stability helps with everything from heavy deadlifts to daily activities.', '70041201', '70041201-Weighted-Hanging-Leg-Hip-Raise-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:40.037451+00', '1. Grip the bar and hang with arms fully extended, engaging your shoulders. 2. Set up in the starting position for Weighted Hanging Leg Hip Raise. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Weighted Hanging Leg Hip Raise', 'crunch, plank, v_up', FALSE, 'pull_up_bar', FALSE, 3, 60, 2, 70, 88, 95, 65),
('33242499-6121-4f44-9af7-8874d54348d2', 'Standing Overhead Triceps Extension (Barbell)', 'Arms', 'Barbell', '{"Triceps"}'::text[], '{"Shoulders"}'::text[], 'Build stronger triceps with this extension exercise for bigger arms. The standing position engages your core for stability. The barbell allows you to handle heavier loads for maximum strength gains. Arm strength supports grip, pulling, and pushing in compound movements.', '26051201', '26051201-Barbell-Standing-Overhead-Triceps-Extension-(femal.mp4', 'female', FALSE, '2025-12-03 23:26:31.133197+00', '1. Grip a barbell with hands at the appropriate width for Barbell Standing Overhead Triceps Extension. 2. Stand tall with your feet firmly planted. 3. Extend at the elbow until your arm is straight, squeezing the tricep. 4. Lower with control, keeping your upper arm stationary. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 94, 5, 7, FALSE, TRUE, 'tricep_extension', 'Standing Overhead Triceps Extension', 'tricep_pushdown, close_grip_bench', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('332e373d-4177-49e7-8281-c1278bfe021a', 'Incline Breeding (Dumbbell)', 'Chest', 'Dumbbells', '{"Chest"}'::text[], '{}'::text[], 'Build a stronger chest with this movement movement that develops pressing power. Using an incline changes the angle of resistance for varied muscle recruitment. Dumbbells allow each arm to work independently, helping correct imbalances. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '3161201', '03161201-Dumbbell-Incline-Breeding_Chest.mp4', 'male', FALSE, '2025-12-03 23:26:23.056255+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Incline Breeding. 2. Set up in the starting position for Dumbbell Incline Breeding. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 65, 7, 8, TRUE, TRUE, 'general_exercise', 'Incline Breeding', 'squat, bench_press, deadlift', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('333a3317-4115-43a6-aa74-4ab2f21942df', 'Chest Fly Arms', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Build a stronger chest with this flying movement that develops pressing power. Your front delts work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. A well-developed chest contributes to upper body strength and aesthetics.', '23371201', '23371201-Chest-Fly---Arms-(WRONG-RIGHT)_.mp4', 'male', FALSE, '2025-12-03 23:26:23.79417+00', '1. With a slight bend in your elbows, move the weight in a wide arc. 2. Squeeze your chest muscles at the center/top of the movement. 3. Return with control, feeling the stretch at the bottom. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'chest_fly', 'Chest Fly Arms', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('3342cb11-d46e-4599-8f56-e4fc34d54fd2', 'Single Leg Sprinter', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build power and athleticism with this high-intensity movement exercise that challenges your entire body. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities. Quality repetitions are more important than quantity.', '78171201', '78171201-Single-Leg-Sprinter-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.429219+00', '1. Complete all reps on one side, then switch to the other side. 2. Set up in the starting position for Single Leg Sprinter. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'sprint', 'Single Leg Sprinter', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3347901c-8d71-401e-b295-1772d178c8d7', 'Plank Arm Lifts', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'The Plank Arm Lifts is a stabilization exercise that develops back strength and muscle. Secondary activation of your shoulders, lower back provides additional muscle engagement. No equipment needed—your body provides all the resistance. Back development is crucial for pulling strength and overall upper body function.', '14401201', '14401201-Plank-arm-lifts-(female)_Back-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:35.667316+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout. An effective movement for your back routine.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Plank Arm Lifts', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('334a8a6a-d917-4a46-bee0-b884295c069e', 'Stepback Flap', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic stepping movement gets your heart rate up while developing explosive strength. Secondary activation of your quads provides additional muscle engagement. Plyometric training builds explosive power that transfers to sports and daily activities. This variation is excellent for building mind-muscle connection. Consistency with this movement will yield noticeable results.', '86301201', '86301201-Stepback-Flap-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:28.71819+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Stepback Flap. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_exercise', 'Stepback Flap', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('334b5c95-e370-4256-abdc-dc1339b68d8c', 'Pike (TRX)', 'Core', 'TRX', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Suspender Pike, focusing on your abs. The TRX allows you to adjust difficulty by changing your body angle. A strong core improves posture, protects your spine, and enhances all other lifts.', '95001201', '95001201-Suspender-Pike-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:29.971345+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Pike. 2. Set up in the starting position for Suspender Pike. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 40, 7, 8, TRUE, TRUE, 'general_exercise', 'Suspender Pike', 'squat, bench_press, deadlift', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('334c00ea-600e-4bef-aeb5-0508b5e3c9d8', 'Ankle Circles', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger calves with this targeted movement exercise. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '39311201', '39311201-Ankle-Circles-(female)_Calves-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:30.54809+00', '1. Set up in the starting position for Ankle Circles. 2. Execute the movement with proper form, focusing on your calves. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Ankle Circles', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('334e2dd3-ffbd-43c2-a59d-8e898a16a1c9', 'Lying T Raise', 'Shoulders', 'Bodyweight', '{"Rear Delts"}'::text[], '{"Upper Back","Rotator Cuff"}'::text[], 'Build a stronger back with this raising movement targeting your core. Performing this lying down removes momentum for stricter form. This bodyweight exercise requires no equipment and can be done anywhere. Back development is crucial for pulling strength and overall upper body function.', '90371201', '90371201-Lying-T-Raise-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:35.38119+00', '1. Lie down in the appropriate position for Lying T Raise. 2. Raise the weight in the prescribed direction for Lying T Raise. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'lateral_raise', 'Lying T Raise', 'shoulder_press, front_raise, rear_delt', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('33643037-3f16-48bd-aee2-03c3e9d1e81c', 'Skater Hops', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Quads","Hip Abductors"}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. No equipment needed—your body provides all the resistance. Develops fast-twitch muscle fibers for quicker, more powerful movements. Perfect for including in both strength and hypertrophy programs.', '38201201', '38201201-Skater-Hops-(female)_Plyometric.mp4', 'female', FALSE, '2025-12-03 23:26:37.99429+00', '1. Set up in the starting position for Skater Hops. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'skater', 'Skater Hops', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('3365de84-1227-4340-8dc9-f9d9aa4542a5', 'Seated Learning Back Stretch', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Lower Back"}'::text[], 'Designed to lengthen your back, the Seated Learning Back Stretch helps improve mobility and prevent stiffness. The seated position helps isolate the target muscles by removing momentum. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '55031201', '55031201-Seated-Learning-Back-Stretch_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:24.099303+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Learning Back Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'back_stretch', 'Seated Learning Back Stretch', 'stretch_hip, stretch_hamstring, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('3366484a-8859-4a21-aa83-39194e753ae3', 'Seated Row (Machine)', 'Back', 'Machine', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Lever Seated Row is a rowing exercise that builds thickness in your upper back. Secondary activation of your biceps, lats provides additional muscle engagement. The seated position helps isolate the target muscles by removing momentum. Machine exercises are great for isolating muscles and training to failure safely. Back development is crucial for pulling strength and overall upper body function.', '70171201', '70171201-Lever-Seated-Row-(version-2)-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Seated Row. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, 'Seated', NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 90, 7, 9, TRUE, FALSE, 'cable_row', 'Lever Seated Row', 'squat, bench_press, deadlift', TRUE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('3369101b-e5b8-44af-ae5f-f5a50a484f83', 'Contralateral Reverse Lunge (Kettlebell)', 'Legs', 'Kettlebell', '{"Glutes"}'::text[], '{"Quads","Hamstrings"}'::text[], 'Build stronger quads with this lunging movement that develops leg drive and power. Secondary activation of your glutes, hamstrings provides additional muscle engagement. The kettlebell''s offset center of mass increases the stability challenge. Strong legs are the foundation for athletic performance and functional fitness.', '75811201', '75811201-Kettlebell-Contralateral-Reverse-Lunge-(male)_Thig.mp4', 'male', FALSE, '2025-12-03 23:26:26.808474+00', '1. Select an appropriately weighted kettlebell for Kettlebell Contralateral Reverse Lunge. 2. Step backward, lowering your back knee toward the floor. 3. Push through your front/working leg to return to the starting position. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'lunge', 'Contralateral Reverse Lunge', 'split_squat, step_up, squat', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('336d9125-5d8d-4cd1-862c-e9740d2bf6f3', 'Isometric Hold Chin Up - Close Grip (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'The Isometric Hold Close Grip Chin Up is a movement exercise that targets your latissimus dorsi for a wider back. The biceps assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. A strong back improves posture, prevents injury, and balances pressing movements.', '93201201', '93201201-Isometric-Hold-Close-Grip-Chin-Up-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:34.196858+00', '1. Use a close/narrow grip (hands closer than shoulder-width). 2. Pull yourself up, focusing on bicep and lat engagement. 3. Raise until chin is over the bar, lower with full control. 4. Hold the position for the prescribed time, maintaining tension.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 65, 7, 8, TRUE, TRUE, 'pull_up', 'Isometric Hold Chin Up - Close Grip', 'Isometric Hold Chin Up - Close Grip', TRUE, 'pull_up_bar', TRUE, 3, 90, 4, 70, 88, 95, 65),
('33817695-db7c-4c15-9540-a8f833ed7899', 'Weighted Bag Walking Lunge', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this lunging movement that develops leg drive and power. Secondary activation of your glutes, hamstrings provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '87011201', '87011201-Weighted-Bag-Walking-Lunge-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:27.145158+00', '1. Step forward into a lunge, then bring your back foot forward for the next step. 2. Push through your front/working leg to return to the starting position. 3. Repeat for the prescribed number of repetitions. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 70, 9, 8, FALSE, TRUE, 'lunge', 'Weighted Bag Walking Lunge', 'split_squat, step_up, squat', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('33828915-00ca-4bc8-8a88-6a316b958820', 'Plank Side Walk', 'Core', 'Bodyweight', '{"Core","Abs"}'::text[], '{"Shoulders"}'::text[], 'Strengthen your midsection with this stabilization movement that works your abs. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '56271201', '56271201-Plank-Side-Walk-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:25.341124+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Repeat for the prescribed number of repetitions. Keep your core engaged for stability. Great for building strength in your abs.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Plank Side Walk', 'side_plank, dead_bug, hollow_hold', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('33879284-cfd9-40f1-aa74-bb938f9a678a', 'Kneeling Staggered Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger chest with this pushing movement that develops pressing power. Secondary activation of your triceps, front delts provides additional muscle engagement. Kneeling helps eliminate lower body momentum from the movement. A versatile bodyweight movement perfect for home or gym training. A well-developed chest contributes to upper body strength and aesthetics. Works well as both a primary exercise or accessory movement.', '52781201', '52781201-Kneeling-Staggered-Push-up-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:34.487002+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Complete all reps with control before resting. Control the movement—avoid using momentum. A solid choice for chest day.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Kneeling Staggered Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('33913a11-a372-4955-b0e6-669d6f0cddf8', 'Lying Legs Extension Abduction', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Lying Legs Extension Abduction is a lower body extension exercise that targets your glute med/abductors. The lying position provides back support and helps isolate the target muscles. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '96581201', '96581201-Lying-Legs-Extension-Abduction-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:21.109351+00', '1. Lie down in the appropriate position for Lying Legs Extension Abduction. 2. Extend your legs until straight, squeezing your quads at the top. 3. Lower with control back to the starting position. 4. Repeat for the prescribed number of repetitions. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'hip_abduction', 'Lying Legs Extension Abduction', 'leg_curl, squat, leg_press, lunge', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('339375e2-bd81-42a6-a207-0ad115e85604', 'Kneeling Push Up Jack', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Kneeling Push Up Jack is an explosive exercise that combines cardiovascular training with dynamic pushing movements. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. Kneeling helps eliminate lower body momentum from the movement. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '85971201', '85971201-Kneeling-Push-up-Jack-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:29.971345+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Repeat for the prescribed number of repetitions. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'push_up', 'Kneeling Push Up Jack', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('33a38a30-477e-4780-ba3a-ae97fa05ee89', 'Calf Raise Press (Machine)', 'Legs', 'Machine', '{"Calves"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Lever Calf Raise (bench Press Machine) isolates your calf muscles through a pressing motion. You''ll also feel your triceps, front delts working to support the movement. The fixed path allows you to focus purely on muscular effort. Strong legs are the foundation for athletic performance and functional fitness.', '12201201', '12201201-Lever-Calf-Raise-(Bench-Press-Machine)_Calves_.mp4', 'male', FALSE, '2025-12-03 23:26:25.87243+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Calf Raise. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 100, 5, 7, FALSE, TRUE, 'bench_press', 'Lever Calf Raise', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('33b93ee5-4d37-41bf-8257-bf17bf970e9a', 'Low Chest Fly (Band) - Alternating', 'Chest', 'Resistance Band', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Target your chest with the Band Alternate Low Chest Fly, an effective flying movement for upper body strength. You''ll also feel your front delts working to support the movement. Bands are joint-friendly and portable, perfect for any training environment. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '70351201', '70351201-Band-Alternate-Low-Chest-Fly-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:30.685158+00', '1. Secure the resistance band appropriately for Band Alternate Low Chest Fly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Alternate between sides/arms/legs with each repetition. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'chest_fly', 'Low Chest Fly - Alternating', 'bench_press, incline_press, push_up', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('33cedb02-9829-479e-bf4c-852e571e3b92', 'Lying Bent Knee Tibialis Press', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This pressing movement focuses on your gastrocnemius and soleus. The lying position provides back support and helps isolate the target muscles. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '105401201', '105401201-Lying-Bent-Knee-Tibialis-Press-(male)_Calves_.mp4', 'male', FALSE, '2025-12-03 23:26:23.172397+00', '1. Lie down in the appropriate position for Lying Bent Knee Tibialis Press. 2. Execute the pressing motion for Lying Bent Knee Tibialis Press, extending through the target muscles. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Bent Knee Tibialis Press', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('33d044d0-d0a9-4154-9edf-00e5bcfbca3f', '45 Degrees Side Bend', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. Secondary activation of your abs provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '24351201', '24351201-45-degrees-Side-Bend-(female)_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:30.292204+00', '1. Set up in the starting position for 45 Degrees Side Bend. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'side_bend', '45 Degrees Side Bend', 'russian_twist, woodchop, oblique_crunch', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('33fccca8-1098-484a-ae4a-0e82f4cea6cf', 'Lunge With Leg Lift', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Elevate your training with this lunging exercise that develops speed, power, and coordination. You''ll also feel your glutes, hamstrings working to support the movement. No equipment needed—your body provides all the resistance. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '38071201', '38071201-Lunge-with-Leg-Lift-(female)_Plyometrics-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:35.010404+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Complete all reps with control before resting. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'lunge', 'Lunge With Leg Lift', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('33fee322-9535-44bf-a773-372f77dfa2b2', 'Lying Single Arm Slide From Y To T', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Lying Single Arm Slide From Y To T provides a deep stretch for your full body, ideal for recovery and mobility work. Performing this lying down removes momentum for stricter form. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '107421201', '107421201-Lying-Single-Arm-Slide-from-Y-to-T-(male)_Stretch.mp4', 'male', FALSE, '2025-12-03 23:26:22.755209+00', '1. Lie down in the appropriate position for Lying Single Arm Slide From Y To T. 2. Move into the stretch position for Lying Single Arm Slide From Y To T. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 5. Switch sides and repeat for equal time. 6. Complete all reps on one side, then switch to the other side.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'arm_exercise', 'Lying Single Arm Slide From Y To T', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('340d6aa7-18ab-4302-8fd8-bac1fdb89993', 'Windmill Cut', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities. Progress gradually by increasing resistance over time.', '51401201', '51401201-Bodyweight-Windmill-Cut-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:31.60311+00', '1. Set up in the starting position for Bodyweight Windmill Cut. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'windmill', 'Windmill Cut', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('340e1976-641f-48e1-b8c9-2fbf013001f3', 'Air Twisting Crunch', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'This crunching movement focuses on your obliques for a complete core workout. The hip flexors assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Building core stability helps with everything from heavy deadlifts to daily activities.', '41201', '00041201-Air-Twisting-Crunch-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Complete all reps with control before resting. Don''t rush—quality over quantity. Include this in your core training.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 62, 5, 7, FALSE, TRUE, 'crunch', 'Air Twisting Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('341830ff-ae53-4db1-b4a6-52024dcc23a6', 'Superman Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Target your chest with the Superman Push Up, an effective pushing movement for upper body strength. The glutes assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. A well-developed chest contributes to upper body strength and aesthetics. Focus on controlled form throughout each repetition.', '8031201', '08031201-Superman-Push-up_Chest.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout. Ensure full range of motion on each rep. This exercise is excellent for chest development.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'back_extension', 'Superman Push Up', 'bench_press, chest_fly, dip, tricep_pushdown', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('342288d9-a052-4942-8201-8bfa044beaa3', 'Pulldown - Pro Lat Bar (Cable)', 'Back', 'Cables', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'The Cable Pulldown (pro Lat Bar) is a pulling exercise that targets your latissimus dorsi for a wider back. The biceps, upper back assist throughout the movement, making this a well-rounded exercise. Cables provide constant tension throughout the full range of motion. Back development is crucial for pulling strength and overall upper body function.', '1971201', '01971201-Cable-Pulldown-(pro-lat-bar)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:27.805708+00', '1. Adjust the cable machine to the correct height and attachment for Cable Pulldown. 2. Pull the bar/handle down toward your upper chest. 3. Drive your elbows down and back, squeezing your lats. 4. Control the weight back up without letting it yank your arms. 5. Repeat for the prescribed number of repetitions. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Pulldown', 'pull_up, bent_over_row, cable_row, face_pull', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('34238e1c-de21-4db4-81eb-ced10e8fedf0', 'Split Squat Front Foot Elevated (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Using dumbbells requires more stabilization than barbell variations. Strong legs are the foundation for athletic performance and functional fitness.', '29581201', '29581201-Dumbbell-Split-Squat-Front-Foot-Elevanted-(female).mp4', 'female', FALSE, '2025-12-03 23:26:33.168801+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Split Squat Front Foot Elevanted. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'split_squat', 'Split Squat Front Foot Elevanted', 'lunge, bulgarian_split_squat, squat', TRUE, 'dumbbell', FALSE, 4, 120, 5, 92, 90, 92, 90),
('343eb617-93a6-4836-9aed-76293e7ed7bb', 'Elevated Legs Hip Thrust (Step Platform)', 'Legs', 'Step Platform', '{"Glutes"}'::text[], '{"Hamstrings","Core"}'::text[], 'This thrusting exercise isolates your glutes for improved hip strength and power. Your hamstrings work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '76821201', '76821201-Elevated-Legs-Hip-Thrust-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Complete all reps with control before resting. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'hip_thrust', 'Elevated Legs Hip Thrust', 'glute_bridge, romanian_deadlift, leg_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3442bf02-e493-41af-a378-841e68b5139b', 'Side Bridge', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This bridging exercise engages your abs for improved core stability and strength. The hamstrings assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '7061201', '07061201-Side-Bridge_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:36.985772+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Continue for your target rep count, maintaining good form throughout. Focus on squeezing the target muscle at peak contraction. An effective movement for your core routine.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'glute_bridge', 'Side Bridge', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3443921c-2b7a-4fee-98bc-064b7e9d88dc', 'Side Hop Ski', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'The Side Hop Ski is an explosive exercise that combines cardiovascular training with dynamic movement movements. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning.', '69841201', '69841201-Side-Hop-Ski-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Set up in the starting position for Side Hop Ski. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'hop', 'Side Hop Ski', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('3446fa76-c964-4b7a-9c12-7e32e03f141c', 'Hip Thrust (Bench, Barbell)', 'Legs', 'Barbell', '{"Glutes"}'::text[], '{"Hamstrings","Core"}'::text[], 'This thrusting exercise isolates your glutes for improved hip strength and power. You''ll also feel your hamstrings working to support the movement. Using a barbell provides stability for progressive overload. Strong legs are the foundation for athletic performance and functional fitness.', '10601201', '10601201-Barbell-Hip-Thrust_Hips-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:22.536005+00', '1. Grip a barbell with hands at the appropriate width for Barbell Hip Thrust. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Continue for your target rep count, maintaining good form throughout. Start with lighter weight to perfect your form.', 'Hip Extension', 'Push', 'Compound', 'Bilateral', NULL, 3, NULL, 7, 8, NULL, 5, 'Seated/Supported', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 74, 7, 8, TRUE, TRUE, 'hip_thrust', 'Hip Thrust', 'glute_bridge, romanian_deadlift, leg_curl', TRUE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('34477dfa-8f36-4921-bb33-694089c4641e', 'Hip Thrust Side Step', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings","Core"}'::text[], 'Develop your posterior chain with this thrusting movement that emphasizes the glutes. Secondary activation of your hamstrings provides additional muscle engagement. Strong legs are the foundation for athletic performance and functional fitness.', '66861201', '66861201-Hip-Thrust-Side-Step-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:34.073704+00', '1. Set up a box or step platform at the appropriate height. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Continue for your target rep count, maintaining good form throughout. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'hip_thrust', 'Hip Thrust Side Step', 'glute_bridge, romanian_deadlift, leg_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('34519ee9-034d-4269-b2ea-54daa0a89b36', 'Deadlift Shin Tap', 'Back', 'Bodyweight', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'The Bodyweight Deadlift Shin Tap is a lower body hip hinge exercise that targets your hamstrings/glutes. The glutes, lower back assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '87911201', '87911201-Bodyweight-Deadlift-Shin-Tap-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:31.347577+00', '1. Hinge at hips and bend knees to grip the weight. 2. Drive through your heels, extending hips and knees to stand. 3. Lower by reversing the movement with control. 4. Repeat for the prescribed number of repetitions. Don''t rush—quality over quantity. An effective movement for your legs routine.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'deadlift', 'Deadlift Shin Tap', 'romanian_deadlift, hip_thrust, leg_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('34521322-8dcb-4e21-9583-c6673c82ea04', 'Lying Supine Hip Abduction (Resistance Band)', 'Legs', 'Resistance Band', '{"Glutes"}'::text[], '{"Hip Abductors"}'::text[], 'The Resistance Band Lying Supine Hip Abduction is a lower body movement exercise that targets your hip abductors. Secondary activation of your glutes provides additional muscle engagement. Performing this lying down removes momentum for stricter form. The band creates increasing tension as it stretches, challenging the lockout. Strong legs are the foundation for athletic performance and functional fitness.', '101281201', '101281201-Resistance-Band-Lying-Supine-Hip-Abduction-(femal.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band Lying Supine Hip Abduction. 2. Lie on your back with your body relaxed but ready. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'hip_abduction', 'Lying Supine Hip Abduction', 'hip_adduction, glute_bridge, clamshell', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('345916fc-03d1-4b50-b00f-f84e25c4bedd', 'Press - Reverse Grip (Smith Machine)', 'Chest', 'Smith Machine', '{"Chest","Triceps"}'::text[], '{"Front Delts","Forearms"}'::text[], 'Build a stronger chest with this pressing movement that develops pressing power. The machine guides your movement path for safer, more controlled repetitions. A well-developed chest contributes to upper body strength and aesthetics.', '7641201', '07641201-Smith-Reverse-Grip-Press_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:21.890719+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Reverse Grip Press. 2. Use a reverse grip (opposite of the standard grip for this exercise). 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'general_exercise', 'Smith Press - Reverse Grip', 'Press - Reverse Grip', FALSE, 'smith_machine', FALSE, 3, 90, 4, 80, 75, 20, 88);
INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('3459b8f6-c1b9-4cf6-94d5-60f73b6447c9', 'Seated Side Bend With Arm Up (Chair)', 'Core', 'Chair', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Seated Side Bend With Arm Up On Chair targets your obliques through a movement motion, building rotational core strength. Secondary activation of your abs provides additional muscle engagement. Being seated provides stability, allowing you to focus on the working muscles. Building core stability helps with everything from heavy deadlifts to daily activities.', '104971201', '104971201-Seated-Side-Bend-with-Arm-Up-on-Chair-(male)_Wais.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Repeat for the prescribed number of repetitions. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 37, 7, 8, TRUE, TRUE, 'side_bend', 'Seated Side Bend With Arm Up On Chair', 'russian_twist, woodchop, oblique_crunch', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('345ac913-fb04-49e5-b751-c4bd9f0d75d2', 'Seated Leg Extension (Dumbbell)', 'Legs', 'Dumbbells, Flat Bench', '{"Quads"}'::text[], '{}'::text[], 'Target the front of your thighs with this extension exercise for quad development. The seated position helps isolate the target muscles by removing momentum. Dumbbells allow each arm to work independently, helping correct imbalances. Strong legs are the foundation for athletic performance and functional fitness.', '93971201', '93971201-Dumbbell-Sitting-Leg-Extension-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:23.466497+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Seated Leg Extension. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Extend your legs until straight, squeezing your quads at the top. 4. Lower with control back to the starting position. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'leg_extension', 'Seated Leg Extension', 'squat, leg_press, lunge', FALSE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('34625812-6843-4e51-9ef6-95bc3c43dd3f', 'Side Squat Step', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. You''ll also feel your glutes, hamstrings working to support the movement. Lower body strength improves everything from walking to heavy compound lifts. Control the negative portion for maximum muscle engagement.', '85831201', '85831201-Bodyweight-Side-Squat-Step-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Set up a box or step platform at the appropriate height. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps with control before resting. Focus on the mind-muscle connection.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Side Squat Step', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('346fed68-6092-463f-a9b3-0d3c520d6d17', 'Kneeling Side Crunch (Cable)', 'Core', 'Cables', '{"Obliques"}'::text[], '{"Hip Flexors","Abs"}'::text[], 'Strengthen your midsection with this crunching movement that works your abs. Secondary activation of your abs provides additional muscle engagement. The kneeling position adds a core stability challenge. Cables provide constant tension throughout the full range of motion. A strong core improves posture, protects your spine, and enhances all other lifts.', '66931201', '66931201-Cable-Kneeling-Side-Crunch-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:24.099303+00', '1. Adjust the cable machine to the correct height and attachment for Cable Kneeling Side Crunch. 2. Kneel on the floor (use a pad for comfort if needed). 3. Curl your shoulders off the floor by contracting your abs. 4. Don''t pull on your neck—focus on the abdominal contraction. 5. Lower with control, maintaining some tension. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'crunch', 'Kneeling Side Crunch', 'leg_raise, plank, russian_twist, v_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('347fd40e-d2b5-455e-9640-828beb4280bb', 'Mountain Climber', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors","Shoulders"}'::text[], 'The Mountain Climber is a cardiovascular exercise that improves endurance and heart health. The hip flexors, shoulders assist throughout the movement, making this a well-rounded exercise. Regular cardio training builds the aerobic base for better overall fitness.', '6301201', '06301201-Mountain-Climber_Cardio-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:21.608253+00', '1. From plank position, drive one knee toward your chest. 2. Quickly switch legs, bringing the other knee forward. 3. Continue alternating at a quick pace while maintaining plank form. 4. Repeat for the prescribed number of repetitions. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'mountain_climber', 'Mountain Climber', 'burpee, plank, high_knees', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('348a570c-4501-4006-8cc3-8a81fa78ae0f', 'Seated Hip External Rotation', 'Shoulders', 'Bodyweight', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'Build leg strength with this rotation movement focusing on your rotator cuff. The seated position helps isolate the target muscles by removing momentum. Lower body strength improves everything from walking to heavy compound lifts.', '67491201', '67491201-Seated-Hip-External-Rotation-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Rotate your torso through the movement pattern for Seated Hip External Rotation. 3. Control the rotation in both directions—avoid using momentum. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'external_rotation', 'Seated Hip External Rotation', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('348c8a43-8d93-44fc-a2c4-54d6bccace02', 'Lying Frog Push Abduction', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Lying Frog Push Abduction is a lower body pushing exercise that targets your glute med/abductors. Performing this lying down removes momentum for stricter form. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '97141201', '97141201-Lying-Frog-Push-Abduction-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.133808+00', '1. Lie down in the appropriate position for Lying Frog Push Abduction. 2. Set up in the starting position for Lying Frog Push Abduction. 3. Execute the movement with proper form, focusing on your glute med/abductors. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_abduction', 'Lying Frog Push Abduction', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('34a7c83d-b03d-4d65-9526-c6897fc98863', 'Overhead Carry (Kettlebell)', 'Core', 'Kettlebell', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your core. Secondary activation of your shoulders provides additional muscle engagement. Kettlebells are excellent for building functional, real-world strength. A strong core improves posture, protects your spine, and enhances all other lifts.', '42441201', '42441201-Kettlebell-Overhead-Carry_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:23.172397+00', '1. Select an appropriately weighted kettlebell for Kettlebell Overhead Carry. 2. Set up in the starting position for Kettlebell Overhead Carry. 3. Execute the movement with proper form, focusing on your core. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'farmer_carry', 'Overhead Carry', 'squat, bench_press, deadlift', FALSE, 'kettlebell', TRUE, 3, 90, 4, 75, 88, 88, 78),
('34b17f25-9e9f-4012-bb15-9af030213d25', 'Ape Traverse', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Build power and athleticism with this high-intensity movement exercise that challenges your entire body. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning. Excellent for pre-exhausting the target muscle before compound lifts.', '75961201', '75961201-Ape-Traverse-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:27.504261+00', '1. Set up in the starting position for Ape Traverse. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Ape Traverse', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('34d6c805-cb58-4d07-9763-9c3d7b29ba52', 'Double Leg Stretch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Target your full body with this stretching stretch that helps restore range of motion. Regular stretching improves flexibility, reduces injury risk, and aids recovery. Works well as both a primary exercise or accessory movement.', '28431201', '28431201-Double-Leg-Stretch_Pilates_.mp4', 'female', FALSE, '2025-12-03 23:26:32.624497+00', '1. Move into the stretch position for Double Leg Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Double Leg Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('34d80604-9701-4bf0-a1de-983ee8ed8307', 'Lying Floor Row With Bent Knee', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. Your biceps, rear delts work as secondary movers, adding to the training stimulus. The lying position provides back support and helps isolate the target muscles. This bodyweight exercise requires no equipment and can be done anywhere. A strong back improves posture, prevents injury, and balances pressing movements.', '70881201', '70881201-Lying-Floor-Row-with-Bent-Knee-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:35.133808+00', '1. Position yourself on the floor for Lying Floor Row With Bent Knee. 2. Lie down in the appropriate position for Lying Floor Row With Bent Knee. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 65, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Floor Row With Bent Knee', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('34eaea45-a99d-4d87-a14a-b710b298edf3', 'Seated Leg Extension (Band)', 'Legs', 'Resistance Band', '{"Quads"}'::text[], '{}'::text[], 'Target the front of your thighs with this extension exercise for quad development. Being seated provides stability, allowing you to focus on the working muscles. Resistance bands provide accommodating resistance that increases through the range of motion. Strong legs are the foundation for athletic performance and functional fitness.', '35181201', '35181201-Band-Seated-Leg-Extension-(male)_Thighs.mp4', 'male', FALSE, '2025-12-03 23:26:24.203368+00', '1. Secure the resistance band appropriately for Band Seated Leg Extension. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Extend your legs until straight, squeezing your quads at the top. 4. Lower with control back to the starting position. 5. Complete all reps with control before resting. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 87, 5, 7, FALSE, TRUE, 'leg_extension', 'Seated Leg Extension', 'squat, leg_press, lunge', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('34f012c4-815f-43e9-9af0-dba9ef3449c3', 'Jab Jab Right Cross', 'Full Body', 'Bodyweight', '{"Shoulders"}'::text[], '{"Biceps","Triceps","Core"}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. Secondary activation of your shoulders, core provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '67281201', '67281201-Jab-Jab-Right-Cross-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:21.732034+00', '1. Set up in the starting position for Jab Jab Right Cross. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Jab Jab Right Cross', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('34f2875e-4464-4465-b645-2d1d6b696a0a', 'Seated Front Raise With Twist (Dumbbell)', 'Shoulders', 'Dumbbells, Flat Bench', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'Build stronger shoulders with this raising movement focusing on your front delts. The seated position helps isolate the target muscles by removing momentum. The dumbbell variation provides freedom of movement and greater range of motion. Shoulder development enhances both performance and upper body aesthetics. Works well as both a primary exercise or accessory movement.', '105151201', '105151201-Dumbbell-Seated-Front-Raise-with-Twist_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:26.507873+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Seated Front Raise With Twist. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Raise the weight in front of you to shoulder height. 4. Lower with control, maintaining tension throughout. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 84, 5, 7, FALSE, TRUE, 'front_raise', 'Seated Front Raise With Twist', 'shoulder_press, lateral_raise, rear_delt_fly', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('35004f35-421f-4736-8f0b-c42778ee0e1d', 'Straight Arm Pulldown - Rope (Cable)', 'Back', 'Cables', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'The Cable Straight Arm Pulldown (with Rope) is a pulling exercise that targets your latissimus dorsi for a wider back. The cable setup allows you to adjust the angle of resistance. Back development is crucial for pulling strength and overall upper body function.', '2371201', '02371201-Cable-Straight-Arm-Pulldown-(with-rope)_Back.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Adjust the cable machine to the correct height and attachment for Cable Straight Arm Pulldown. 2. Pull the bar/handle down toward your upper chest. 3. Drive your elbows down and back, squeezing your lats. 4. Control the weight back up without letting it yank your arms. 5. Repeat for the prescribed number of repetitions. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Straight Arm Pulldown', 'pull_up, bent_over_row, cable_row, face_pull', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('35106aaa-6967-46b4-a838-b4e030647116', 'Kneeling Twist (Machine)', 'Core', 'Machine', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Build rotational power and define your waistline with the Lever Kneeling Twist. You''ll also feel your abs working to support the movement. Kneeling helps eliminate lower body momentum from the movement. Machine exercises are great for isolating muscles and training to failure safely. Building core stability helps with everything from heavy deadlifts to daily activities.', '5831201', '05831201-Lever-Kneeling-Twist_Waist-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:24.099303+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Kneeling Twist. 2. Kneel on the floor (use a pad for comfort if needed). 3. Rotate your torso through the movement pattern for Lever Kneeling Twist. 4. Control the rotation in both directions—avoid using momentum. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 58, 5, 7, FALSE, TRUE, 'russian_twist', 'Lever Kneeling Twist', 'squat, leg_extension, lunge', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('351bb9aa-cd39-45af-b2e9-7a98b750b715', 'Roll Neck Decompress Lying On Floor', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your neck with this pressing exercise for improved stability. Performing this lying down removes momentum for stricter form. A versatile bodyweight movement perfect for home or gym training. Include this exercise in your routine for balanced strength development.', '54111201', '54111201-Roll-Neck-Decompress-Lying-on-Floor-(female)_Neck_.mp4', 'female', FALSE, '2025-12-03 23:26:36.38616+00', '1. Position yourself on the floor for Roll Neck Decompress Lying On Floor. 2. Lie down in the appropriate position for Roll Neck Decompress Lying On Floor. 3. Execute the pressing motion for Roll Neck Decompress Lying On Floor, extending through the target muscles. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'neck_exercise', 'Roll Neck Decompress Lying On Floor', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('352dc936-45e9-4e7e-aa58-5d372d001480', 'Step Up Knee Raise On Stepbox - Stick (Step Platform)', 'Legs', 'Step Platform', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Stick Step Up Knee Raise On Stepbox is a lower body raising exercise that targets your abs. Secondary activation of your hip flexors provides additional muscle engagement. Lower body strength improves everything from walking to heavy compound lifts.', '100161201', '100161201-Stick-Step-up-Knee-Raise-on-Stepbox-(female)_Thig.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Set up a box or step platform at the appropriate height. 2. Raise the weight in the prescribed direction for Stick Step Up Knee Raise On Stepbox. 3. Lower with control, maintaining tension throughout. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'leg_raise', 'Stick Step Up Knee Raise On Stepbox', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3533184e-08ed-48d0-af87-abacd6badb4c', 'Stepback Opposite Grab', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'A challenging plyometric exercise, the Stepback Opposite Grab builds reactive power and improves conditioning. The quads assist throughout the movement, making this a well-rounded exercise. Great for improving athletic performance, burning calories, and building conditioning.', '76591201', '76591201-Stepback-Opposite-Grab-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.21093+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Stepback Opposite Grab. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_exercise', 'Stepback Opposite Grab', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('35333b7e-2256-4264-a487-c00a100ddf1a', 'Inverse Leg Curl With Bench Pads', 'Legs', 'Bodyweight', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'Strengthen the back of your thighs with this curling exercise. Your calves work as secondary movers, adding to the training stimulus. Leg training boosts metabolism and builds functional, real-world strength. Start with lighter weight to master the movement pattern.', '81111201', '81111201-Inverse-Leg-Curl-with-Bench-Pads-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:34.073704+00', '1. Curl your heels toward your glutes by bending at the knees. 2. Squeeze your hamstrings at peak contraction. 3. Extend legs back out with control. 4. Continue for your target rep count, maintaining good form throughout. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 80, 7, 8, TRUE, TRUE, 'leg_curl', 'Inverse Leg Curl With Bench Pads', 'romanian_deadlift, hip_thrust', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('35336138-b263-48c5-8efe-1a6b1b391019', 'Incline Chest Press (Plate Loaded Machine)', 'Chest', 'Machine', '{"Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'Build a stronger chest with this pressing movement that develops pressing power. Your triceps, front delts work as secondary movers, adding to the training stimulus. The incline angle shifts emphasis toward the upper portion of the target muscles. Machine exercises are great for isolating muscles and training to failure safely. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '12991201', '12991201-Lever-Incline-Chest-Press_Chest-FIX2_.mp4', 'male', FALSE, '2025-12-03 23:26:20.982555+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Incline Chest Press. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 81, 7, 8, TRUE, TRUE, 'incline_press', 'Lever Incline Chest Press', 'bench_press, shoulder_press, chest_fly', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('353e4363-b637-4956-bcdc-e9660ae68680', 'Side Glute Raise (Chair)', 'Legs', 'Chair', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'The Side Glute Raise Chair Supported is a hip-dominant raising exercise that targets your glutes. Lower body strength improves everything from walking to heavy compound lifts.', '85891201', '85891201-Side-Glute-Raise-Chair-Supported-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:36.985772+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 55, 5, 7, FALSE, TRUE, 'glute_exercise', 'Side Glute Raise Chair Supported', 'shoulder_press, front_raise, rear_delt_fly, upright_row', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('3542c724-c934-4512-9cd2-4f6c83201bca', 'Body Rock To Down Dog', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Target your full body with this movement stretch that helps restore range of motion. Regular stretching improves flexibility, reduces injury risk, and aids recovery. Perfect for including in both strength and hypertrophy programs. Consistency with this movement will yield noticeable results.', '77631201', '77631201-Body-Rock-to-Down-Dog-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:31.347577+00', '1. Move into the stretch position for Body Rock To Down Dog. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Body Rock To Down Dog', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('354b4b76-83b0-4c66-b92f-93789b5da189', 'Preacher Curl - Hammer Grip (Machine)', 'Arms', 'Machine', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Lever Hammer Grip Preacher Curl is a curling exercise that isolates your biceps. Secondary activation of your forearms provides additional muscle engagement. Machine exercises are great for isolating muscles and training to failure safely. Dedicated arm training builds both strength and muscular definition.', '16151201', '16151201-Lever-Hammer-Grip-Preacher-Curl_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:25.87243+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Hammer Grip Preacher Curl. 2. Use a hammer/neutral grip with palms facing each other throughout. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 88, 5, 7, FALSE, TRUE, 'preacher_curl', 'Lever Hammer Grip Preacher Curl', 'tricep_pushdown, tricep_extension, bicep_curl, hammer_curl', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('354db962-69a7-4a29-999b-e47c70213f06', 'Foot Hopscotch - Alternating', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'Build power and athleticism with this high-intensity movement exercise that challenges your entire body. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning. Aim for full range of motion on every rep.', '80731201', '80731201-Alternate-Foot-Hopscotch-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:29.837118+00', '1. Alternate between sides/arms/legs with each repetition. 2. Set up in the starting position for Alternate Foot Hopscotch. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'hop', 'Foot Hopscotch - Alternating', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('3560e4de-1904-491e-bb25-85709d55d40d', 'Seated Bent Over Row And Fly (Dumbbell)', 'Back', 'Dumbbells, Flat Bench, Chair', '{"Back","Lats"}'::text[], '{"Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. Your biceps, lats work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. Dumbbells allow each arm to work independently, helping correct imbalances. Back development is crucial for pulling strength and overall upper body function.', '104901201', '104901201-Dumbbell-Seated-Bent-Over-Row-and-Fly-on-Chair-(m.mp4', 'male', FALSE, '2025-12-03 23:26:24.203368+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Seated Bent Over Row And Fly On Chair. 2. Position yourself with a sturdy chair for support or as part of the movement. 3. Sit with your back supported, core engaged, feet flat on the floor. 4. Pull the weight toward your torso, leading with your elbow(s). 5. Squeeze your shoulder blades together at the peak contraction. 6. Extend back out with control, feeling the stretch in your back. 7. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, 'Seated', NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 69, 7, 9, TRUE, FALSE, 'bent_over_row', 'Seated Bent Over Row And Fly On Chair', 'cable_row, dumbbell_row, t_bar_row, lat_pulldown', TRUE, 'dumbbell', FALSE, 4, 120, 4, 92, 90, 92, 90),
('3563d98b-28d0-4b47-929b-363121d53e65', 'Bicep Curl - Lying (Towel)', 'Arms', 'Towel', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. The forearms assist throughout the movement, making this a well-rounded exercise. The lying position provides back support and helps isolate the target muscles. Arm strength supports grip, pulling, and pushing in compound movements.', '81001201', '81001201-Lying-Biceps-Curl-with-Towel-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:35.133808+00', '1. Lie down in the appropriate position for Lying Biceps Curl With Towel. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'bicep_curl', 'Lying Biceps Curl With Towel', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('35761ed4-9616-4bef-8c7a-89565a51e990', 'Chest Press - Single Arm (Plate Loaded Machine)', 'Chest', 'Machine', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pressing exercise focuses on your pectorals for improved chest strength and development. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. The fixed path allows you to focus purely on muscular effort. A well-developed chest contributes to upper body strength and aesthetics. Quality repetitions are more important than quantity.', '97461201', '97461201-Lever-Single-Arm-Chest-Press-(plate-loaded)-(femal.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Single Arm Chest Press. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Complete all reps on one side, then switch to the other side. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 73, 7, 8, TRUE, TRUE, 'bench_press', 'Lever Single Arm Chest Press', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('35862923-52a2-4459-9531-d3479d42bfbe', 'Walking On Spot Shoulder Tap Raise', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Elevate your training with this raising exercise that develops speed, power, and coordination. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '92601201', '92601201-Walking-On-Spot-Shoulder-Tap-Raise-(front-POV)-(fe.mp4', 'female', FALSE, '2025-12-03 23:26:39.91585+00', '1. Raise the weight in front of you to shoulder height. 2. Lower with control, maintaining tension throughout. 3. Complete all reps with control before resting. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Cardio', 70, 5, 7, FALSE, TRUE, 'walking', 'Walking On Spot Shoulder Tap Raise', 'lateral_raise, shoulder_press, front_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('358acfad-c8f3-415d-a588-773753756458', 'Back Kick Heel Touches', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'A challenging plyometric exercise, the Back Kick Heel Touches builds reactive power and improves conditioning. Your abs work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '96441201', '96441201-Back-Kick-Heel-Touches-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:26.808474+00', '1. Set up in the starting position for Back Kick Heel Touches. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_exercise', 'Back Kick Heel Touches', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3599ffc0-9fdb-48dd-95b0-5ae65e82bcf1', 'Arm Leg Lift To Split Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Arm Leg Lift To Split Squat is a squatting exercise that primarily loads your quadriceps. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '71931201', '71931201-Arm-Leg-Lift-to-Split-Squat-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:30.54809+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Repeat for the prescribed number of repetitions. Keep the movement smooth and controlled. This exercise is excellent for quads development.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'split_squat', 'Arm Leg Lift To Split Squat', 'lunge, bulgarian_split_squat, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('359e544c-c3b0-4c76-9b2f-d274ddcba17d', 'Hip Thrust', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings","Core"}'::text[], 'Build stronger glutes with this thrusting movement focused on hip extension. Your hamstrings work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '21451201', '21451201-Hip-Thrusts-(Female)_Hips-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:34.073704+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Complete all reps with control before resting. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'hip_thrust', 'Hip Thrust', 'glute_bridge, romanian_deadlift, leg_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('35b46e01-f5de-47f8-89fd-3084e9b4e20d', 'Incline Row (Dumbbell)', 'Back', 'Dumbbells, Incline Bench', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. You''ll also feel your biceps, rear delts working to support the movement. Using an incline changes the angle of resistance for varied muscle recruitment. Using dumbbells requires more stabilization than barbell variations. Back development is crucial for pulling strength and overall upper body function.', '25101201', '25101201-Dumbbell-Incline-Row-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:32.914483+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Incline Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Continue for your target rep count, maintaining good form throughout. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 85, 7, 9, TRUE, FALSE, 'dumbbell_row', 'Incline Row', 'lat_pulldown, bent_over_row, pull_up', TRUE, 'dumbbell', FALSE, 4, 120, 4, 92, 90, 92, 90),
('35c86936-a99e-4a9d-9732-5d52e20e2828', 'Clean (Dumbbell)', 'Full Body', 'Dumbbells', '{"Full Body"}'::text[], '{"Quads","Glutes","Traps"}'::text[], 'Develop functional strength with the Dumbbell Clean, a comprehensive movement exercise. The quads, glutes, traps assist throughout the movement, making this a well-rounded exercise. Using dumbbells requires more stabilization than barbell variations. Full body exercises are time-efficient and build functional, real-world strength.', '57871201', '57871201-Dumbbell-Clean-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:32.735372+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Clean. 2. Explosively pull the weight upward from the starting position. 3. Pull yourself under the weight and catch it at shoulder level. 4. Stand to complete the lift, then lower with control. 5. Continue for your target rep count, maintaining good form throughout. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 9, NULL, TRUE, NULL, 'Strength', 62, 7, 9, TRUE, FALSE, 'clean', 'Clean', 'power_clean, deadlift, front_squat', FALSE, 'dumbbell', FALSE, 4, 120, 6, 92, 90, 92, 90),
('35d21648-a23b-416a-8cf5-3e34e638bc2c', 'Ring Wide Pull Up (Gymnastic Rings)', 'Back', 'Gymnastic Rings', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'The Ring Wide Pull Up is a pulling exercise that targets your latissimus dorsi for a wider back. You''ll also feel your biceps, upper back working to support the movement. Back development is crucial for pulling strength and overall upper body function.', '72281201', '72281201-Ring-Wide-Pull-up-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Use a wide grip (wider than shoulder-width) for this variation. 2. Pull yourself up by driving your elbows down and back. 3. Continue until your chin clears the bar, then lower with control to a full hang. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'pull_up', 'Ring Wide Pull Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'gymnastic_rings', FALSE, 3, 90, 4, 68, 85, 85, 70),
('35dddafd-2699-4adb-8762-4c3ad30fd756', 'Rear Fly Stepback', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Quads"}'::text[], 'A challenging plyometric exercise, the Rear Fly Stepback builds reactive power and improves conditioning. You''ll also feel your quads working to support the movement. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '55961201', '55961201-Rear-Fly-Stepback-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:35.936279+00', '1. Set up a box or step platform at the appropriate height. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'rear_delt', 'Rear Fly Stepback', 'bench_press, incline_bench_press, push_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('35f2761a-6263-4f4d-ad84-4ab52a72939d', 'Seal Pose', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Designed to lengthen your full body, the Seal Pose helps improve mobility and prevent stiffness. Include this in your routine for better mobility and reduced muscle tension.', '79541201', '79541201-Seal-Pose-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:36.581585+00', '1. Move into the stretch position for Seal Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 50, 2, 6, FALSE, TRUE, 'general_exercise', 'Seal Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('35fc44e5-45d7-4482-8872-af7c5fbcca46', 'Bench Seated Press (Dumbbell)', 'Shoulders', 'Dumbbells, Flat Bench', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'The Dumbbell Bench Seated Press is a pressing exercise that targets your delts for shoulder development. The seated position helps isolate the target muscles by removing momentum. The dumbbell variation provides freedom of movement and greater range of motion. Strong shoulders improve overhead strength and support nearly all upper body movements.', '2901201', '02901201-Dumbbell-Bench-Seated-Press_Shoulders-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:29.61214+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Bench Seated Press. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 84, 7, 8, TRUE, TRUE, 'shoulder_press', 'Bench Seated Press', 'lateral_raise, front_raise, rear_delt', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('35febee4-b53c-4a85-abf9-808ad59a813e', 'Single Arm Curl (Cable)', 'Arms', 'Cables', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. Secondary activation of your forearms provides additional muscle engagement. Cables provide constant tension throughout the full range of motion. Arm strength supports grip, pulling, and pushing in compound movements. Keep your core engaged throughout the exercise.', '1901201', '01901201-Cable-One-Arm-Curl_Upper-Arms.mp4', 'male', FALSE, '2025-12-03 23:26:21.109351+00', '1. Adjust the cable machine to the correct height and attachment for Cable One Arm Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 75, 5, 7, FALSE, TRUE, 'bicep_curl', 'Single Arm Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('360cd33f-1dc2-4a4b-a6b1-825d96ae6674', 'Romanian Deadlift To Bent Over Row (Dumbbell)', 'Legs', 'Dumbbells', '{"Back","Lats"}'::text[], '{"Glutes","Lower Back"}'::text[], 'The Dumbbell Romanian Deadlift To Bent Over Row is a lower body rowing exercise that targets your hamstrings/glutes. Secondary activation of your biceps, lats provides additional muscle engagement. Bending over allows gravity to provide resistance in a different plane. Dumbbells allow each arm to work independently, helping correct imbalances. Leg training boosts metabolism and builds functional, real-world strength.', '74721201', '74721201-Dumbbell-Romanian-Deadlift-to-Bent-Over-Row_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:22.123147+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Romanian Deadlift To Bent Over Row. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'romanian_deadlift', 'Romanian Deadlift To Bent Over Row', 'deadlift, leg_curl, hip_thrust', FALSE, 'dumbbell', FALSE, 4, 120, 6, 92, 90, 92, 90),
('36123c6b-c059-41f8-8096-1708d17032aa', 'Standing Tibialis Raise (Wall Supported)', 'Full Body', 'Wall', '{"Full Body"}'::text[], '{}'::text[], 'Build leg strength with this raising movement focusing on your full body. The standing position engages your core for stability. Leg training boosts metabolism and builds functional, real-world strength.', '98031201', '98031201-Standing-Tibialis-Raise-Wall-Supported-(male)_Calv.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Position yourself at the appropriate distance from a wall. 2. Stand tall with your feet firmly planted. 3. Raise the weight in the prescribed direction for Standing Tibialis Raise Wall Supported. 4. Lower with control, maintaining tension throughout. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 64, 5, 7, FALSE, TRUE, 'general_exercise', 'Standing Tibialis Raise Wall Supported', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('36191c60-b384-4991-940c-bb3aaa64a14b', 'Lying Floor Fly', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'This flying exercise focuses on your pectorals for improved chest strength and development. You''ll also feel your front delts working to support the movement. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '88091201', '88091201-Lying-Floor-Fly-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:35.133808+00', '1. Position yourself on the floor for Lying Floor Fly. 2. Lie down in the appropriate position for Lying Floor Fly. 3. With a slight bend in your elbows, move the weight in a wide arc. 4. Squeeze your chest muscles at the center/top of the movement. 5. Return with control, feeling the stretch at the bottom. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 65, 5, 7, FALSE, TRUE, 'chest_fly', 'Lying Floor Fly', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('361aee89-be4e-4134-a515-35ce8d902003', 'Standing Air Bike Foot Tap', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. The standing position engages your core for stability. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities. Control the negative portion for maximum muscle engagement.', '83961201', '83961201-Standing-Air-Bike-Foot-Tap-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:25.341124+00', '1. Begin in a standing position with good posture. 2. Set up in the starting position for Standing Air Bike Foot Tap. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 37, 9, 8, FALSE, TRUE, 'cycling', 'Standing Air Bike Foot Tap', 'crunch, russian_twist, leg_raise', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('3623d5e8-e0dd-4d3d-977a-002bfe8e1ff7', 'Shoulder Pat Knee Raise', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This dynamic raising movement gets your heart rate up while developing explosive strength. Your hip flexors work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '71881201', '71881201-Shoulder-Pat-Knee-Raise-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:36.985772+00', '1. Raise the weight in the prescribed direction for Shoulder Pat Knee Raise. 2. Lower with control, maintaining tension throughout. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Shoulder Pat Knee Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('362d746d-1e11-4f44-9231-7c0fc2c8664c', 'Squat Jump (Resistance Band)', 'Legs', 'Resistance Band', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Resistance bands provide accommodating resistance that increases through the range of motion. Leg training boosts metabolism and builds functional, real-world strength. A staple exercise that belongs in most training programs.', '72051201', '72051201-Resistance-Band-Squat-Jump-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:36.266593+00', '1. Secure the resistance band appropriately for Resistance Band Squat Jump. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Explode upward from the bottom, jumping as high as possible. 5. Land softly with bent knees and immediately descend into the next rep. 6. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 90, 9, 8, TRUE, TRUE, 'squat_jump', 'Squat Jump', 'squat, lunge, leg_press', FALSE, 'band', FALSE, 3, 60, 4, 60, 85, 90, 50),
('3654cc8c-2443-4af2-8f0e-a0348d05cfea', 'Standing Hands On Hip Front And Back Open', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This full-body movement exercise challenges multiple muscle groups simultaneously. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. Full body exercises are time-efficient and build functional, real-world strength.', '95471201', '95471201-Standing-Hands-On-Hip-Front-And-Back-Open-(female).mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Stand tall with your feet firmly planted. 2. Set up in the starting position for Standing Hands On Hip Front And Back Open. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'back_exercise', 'Standing Hands On Hip Front And Back Open', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('365b2410-3f76-4981-a91b-f26ffb3161b4', 'Ipsilateral Single Leg Stiff Leg Deadlift (Dumbbell)', 'Legs', 'Dumbbells', '{"Hamstrings"}'::text[], '{"Glutes","Lower Back"}'::text[], 'Strengthen the back of your thighs with this hip hinge exercise. The glutes, lower back assist throughout the movement, making this a well-rounded exercise. Using dumbbells requires more stabilization than barbell variations. Leg training boosts metabolism and builds functional, real-world strength.', '76471201', '76471201-Dumbbell-Ipsilateral-Single-Leg-Stiff-Leg-Deadlift.mp4', 'male', FALSE, '2025-12-03 23:26:28.851102+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Push your hips back, lowering the weight along your legs with a flat back. 3. Lower until you feel a stretch in your hamstrings. 4. Drive hips forward to stand, squeezing glutes at the top. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 82, 7, 9, TRUE, FALSE, 'romanian_deadlift', 'Ipsilateral Single Leg Stiff Leg Deadlift', 'deadlift, leg_curl, hip_thrust', FALSE, 'dumbbell', FALSE, 4, 120, 6, 92, 90, 92, 90),
('365c2c94-22dd-4ac5-b879-289c5b8d6a9d', 'Single Leg Squat (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Using a barbell provides stability for progressive overload. Leg training boosts metabolism and builds functional, real-world strength. A staple exercise that belongs in most training programs.', '43491201', '43491201-Barbell-Single-Leg-Squat_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:21.608253+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Single Leg Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 92, 7, 9, TRUE, FALSE, 'pistol_squat', 'Single Leg Squat', 'squat, bench_press, deadlift', FALSE, 'barbell', FALSE, 4, 120, 5, 95, 80, 65, 95),
('36718d86-2834-4390-9ab2-b721ac93d6b8', 'Lying Bent Knee Raise (Resistance Band)', 'Core', 'Resistance Band', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this raising movement that works your abs. Secondary activation of your hip flexors provides additional muscle engagement. Performing this lying down removes momentum for stricter form. Resistance bands provide accommodating resistance that increases through the range of motion. Core strength is foundational for athletic performance and injury prevention.', '68101201', '68101201-Resistance-Band-Lying-Bent-Knee-Raise-(male)_Waist.mp4', 'male', FALSE, '2025-12-03 23:26:22.755209+00', '1. Secure the resistance band appropriately for Resistance Band Lying Bent Knee Raise. 2. Lie down in the appropriate position for Resistance Band Lying Bent Knee Raise. 3. Raise the weight in the prescribed direction for Resistance Band Lying Bent Knee Raise. 4. Lower with control, maintaining tension throughout. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 75, 5, 7, FALSE, TRUE, 'leg_raise', 'Lying Bent Knee Raise', 'crunch, plank, v_up', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('36883ede-dbde-4cab-b357-a750cd36263a', 'Negative Dragon Flag', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. This bodyweight exercise requires no equipment and can be done anywhere. Core strength is foundational for athletic performance and injury prevention. Start with lighter weight to master the movement pattern.', '52641201', '52641201-Negative-Dragon-Flag-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.532804+00', '1. Focus on a slow, controlled lowering phase (3-5 seconds). 2. Set up in the starting position for Negative Dragon Flag. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 5, 7, 8, TRUE, TRUE, 'general_exercise', 'Negative Dragon Flag', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('36905756-85c2-417d-aac5-4311ee207319', 'Frankenstein Squat (Smith Machine)', 'Legs', 'Smith Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. You''ll also feel your glutes, hamstrings working to support the movement. The machine guides your movement path for safer, more controlled repetitions. Strong legs are the foundation for athletic performance and functional fitness.', '15941201', '15941201-Smith-Frankenstein-Squat_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:21.995567+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Frankenstein Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 93, 7, 9, TRUE, FALSE, 'squat', 'Smith Frankenstein Squat', 'Frankenstein Squat', FALSE, 'smith_machine', FALSE, 4, 120, 5, 80, 75, 20, 88),
('36922d99-7bc0-436d-b4ab-3fcd5a6e1052', 'Side Bend Arms Above', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. You''ll also feel your abs working to support the movement. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention.', '63821201', '63821201-Side-Bend-Arms-Above-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:36.985772+00', '1. Set up in the starting position for Side Bend Arms Above. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'side_bend', 'Side Bend Arms Above', 'russian_twist, woodchop, oblique_crunch', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3693ac3e-78aa-4061-9de6-d9d1ae42cfe9', 'Forward Shoulder Rotation Arm Crossover', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'This dynamic rotation movement gets your heart rate up while developing explosive strength. You''ll also feel your front delts working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '78151201', '78151201-Forward-Shoulder-Rotation-Arm-Crossover-(female)_P.mp4', 'female', FALSE, '2025-12-03 23:26:33.640031+00', '1. Rotate your torso through the movement pattern for Forward Shoulder Rotation Arm Crossover. 2. Control the rotation in both directions—avoid using momentum. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'chest_fly', 'Forward Shoulder Rotation Arm Crossover', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('36947c0c-159f-4f76-80ef-09493dc76740', 'Seated Bent Arm Lateral Raise To Triceps (Dumbbell)', 'Arms', 'Dumbbells, Flat Bench', '{"Triceps"}'::text[], '{"Traps"}'::text[], 'Target your lateral delts with the Dumbbell Seated Bent Arm Lateral Raise To Triceps, an effective shoulder raising exercise. Being seated provides stability, allowing you to focus on the working muscles. Using dumbbells requires more stabilization than barbell variations. Strong shoulders improve overhead strength and support nearly all upper body movements.', '105101201', '105101201-Dumbbell-Seated-Bent-Arm-Lateral-Raise-to-Triceps.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Seated Bent Arm Lateral Raise To Triceps. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Raise your arms out to the sides until parallel to the floor. 4. Lower with control, maintaining tension throughout. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 84, 5, 7, FALSE, TRUE, 'lateral_raise', 'Seated Bent Arm Lateral Raise To Triceps', 'shoulder_press, front_raise, rear_delt', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('3697dec9-1aef-4ab8-801c-32d6553a2cc0', 'Decline Chest Fly - Single Arm (Dumbbell)', 'Chest', 'Dumbbells, Decline Bench', '{"Chest"}'::text[], '{"Front Delts","Lower Chest"}'::text[], 'The Dumbbell Decline One Arm Fly is a flying exercise that targets your chest muscles. You''ll also feel your front delts working to support the movement. Declining shifts the emphasis to hit the muscles from a different angle. The dumbbell variation provides freedom of movement and greater range of motion. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '12761201', '12761201-Dumbbell-Decline-One-Arm-Fly_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:26.271124+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions. Keep the movement smooth and controlled.', 'Fly', NULL, NULL, 'Unilateral', NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'chest_fly', 'Decline Single Arm Fly', 'bench_press, incline_press, push_up', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('369af606-8a69-4213-b7c6-2204e78b0191', 'Seated Row - Single Arm - Neutral Grip (Plate Loaded Machine)', 'Back', 'Machine', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Lever Single Arm Neutral Grip Seated Row (plate Lo is a rowing exercise that builds thickness in your upper back. Your biceps, lats work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. The fixed path allows you to focus purely on muscular effort. Back development is crucial for pulling strength and overall upper body function.', '5711201', '05711201-Lever-Single-Arm-Neutral-Grip-Seated-Row-(plate-lo.mp4', 'male', FALSE, '2025-12-03 23:26:23.056255+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Single Arm Neutral Grip Seated Row (plate Lo. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Use a neutral grip with palms facing each other. 4. Pull the weight toward your torso, leading with your elbow(s). 5. Squeeze your shoulder blades together at the peak contraction. 6. Extend back out with control, feeling the stretch in your back. 7. Complete all reps on one side, then switch to the other side. 8. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, 'Seated', NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 85, 7, 9, TRUE, FALSE, 'cable_row', 'Lever Single Arm Neutral Grip Seated Row (plate Lo', 'Lever Single Arm Seated Row (plate Lo - Neutral Grip', FALSE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('369da75b-5340-4603-9ff7-74be142b6e95', 'Side Lying 90 Degrees Hip Clam', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Side Lying 90 Degrees Hip Clam is a lower body movement exercise that targets your glute med/abductors. The lying position provides back support and helps isolate the target muscles. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '63121201', '63121201-Side-Lying-90-Degrees-Hip-Clam-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:37.179953+00', '1. Lie on your side with your body aligned. 2. Set up in the starting position for Side Lying 90 Degrees Hip Clam. 3. Execute the movement with proper form, focusing on your glute med/abductors. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_abduction', 'Side Lying 90 Degrees Hip Clam', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('36ab0586-a733-4ee9-868b-88b272bb689f', 'Ring Self Assisted Pull Up (Gymnastic Rings)', 'Back', 'Gymnastic Rings', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'The Ring Self Assisted Pull Up is a pulling exercise that targets your latissimus dorsi for a wider back. Secondary activation of your biceps, upper back provides additional muscle engagement. Back development is crucial for pulling strength and overall upper body function.', '64991201', '64991201-Ring-Self-Assisted-Pull-Up-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Pull yourself up by driving your elbows down and back. 2. Continue until your chin clears the bar, then lower with control to a full hang. 3. Repeat for the prescribed number of repetitions. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'pull_up', 'Ring Self Assisted Pull Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'gymnastic_rings', FALSE, 3, 90, 4, 68, 85, 85, 70),
('36da828d-df16-48dd-b3ea-f4a5cbe94109', 'Standing Back Squeeze Pulse', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Build a stronger back with this movement movement targeting your full body. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Back development is crucial for pulling strength and overall upper body function.', '72231201', '72231201-Standing-Back-Squeeze-Pulse-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Begin in a standing position with good posture. 2. At the bottom or top, pulse up and down in small movements before completing the rep. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'pulse', 'Standing Back Squeeze Pulse', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('36e0eec8-e70b-44e2-8ac2-77859c7d3927', 'Standing Balance Hip Flexion', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Build leg strength with this flexion movement focusing on your full body. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts.', '57461201', '57461201-Standing-Balance-Hip-Flexion-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Stand tall with your feet firmly planted. 2. Set up in the starting position for Standing Balance Hip Flexion. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'balance', 'Standing Balance Hip Flexion', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('36e5d381-7407-4868-81ba-9a6af97bca3c', 'Inverted Row Bent Knees', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. Secondary activation of your biceps provides additional muscle engagement. No equipment needed—your body provides all the resistance. A strong back improves posture, prevents injury, and balances pressing movements.', '23001201', '23001201-Inverted-Row-Bent-Knees_Back.mp4', 'male', FALSE, '2025-12-03 23:26:26.808474+00', '1. Pull the weight toward your torso, leading with your elbow(s). 2. Squeeze your shoulder blades together at the peak contraction. 3. Extend back out with control, feeling the stretch in your back. 4. Continue for your target rep count, maintaining good form throughout. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'general_exercise', 'Inverted Row Bent Knees', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('36e84623-a57a-406a-ad88-fb331ef63a80', 'L Sit Pull Up (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'The L Sit Pull Up is a pulling exercise that targets your latissimus dorsi for a wider back. The biceps, upper back assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Back development is crucial for pulling strength and overall upper body function.', '69421201', '69421201-L-Sit-Pull-up-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:25.233728+00', '1. Pull yourself up by driving your elbows down and back. 2. Continue until your chin clears the bar, then lower with control to a full hang. 3. Repeat for the prescribed number of repetitions. Ensure full range of motion on each rep. An effective movement for your back routine.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'L Sit Pull Up', 'lat_pulldown, bent_over_row, bicep_curl', FALSE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('36e8c849-32a7-499d-9461-461db9818adb', 'Walking Backward (Treadmill)', 'Legs', 'Treadmill', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build your aerobic capacity with this steady-state cardio movement. Cardiovascular exercise improves heart health, endurance, and helps manage weight. Perfect for including in both strength and hypertrophy programs.', '96081201', '96081201-Walking-Backward-on-a-Treadmill-(male)_Cardio_.mp4', 'male', FALSE, '2025-12-03 23:26:21.732034+00', '1. Set up in the starting position for Walking Backward On A Treadmill. 2. Execute the movement with proper form, focusing on your cardio. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'treadmill', 'Walking Backward On A Treadmill', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('36f0f58b-7262-4527-8767-5c4240238994', 'Sumo Squat Off Benches (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Inner Thighs","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. You''ll also feel your glutes, hamstrings working to support the movement. The dumbbell variation provides freedom of movement and greater range of motion. Strong legs are the foundation for athletic performance and functional fitness.', '58271201', '58271201-Dumbbell-Sumo-Squat-Off-Benches-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:21.890719+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Sumo Squat Off Benches. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'squat', 'Sumo Squat Off Benches', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', TRUE, 'dumbbell', FALSE, 4, 120, 5, 92, 90, 92, 90),
('36f6b2f4-0db0-4cdb-8a60-049345b00899', 'Rolling Plank', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'This stabilization exercise engages your abs for improved core stability and strength. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention. Aim for full range of motion on every rep. Consistency with this movement will yield noticeable results.', '71241201', '71241201-Rolling-Plank-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:36.581585+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Complete all reps with control before resting. Focus on maintaining proper breathing throughout. Perfect for targeting your abs.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Rolling Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('36f96cbd-44a2-4f95-b69b-6c4f6ea1b444', 'Spine Backbend Stretch', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Obliques"}'::text[], 'Target your back with this stretching stretch that helps restore range of motion. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '35171201', '35171201-Spine-Backbend-Stretch_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:23.586683+00', '1. Move into the stretch position for Spine Backbend Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Spine Backbend Stretch', 'running, elliptical, rowing_cardio', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('36ff70e3-4534-4236-823f-44a2ed5157f9', 'Seated External Rotation (Chair)', 'Shoulders', 'Chair', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'The Seated External Rotation On A Chair is a rotation exercise that develops back strength and muscle. The seated position helps isolate the target muscles by removing momentum. A strong back improves posture, prevents injury, and balances pressing movements.', '86171201', '86171201-Seated-External-Rotation-on-a-Chair-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:27.805708+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Rotate your torso through the movement pattern for Seated External Rotation On A Chair. 4. Control the rotation in both directions—avoid using momentum. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 37, 7, 8, TRUE, TRUE, 'external_rotation', 'Seated External Rotation On A Chair', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3702ac55-40db-4761-980b-0f3c396ecc5b', 'Cradle', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This stretch specifically works on your full body, promoting flexibility and reducing muscle tightness. Flexibility work like this enhances performance and prevents stiffness. Excellent for pre-exhausting the target muscle before compound lifts.', '103761201', '103761201-Cradle-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:28.52454+00', '1. Move into the stretch position for Cradle. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Cradle', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('370852ee-28a9-440b-8bf5-e1ae0ad8c15c', 'Yoga Squat Dives', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Yoga Squat Dives is a flexibility exercise that targets your quads, helping to release tension and improve range of motion. You''ll also feel your glutes, hamstrings working to support the movement. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '84141201', '84141201-Yoga-Squat-Dives-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:40.146812+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. Focus on squeezing the target muscle at peak contraction. Perfect for targeting your quads.', 'Squat', NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'squat', 'Yoga Squat Dives', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('371c7ca7-c01b-40b7-98db-ff78e4e67bab', 'Glute Bridge (Resistance Band)', 'Legs', 'Resistance Band', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Develop your posterior chain with this bridging movement that emphasizes the glutes. The hamstrings assist throughout the movement, making this a well-rounded exercise. Resistance bands provide accommodating resistance that increases through the range of motion. Lower body strength improves everything from walking to heavy compound lifts.', '91471201', '91471201-Resistance-Band-Glute-Bridge-(VERSION-2)-(female)_.mp4', 'female', FALSE, '2025-12-03 23:26:35.936279+00', '1. Secure the resistance band appropriately for Resistance Band Glute Bridge. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'glute_bridge', 'Glute Bridge', 'hip_thrust, romanian_deadlift', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('372c8d7d-2e2d-4eca-a257-51ff5b4d530b', 'Fly (Stability Ball, Dumbbell)', 'Chest', 'Dumbbells, Stability Ball, Flat Bench', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'This flying exercise focuses on your pectorals for improved chest strength and development. You''ll also feel your front delts working to support the movement. Dumbbells allow each arm to work independently, helping correct imbalances. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '12771201', '12771201-Dumbbell-Fly-on-Exercise-Ball_Chest.mp4', 'male', FALSE, '2025-12-03 23:26:22.938497+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Fly On Exercise Ball. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 74, 5, 7, FALSE, TRUE, 'general_exercise', 'Fly On Exercise Ball', 'bench_press, incline_bench_press, push_up', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('373334e7-d1df-4554-b64f-82cb9dfaed1f', 'Bent Over Knee Rotation', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Bent Over Knee Rotation provides a deep stretch for your full body, ideal for recovery and mobility work. The bent over position requires core engagement to maintain a neutral spine. Flexibility work like this enhances performance and prevents stiffness.', '105271201', '105271201-Bent-over-Knee-Rotation-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:24.941834+00', '1. Hinge at your hips, pushing them back while keeping your back flat. 2. Rotate your torso through the movement pattern for Bent Over Knee Rotation. 3. Control the rotation in both directions—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Bent Over Knee Rotation', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('373451c2-ba83-4d1f-9d32-5e7867079e8b', 'Seated Piriformis Stretch (Chair)', 'Legs', 'Chair', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Designed to lengthen your glutes, the Seated Piriformis Stretch On A Chair helps improve mobility and prevent stiffness. The hips assist throughout the movement, making this a well-rounded exercise. Being seated provides stability, allowing you to focus on the working muscles. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '84321201', '84321201-Seated-Piriformis-Stretch-on-a-Chair-(male)_Stretc.mp4', 'male', FALSE, '2025-12-03 23:26:28.52454+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Move into the stretch position for Seated Piriformis Stretch On A Chair. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 27, 2, 6, FALSE, TRUE, 'glute_stretch', 'Seated Piriformis Stretch On A Chair', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('37349a9a-578d-4c40-90a9-ad06872e214b', 'Single Arm Reverse Fly - Rack Support (Dumbbell)', 'Shoulders', 'Dumbbells, Flat Bench', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'The Dumbbell Single Arm Reverse Fly (rack Support) targets your rear deltoids with a flying motion. Your upper back work as secondary movers, adding to the training stimulus. Dumbbells allow each arm to work independently, helping correct imbalances. Back development is crucial for pulling strength and overall upper body function.', '88171201', '88171201-Dumbbell-Single-Arm-Reverse-Fly-(rack-support)_Bac.mp4', 'male', FALSE, '2025-12-03 23:26:28.52454+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 69, 5, 7, FALSE, TRUE, 'rear_delt', 'Single Arm Reverse Fly', 'bench_press, incline_bench_press, push_up', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('373ad4db-2efb-4728-a332-a81dd46c5cf2', 'Stand To Stand Bridge', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Hamstrings"}'::text[], 'Target your full body with this bridging stretch that helps restore range of motion. Your hamstrings work as secondary movers, adding to the training stimulus. Include this in your routine for better mobility and reduced muscle tension.', '96491201', '96491201-Stand-to-Stand-Bridge-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:22.938497+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'glute_bridge', 'Stand To Stand Bridge', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('374f5378-d382-4904-8364-a5f7ae5d330a', 'Standing Forward Bend Back Squeeze', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Standing Forward Bend Back Squeeze is a movement exercise that develops back strength and muscle. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. Back development is crucial for pulling strength and overall upper body function.', '72211201', '72211201-Standing-Forward-Bend-Back-Squeeze-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Begin in a standing position with good posture. 2. Set up in the starting position for Standing Forward Bend Back Squeeze. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Stretch', 52, 7, 8, TRUE, TRUE, 'back_exercise', 'Standing Forward Bend Back Squeeze', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3776ec60-01d8-4880-b5bd-b75eafab36f1', 'Bench Press - Close Grip (Dumbbell)', 'Arms', 'Dumbbells', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'The Dumbbell Close Grip Press targets your triceps through a pressing motion. Your chest work as secondary movers, adding to the training stimulus. Using dumbbells requires more stabilization than barbell variations. Arm strength supports grip, pulling, and pushing in compound movements.', '26451201', '26451201-Dumbbell-Close-Grip-Press-(female)_Upper-Arms.mp4', 'female', FALSE, '2025-12-03 23:26:32.735372+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Close Grip Press. 2. Use a close/narrow grip (hands closer than shoulder-width). 3. Execute the pressing motion for Dumbbell Close Grip Press, extending through the target muscles. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'general_exercise', 'Press - Close Grip', 'Press - Close Grip', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('37857206-a793-462c-b3df-f0af7f4e0672', 'Leg Over Knee Glute Bridge', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Build stronger glutes with this bridging movement focused on hip extension. The hamstrings assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '46901201', '46901201-Leg-Over-Knee-Glute-Bridge-(male)_Hips.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Repeat for the prescribed number of repetitions. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'glute_bridge', 'Leg Over Knee Glute Bridge', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('37983ebc-fa7f-4574-a55a-448094a6ce11', 'Sumo Squat Jack', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Inner Thighs","Hamstrings"}'::text[], 'This dynamic squatting movement gets your heart rate up while developing explosive strength. Secondary activation of your glutes, hamstrings provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '104081201', '104081201-Sumo-Squat-Jack-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Start with lighter weight to perfect your form. Ideal for quads strength and endurance. Variation: Sumo Squat Jack.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 85, 9, 8, TRUE, TRUE, 'squat', 'Sumo Squat Jack', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('37a91419-cdb5-4586-b9c0-9fd7f5f8e785', 'Roll And Side Twist (stabilitity Ball)', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Elevate your training with this twisting exercise that develops speed, power, and coordination. Secondary activation of your abs provides additional muscle engagement. Using a ball requires constant core engagement to maintain balance. Plyometric training builds explosive power that transfers to sports and daily activities.', '93291201', '93291201-Roll-and-Side-Twist-on-Stabilitity-Ball-(female)_P.mp4', 'female', FALSE, '2025-12-03 23:26:36.38616+00', '1. Rotate your torso through the movement pattern for Roll And Side Twist. 2. Control the rotation in both directions—avoid using momentum. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'russian_twist', 'Roll And Side Twist', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('37cfbbdc-da51-4197-bc5f-1fd506d3da14', 'Seated Curl (Dumbbell)', 'Arms', 'Dumbbells, Flat Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Dumbbell Seated Curl is a curling exercise that isolates your biceps. You''ll also feel your forearms working to support the movement. Being seated provides stability, allowing you to focus on the working muscles. Using dumbbells requires more stabilization than barbell variations. Arm strength supports grip, pulling, and pushing in compound movements.', '74011201', '74011201-Dumbbell-Seated-Curl-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:33.034396+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Seated Curl. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Repeat for the prescribed number of repetitions. Maintain consistent tempo throughout the set.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 84, 5, 7, FALSE, TRUE, 'leg_curl', 'Seated Curl', 'romanian_deadlift, hip_thrust', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('37cfd90d-672d-4723-a69b-e5a30bc29990', 'Roll Calves', 'Legs', 'Bodyweight', '{"Calves"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This movement movement focuses on your gastrocnemius and soleus. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '54381201', '54381201-Roll-Calves-(female)_Calves_.mp4', 'female', FALSE, '2025-12-03 23:26:36.38616+00', '1. Set up in the starting position for Roll Calves. 2. Execute the movement with proper form, focusing on your calves. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Roll Calves', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('37d9dfbb-8c99-44a2-bc21-2613fde25aca', 'Decline Bench Press - Reverse Grip (Barbell)', 'Chest', 'Barbell, Decline Bench', '{"Chest","Lower Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'Target your chest with the Barbell Reverse Grip Decline Bench Press, an effective pressing movement for upper body strength. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. The decline position targets the lower portion of the muscles more intensely. Using a barbell provides stability for progressive overload. A well-developed chest contributes to upper body strength and aesthetics.', '12561201', '12561201-Barbell-Reverse-Grip-Decline-Bench-Press_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:21.608253+00', '1. Load a barbell and set it on a bench rack at the appropriate height. 2. Use a reverse grip (opposite of the standard grip for this exercise). 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Complete all reps with control before resting. Start with lighter weight to perfect your form.', 'Press', 'Push', 'Compound', 'Bilateral', NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 100, 7, 9, TRUE, FALSE, 'decline_press', 'Decline Bench Press - Reverse Grip', 'Decline Bench Press - Reverse Grip', TRUE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('37e7ad38-1a3f-45fa-b889-6417f1bbc9c9', 'Standing Ab Twist Wall Touch (Wall)', 'Core', 'Wall', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Work your side abdominals with this twisting exercise that strengthens your obliques. The abs assist throughout the movement, making this a well-rounded exercise. The standing position engages your core for stability. Building core stability helps with everything from heavy deadlifts to daily activities.', '88851201', '88851201-Standing-Ab-Twist-Wall-Touch-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Position yourself at the appropriate distance from a wall. 2. Stand with feet about shoulder-width apart. 3. Rotate your torso through the movement pattern for Standing Ab Twist Wall Touch. 4. Control the rotation in both directions—avoid using momentum. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 44, 5, 7, FALSE, TRUE, 'russian_twist', 'Standing Ab Twist Wall Touch', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('37e9eb00-3a5e-4106-aa43-7ec1e61247ea', 'Seated Lean Back Cycling (Chair)', 'Core', 'Stationary Bike, Chair', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Seated Lean Back Cycling On A Chair is a core movement exercise that primarily targets your abs. The seated position helps isolate the target muscles by removing momentum. Core strength is foundational for athletic performance and injury prevention.', '83091201', '83091201-Seated-Lean-Back-Cycling-on-a-Chair-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Repeat for the prescribed number of repetitions. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 37, 9, 8, FALSE, TRUE, 'cycling', 'Seated Lean Back Cycling On A Chair', 'running, elliptical, rowing_cardio', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('37f92470-ca62-45d3-8e9d-0b92fdb3bb29', 'Hammer Curl (Dumbbell)', 'Arms', 'Dumbbells', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Dumbbell Hammer Curl is a curling exercise that isolates your biceps. The forearms assist throughout the movement, making this a well-rounded exercise. The dumbbell variation provides freedom of movement and greater range of motion. Arm strength supports grip, pulling, and pushing in compound movements. Quality repetitions are more important than quantity.', '24851201', '24851201-Dumbbell-Hammer-Curl-(female)_Upper-Arms.mp4', 'female', FALSE, '2025-12-03 23:26:32.735372+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Hammer Curl. 2. Use a hammer/neutral grip with palms facing each other throughout. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'hammer_curl', 'Hammer Curl', 'bicep_curl, preacher_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('380af61c-1b03-4694-8419-add61edceec7', 'Elevated Staggered Leg Hip Thrust (Step Platform)', 'Legs', 'Step Platform', '{"Glutes"}'::text[], '{"Hamstrings","Core"}'::text[], 'The Elevated Staggered Leg Hip Thrust is a hip-dominant thrusting exercise that targets your glutes. You''ll also feel your hamstrings working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '76811201', '76811201-Elevated-Staggered-Leg-Hip-Thrust-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Repeat for the prescribed number of repetitions. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'hip_thrust', 'Elevated Staggered Leg Hip Thrust', 'glute_bridge, romanian_deadlift, leg_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3818f6aa-a425-42e3-934c-83b66d8f93f3', 'Seated Pec Dec (Chair)', 'Chest', 'Chair', '{"Chest"}'::text[], '{}'::text[], 'This movement exercise focuses on your pectorals for improved chest strength and development. Being seated provides stability, allowing you to focus on the working muscles. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '86211201', '86211201-Seated-Pec-Dec-on-a-Chair-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:27.67144+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Complete all reps with control before resting. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 37, 7, 8, TRUE, TRUE, 'chest_exercise', 'Seated Pec Dec On A Chair', 'bench_press, chest_fly, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3821c244-c330-43f5-b68e-07917a686d67', 'Standing Eagle Up And Left', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{}'::text[], 'Build a stronger chest with this movement movement that develops pressing power. Performing this standing challenges your balance and core engagement. No equipment needed—your body provides all the resistance. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '94201201', '94201201-Standing-Eagle-Up-and-Left-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Standing Eagle Up And Left. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'general_exercise', 'Standing Eagle Up And Left', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('38291caf-3c88-452e-9433-dad4824c7a38', 'Palms Above Head Elbow Squeeze', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{}'::text[], 'This movement exercise focuses on your pectorals for improved chest strength and development. This bodyweight exercise requires no equipment and can be done anywhere. A well-developed chest contributes to upper body strength and aesthetics. A staple exercise that belongs in most training programs.', '59941201', '59941201-Palms-Above-Head-Elbow-Squeeze-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:35.667316+00', '1. Set up in the starting position for Palms Above Head Elbow Squeeze. 2. Execute the movement with proper form, focusing on your chest. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Palms Above Head Elbow Squeeze', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('382f34d0-5692-492e-8dc4-4430c117ba60', 'Seated Preacher Curl (Dumbbell)', 'Arms', 'Dumbbells, Preacher Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. The forearms assist throughout the movement, making this a well-rounded exercise. Being seated provides stability, allowing you to focus on the working muscles. Dumbbells allow each arm to work independently, helping correct imbalances. Dedicated arm training builds both strength and muscular definition.', '4021201', '04021201-Dumbbell-Seated-Preacher-Curl_Upper-Arms-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:22.755209+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Seated Preacher Curl. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 94, 5, 7, FALSE, TRUE, 'preacher_curl', 'Seated Preacher Curl', 'tricep_pushdown, tricep_extension, bicep_curl, hammer_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('38367381-4c76-4217-9503-a478d293c125', 'Glute Bridge Hold With Kick', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'The Glute Bridge Hold With Kick is a hip-dominant kicking exercise that targets your glutes. Secondary activation of your hamstrings provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '63851201', '63851201-Glute-Bridge-Hold-with-Kick-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:33.778367+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Hold the position for the prescribed time, maintaining tension. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 65, 7, 8, TRUE, TRUE, 'glute_bridge', 'Glute Bridge Hold With Kick', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('3850ba17-e3ca-470e-9475-290f3c21290f', 'Ipsilateral Single Leg Stiff Leg Deadlift (Dumbbell)', 'Legs', 'Dumbbells', '{"Hamstrings"}'::text[], '{"Glutes","Lower Back"}'::text[], 'This hip hinge movement works your hamstrings for balanced leg development. You''ll also feel your glutes, lower back working to support the movement. Dumbbells allow each arm to work independently, helping correct imbalances. Leg training boosts metabolism and builds functional, real-world strength.', '76481201', '76481201-Dumbbell-Ipsilateral-Single-Leg-Stiff-Leg-Deadlift.mp4', 'female', FALSE, '2025-12-03 23:26:32.914483+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Push your hips back, lowering the weight along your legs with a flat back. 3. Lower until you feel a stretch in your hamstrings. 4. Drive hips forward to stand, squeezing glutes at the top. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 82, 7, 9, TRUE, FALSE, 'romanian_deadlift', 'Ipsilateral Single Leg Stiff Leg Deadlift', 'deadlift, leg_curl, hip_thrust', FALSE, 'dumbbell', FALSE, 4, 120, 6, 92, 90, 92, 90),
('386f13eb-34e8-42e2-9cfe-c67338a4bdf5', 'Around The World Superman Hold', 'Back', 'Bodyweight', '{"Lower Back"}'::text[], '{"Glutes","Upper Back"}'::text[], 'The Around The World Superman Hold is a lower body movement exercise that targets your delts. Your chest work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '70291201', '70291201-Around-the-World-Superman-Hold-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:30.54809+00', '1. Hold the position for the prescribed time, maintaining tension. 2. Set up in the starting position for Around The World Superman Hold. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'around_world', 'Around The World Superman Hold', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('387036fa-8177-41c9-a072-90d6e2e8bfd6', 'Standing Arnold Press', 'Shoulders', 'Bodyweight', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'The Bodyweight Standing Arnold Press is a pressing exercise that targets your delts for shoulder development. Secondary activation of your triceps provides additional muscle engagement. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. Strong shoulders improve overhead strength and support nearly all upper body movements.', '86001201', '86001201-Bodyweight-Standing-Arnold-Press-(female)_Shoulder.mp4', 'female', FALSE, '2025-12-03 23:26:31.475486+00', '1. Begin in a standing position with good posture. 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 72, 7, 8, TRUE, TRUE, 'shoulder_press', 'Standing Arnold Press', 'lateral_raise, front_raise, rear_delt', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3875fa75-6bc9-4f41-8ce4-a972330db3e9', 'Standing Arms Forward Arm Crossover', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. Your front delts work as secondary movers, adding to the training stimulus. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '87481201', '87481201-Standing-Arms-Forward-Arm-Crossover-(female)_Plyom.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Begin in a standing position with good posture. 2. Set up in the starting position for Standing Arms Forward Arm Crossover. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'chest_fly', 'Standing Arms Forward Arm Crossover', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('38818c4b-14df-4179-9b1d-1aba018f357b', 'Incline Triceps Extension (Kettlebell)', 'Arms', 'Kettlebell, Incline Bench', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'The Kettlebell Incline Triceps Extension targets your triceps through a extension motion. Using an incline changes the angle of resistance for varied muscle recruitment. The kettlebell''s offset center of mass increases the stability challenge. Arm strength supports grip, pulling, and pushing in compound movements.', '68261201', '68261201-Kettlebell-Incline-Triceps-Extension_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Select an appropriately weighted kettlebell for Kettlebell Incline Triceps Extension. 2. Extend at the elbow until your arm is straight, squeezing the tricep. 3. Lower with control, keeping your upper arm stationary. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 91, 5, 7, FALSE, TRUE, 'tricep_extension', 'Incline Triceps Extension', 'tricep_pushdown, close_grip_bench', FALSE, 'kettlebell', FALSE, 3, 60, 2, 75, 88, 88, 78),
('3885117e-9acb-4a31-9961-d308f817925f', 'Leg Extension - Single Leg', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{}'::text[], 'The Lying Single Leg Extension is a extension exercise that primarily loads your quadriceps. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '96631201', '96631201-Lying-Single-Leg-Extension-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Lie down in the appropriate position for Lying Single Leg Extension. 2. Extend your legs until straight, squeezing your quads at the top. 3. Lower with control back to the starting position. 4. Complete all reps on one side, then switch to the other side. 5. Repeat for the prescribed number of repetitions. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 75, 5, 7, FALSE, TRUE, 'leg_extension', 'Lying Single Leg Extension', 'squat, leg_press, lunge', TRUE, 'bodyweight', FALSE, 3, 60, 2, 80, 75, 20, 88),
('388bca5c-a22d-4df6-8072-d8704b8627e8', 'Calf Side To Side Jump', 'Legs', 'Bodyweight', '{"Calves"}'::text[], '{"Glutes"}'::text[], 'Build power and athleticism with this high-intensity jumping exercise that challenges your entire body. The quads, calves assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '107571201', '107571201-Calf-Side-to-Side-Jump-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:32.166461+00', '1. Set up in the starting position for Calf Side To Side Jump. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'general_exercise', 'Calf Side To Side Jump', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('3895be36-2c34-45d0-9385-56c17fe9a313', 'Wheel Rollout (Ab Wheel)', 'Core', 'Ab Wheel', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. Secondary activation of your lats, shoulders provides additional muscle engagement. Building core stability helps with everything from heavy deadlifts to daily activities.', '23321201', '23321201-Wheel-Rollout-(female)_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:40.037451+00', '1. Set up in the starting position for Wheel Rollout. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'ab_rollout', 'Wheel Rollout', 'plank, crunch, dead_bug', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65);
INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('38a1b5e4-7d53-4420-8dbb-e54330c96671', 'Burpee Tuck Jump', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Burpee Tuck Jump is an explosive exercise that combines cardiovascular training with dynamic jumping movements. Secondary activation of your chest, quads provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '68611201', '68611201-Burpee-Tuck-Jump-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:24.831811+00', '1. Squat down and place hands on the floor, jump feet back to plank. 2. Jump feet back toward hands, then explosively jump up with arms overhead. 3. Land softly and immediately begin the next rep. 4. Complete all reps with control before resting. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'tuck_jump', 'Burpee Tuck Jump', 'mountain_climber, box_jump, jumping_jack', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('38ad4506-5305-4975-a7b8-5b4cdd3fb050', 'Standing Bicep Curl (Plate)', 'Arms', 'Weight Plate', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. Your forearms work as secondary movers, adding to the training stimulus. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. Dedicated arm training builds both strength and muscular definition.', '105781201', '105781201-Weighted-Plate-Standing-Biceps-Curl-(female)_Fore.mp4', 'female', FALSE, '2025-12-03 23:26:40.037451+00', '1. Stand tall with your feet firmly planted. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps with control before resting. Keep the movement smooth and controlled.', 'Curl', 'Pull', NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'bicep_curl', 'Weighted Plate Standing Biceps Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'plate', FALSE, 3, 60, 2, 70, 88, 95, 65),
('38c9d9dc-1a9b-4001-8e8b-93bb71d50900', 'Single Leg Hopping', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning. A staple exercise that belongs in most training programs.', '54821201', '54821201-Single-Leg-Hopping_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:29.837118+00', '1. Complete all reps on one side, then switch to the other side. 2. Set up in the starting position for Single Leg Hopping. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 45, 9, 8, TRUE, TRUE, 'hop', 'Single Leg Hopping', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('38d01d35-3220-4794-ba5d-833bbc70aa5f', 'Standing Wood Chopper (Cable)', 'Core', 'Cables', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Cable Standing Wood Chopper targets your obliques through a movement motion, building rotational core strength. You''ll also feel your shoulders working to support the movement. Performing this standing challenges your balance and core engagement. The cable setup allows you to adjust the angle of resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '80231201', '80231201-Cable-Standing-Wood-Chopper-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Adjust the cable machine to the correct height and attachment for Cable Standing Wood Chopper. 2. Stand with feet about shoulder-width apart. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'woodchop', 'Standing Wood Chopper', 'russian_twist, pallof_press, cable_crunch', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('38d96122-6df7-4855-93fa-a3f3b2c8c641', 'Duck Side Punch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Shoulders"}'::text[], 'The Duck Side Punch is an explosive exercise that combines cardiovascular training with dynamic movement movements. Your shoulders work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '67251201', '67251201-Duck-Side-Punch-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:27.263406+00', '1. Set up in the starting position for Duck Side Punch. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Duck Side Punch', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('38fb40e9-2c1f-42a6-a83e-df1db063f3ad', 'Standing Front Raise Above Head (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'Build stronger shoulders with this raising movement focusing on your front delts. Performing this standing challenges your balance and core engagement. Using dumbbells requires more stabilization than barbell variations. Strong shoulders improve overhead strength and support nearly all upper body movements.', '4191201', '04191201-Dumbbell-Standing-Front-Raise-Above-Head_Shoulders.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Standing Front Raise Above Head. 2. Stand with feet about shoulder-width apart. 3. Raise the weight in front of you to shoulder height. 4. Lower with control, maintaining tension throughout. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 84, 5, 7, FALSE, TRUE, 'front_raise', 'Standing Front Raise Above Head', 'shoulder_press, lateral_raise, rear_delt_fly', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('38fc8504-c72e-4980-b1f7-f9fe6204a646', 'Body Throw', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Build power and athleticism with this high-intensity rowing exercise that challenges your entire body. Your biceps, rear delts work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '51171201', '51171201-Body-Throw-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:31.347577+00', '1. Pull the weight toward your torso, leading with your elbow(s). 2. Squeeze your shoulder blades together at the peak contraction. 3. Extend back out with control, feeling the stretch in your back. 4. Repeat for the prescribed number of repetitions. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'general_exercise', 'Body Throw', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3903d4e9-d61a-40c7-9135-cd3b817287c1', 'Svend Bench Press (Flat Bench)', 'Chest', 'Flat Bench', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Svend Bench Press is an arm pressing exercise targeting your chest. You''ll also feel your triceps, front delts working to support the movement. Dedicated arm training builds both strength and muscular definition.', '97511201', '97511201-Svend-Bench-Press-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:39.623429+00', '1. Lower the weight toward your chest with control. 2. Press the weight up until your arms are extended (don''t lock elbows). 3. Complete all reps with control before resting. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'bench_press', 'Svend Bench Press', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('390463be-edfb-440a-a6d9-15fac58a3c37', 'Standing Reverse Curl Rotate (Dumbbell)', 'Arms', 'Dumbbells', '{"Forearms"}'::text[], '{"Biceps"}'::text[], 'The Dumbbell Standing Reverse Curl Rotate strengthens your forearms and grip through a curling motion. Secondary activation of your biceps provides additional muscle engagement. The standing position engages your core for stability. The dumbbell variation provides freedom of movement and greater range of motion. Arm strength supports grip, pulling, and pushing in compound movements.', '70561201', '70561201-Dumbbell-Standing-Reverse-Curl-Rotate-(male)_Forea.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Standing Reverse Curl Rotate. 2. Stand with feet about shoulder-width apart. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 84, 5, 7, FALSE, TRUE, 'general_exercise', 'Standing Reverse Curl Rotate', 'hammer_curl, wrist_curl, bicep_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('39092353-9e99-43f6-90c2-fb016ff398c0', 'Stepjack Inner Biceps Curl', 'Arms', 'Bodyweight', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build power and athleticism with this high-intensity curling exercise that challenges your entire body. The forearms assist throughout the movement, making this a well-rounded exercise. Great for improving athletic performance, burning calories, and building conditioning.', '56451201', '56451201-Stepjack-Inner-Biceps-Curl-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:29.483269+00', '1. Set up a box or step platform at the appropriate height. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Repeat for the prescribed number of repetitions. Maintain consistent tempo throughout the set.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 80, 9, 8, TRUE, TRUE, 'bicep_curl', 'Stepjack Inner Bicep Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('390ce985-b6c1-4268-8e1a-e86316a573ed', 'Standing Shoulders Full Flexion', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'The Standing Shoulders Full Flexion is a flexion exercise that targets your delts for shoulder development. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. Shoulder development enhances both performance and upper body aesthetics.', '53621201', '53621201-Standing-Shoulders-Full-Flexion-(female)_Shoulders.mp4', 'female', FALSE, '2025-12-03 23:26:38.870314+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Standing Shoulders Full Flexion. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Standing Shoulders Full Flexion', 'lateral_raise, shoulder_press, front_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('391e2412-7adc-4d2e-b782-dfc945914f92', 'Standing Hip Frontal Rotation Arm Bounces', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'This full-body rotation exercise challenges multiple muscle groups simultaneously. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. Full body exercises are time-efficient and build functional, real-world strength. This variation is excellent for building mind-muscle connection.', '68581201', '68581201-Standing-Hip-Frontal-Rotation-Arm-Bounces-(female).mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Begin in a standing position with good posture. 2. Rotate your torso through the movement pattern for Standing Hip Frontal Rotation Arm Bounces. 3. Control the rotation in both directions—avoid using momentum. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'glute_exercise', 'Standing Hip Frontal Rotation Arm Bounces', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('391ea3dc-99a6-4154-9971-abc33d841c2f', 'Leg Press (Machine)', 'Legs', 'Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this pressing exercise for quad development. You''ll also feel your glutes working to support the movement. Being seated provides stability, allowing you to focus on the working muscles. The machine guides your movement path for safer, more controlled repetitions. Lower body strength improves everything from walking to heavy compound lifts.', '26081201', '26081201-Lever-Seated-Leg-Press-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Seated Leg Press. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Position your feet on the platform and release the safety. 4. Lower the weight by bending your knees, then press back up powerfully. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, 'Seated', NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 90, 7, 9, TRUE, FALSE, 'leg_press', 'Lever Seated Leg Press', 'squat, hack_squat, lunge', TRUE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('392344a8-0214-4512-99ef-3134b3df8cac', 'Side Plank Butt', 'Core', 'Bodyweight', '{"Core","Abs"}'::text[], '{"Shoulders"}'::text[], 'The Side Plank Butt is a core stabilization exercise that primarily targets your abs. Secondary activation of your shoulders, lower back provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '23491201', '23491201-Side-Plank---Butt-(WRONG-RIGHT)_.mp4', 'female', FALSE, '2025-12-03 23:26:37.179953+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Repeat for the prescribed number of repetitions. Keep your shoulders relaxed and away from your ears. This variation specifically emphasizes the abs.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'side_plank', 'Side Plank Butt', 'plank, russian_twist, woodchop', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('3926ff6a-dd2a-4c75-aa96-6af13d45cd17', 'Single Arm Dip', 'Chest', 'Bodyweight', '{"Lower Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The One Arm Dip targets your triceps through a dipping motion. Secondary activation of your triceps, front delts provides additional muscle engagement. No equipment needed—your body provides all the resistance. Dedicated arm training builds both strength and muscular definition.', '6391201', '06391201-One-Arm-Dip_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:21.109351+00', '1. Lower your body by bending your elbows to about 90 degrees. 2. Push back up until your arms are fully extended. 3. Complete all reps on one side, then switch to the other side. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 65, 7, 8, TRUE, TRUE, 'dip', 'Single Arm Dip', 'bench_press, tricep_pushdown, push_up', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('392d4a1c-3ac8-4498-92b7-c25967ea1c4b', 'Seated Front Raise (Dumbbell) - Alternating', 'Shoulders', 'Dumbbells, Flat Bench', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'Build stronger shoulders with this raising movement focusing on your front delts. Being seated provides stability, allowing you to focus on the working muscles. Using dumbbells requires more stabilization than barbell variations. Strong shoulders improve overhead strength and support nearly all upper body movements.', '3871201', '03871201-Dumbbell-Seated-Alternate-Front-Raise_Shoulders.mp4', 'male', FALSE, '2025-12-03 23:26:25.123298+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Seated Alternate Front Raise. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Raise the weight in front of you to shoulder height. 4. Lower with control, maintaining tension throughout. 5. Alternate between sides/arms/legs with each repetition. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 84, 5, 7, FALSE, TRUE, 'front_raise', 'Seated Front Raise - Alternating', 'shoulder_press, lateral_raise, rear_delt_fly', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('39341a48-1602-47b8-82b7-175c25336b1e', 'Knee To Hand Tap', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning. Start with lighter weight to master the movement pattern.', '45011201', '45011201-Bodyweight-Knee-To-Hand-Tap_Plyometrics.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Set up in the starting position for Bodyweight Knee To Hand Tap. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_raise', 'Knee To Hand Tap', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('39372617-d627-4926-8532-0db251e426d5', 'Preacher Curl (Cable)', 'Arms', 'Cables', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. Secondary activation of your forearms provides additional muscle engagement. Cables provide constant tension throughout the full range of motion. Arm strength supports grip, pulling, and pushing in compound movements. Focus on controlled form throughout each repetition.', '1951201', '01951201-Cable-Preacher-Curl_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:28.71819+00', '1. Adjust the cable machine to the correct height and attachment for Cable Preacher Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 90, 5, 7, FALSE, TRUE, 'preacher_curl', 'Preacher Curl', 'tricep_pushdown, tricep_extension, bicep_curl, hammer_curl', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('394aa1e6-7b59-47d7-af97-c1b72bfa6b0f', 'Around Head Rotation', 'Shoulders', 'Bodyweight', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'The Bodyweight Around Head Rotation is a rotation exercise that targets your delts for shoulder development. This bodyweight exercise requires no equipment and can be done anywhere. Strong shoulders improve overhead strength and support nearly all upper body movements.', '94161201', '94161201-Bodyweight-Around-Head-Rotation-(female)_Shoulders.mp4', 'female', FALSE, '2025-12-03 23:26:31.347577+00', '1. Rotate your torso through the movement pattern for Bodyweight Around Head Rotation. 2. Control the rotation in both directions—avoid using momentum. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'neck_stretch', 'Around Head Rotation', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('396b8e72-9b79-4b13-b4e9-aa434f0dda2b', 'Cross Over Lateral Pulldown (Cable)', 'Back', 'Cables', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'A challenging plyometric exercise, the Cable Cross Over Lateral Pulldown builds reactive power and improves conditioning. The shoulders, core assist throughout the movement, making this a well-rounded exercise. Cable resistance creates smooth, continuous muscle engagement. Great for improving athletic performance, burning calories, and building conditioning.', '1531201', '01531201-Cable-Cross-over-Lateral-Pulldown_Back.mp4', 'male', FALSE, '2025-12-03 23:26:20.392006+00', '1. Adjust the cable machine to the correct height and attachment for Cable Cross Over Lateral Pulldown. 2. Pull the bar/handle down toward your upper chest. 3. Drive your elbows down and back, squeezing your lats. 4. Control the weight back up without letting it yank your arms. 5. Continue for your target rep count, maintaining good form throughout. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Cross Over Lateral Pulldown', 'pull_up, bent_over_row, cable_row, face_pull', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('39787fc0-36f3-4909-ba0d-a09023b64841', 'Lying Floor Skullcrusher (Dumbbell)', 'Arms', 'Dumbbells', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This movement movement isolates your triceps for improved arm development. The lying position provides back support and helps isolate the target muscles. Dumbbells allow each arm to work independently, helping correct imbalances. Arm strength supports grip, pulling, and pushing in compound movements.', '41511201', '41511201-Dumbbell-Lying-Floor-Skullcrusher_Upper-Arms.mp4', 'male', FALSE, '2025-12-03 23:26:27.384461+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Lying Floor Skullcrusher. 2. Position yourself on the floor for Dumbbell Lying Floor Skullcrusher. 3. Lie down in the appropriate position for Dumbbell Lying Floor Skullcrusher. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 57, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Floor Skullcrusher', 'bicep_curl, tricep_pushdown, tricep_extension, dip', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('397ab3b1-da95-4d6b-8ac2-8005e6336106', 'All Fours Squad Stretch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This stretch specifically works on your quads, promoting flexibility and reducing muscle tightness. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '45131201', '45131201-All-Fours-Squad-Stretch-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Move into the stretch position for All Fours Squad Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'quad_stretch', 'All Fours Squad Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('397cb302-2f61-46f8-b878-ba607fb8846c', 'Lying Bicycle Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hamstrings"}'::text[], 'Build a stronger core with the Lying Bicycle Crunch, focusing on your abs. The abs assist throughout the movement, making this a well-rounded exercise. The lying position provides back support and helps isolate the target muscles. No equipment needed—your body provides all the resistance. Building core stability helps with everything from heavy deadlifts to daily activities.', '71621201', '71621201-Lying-Bicycle-Crunch-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.133808+00', '1. Lie down in the appropriate position for Lying Bicycle Crunch. 2. Bring one knee toward chest while extending the other leg. 3. Rotate to bring opposite elbow toward the bent knee. 4. Alternate sides in a pedaling motion. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'cycling', 'Lying Bicycle Crunch', 'crunch, russian_twist, leg_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('397e37c7-249f-47af-9984-3518545f4801', 'Standing Balance Glute Kickback (Resistance Band)', 'Legs', 'Resistance Band', '{"Glutes","Hamstrings"}'::text[], '{"Rear Delts"}'::text[], 'The Resistance Band Standing Balance Glute Kickback is a hip-dominant kicking exercise that targets your glutes. You''ll also feel your hamstrings working to support the movement. Performing this standing challenges your balance and core engagement. Resistance bands provide accommodating resistance that increases through the range of motion. Strong legs are the foundation for athletic performance and functional fitness.', '72041201', '72041201-Resistance-Band-Standing-Balance-Glute-Kickback-(V.mp4', 'female', FALSE, '2025-12-03 23:26:36.266593+00', '1. Secure the resistance band appropriately for Resistance Band Standing Balance Glute Kickback. 2. Stand with feet about shoulder-width apart. 3. Keep your upper arm stationary and extend your forearm back. 4. Squeeze at full extension, then return with control. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 57, 5, 7, FALSE, TRUE, 'glute_kickback', 'Standing Balance Glute Kickback', 'hip_thrust, glute_bridge, leg_curl', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('3985f706-95e4-4972-aa6e-a624a511e2fd', 'Bent Over Twist Row (Kettlebell) - Alternating', 'Back', 'Kettlebell', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. You''ll also feel your abs working to support the movement. The bent over position requires core engagement to maintain a neutral spine. The kettlebell''s offset center of mass increases the stability challenge. Back development is crucial for pulling strength and overall upper body function.', '58671201', '58671201-Kettlebell-Bent-over-Alternate-Twist-Row_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:22.536005+00', '1. Select an appropriately weighted kettlebell for Kettlebell Bent Over Alternate Twist Row. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Alternate between sides/arms/legs with each repetition. 7. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'russian_twist', 'Bent Over Twist Row - Alternating', 'lat_pulldown, pull_up, bicep_curl, face_pull, seated_row', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('3997cc81-9f88-4b15-9cd0-f048153ad363', 'Leg Press (Machine)', 'Legs', 'Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this pressing movement that develops leg drive and power. Your glutes work as secondary movers, adding to the training stimulus. The fixed path allows you to focus purely on muscular effort. Strong legs are the foundation for athletic performance and functional fitness.', '58381201', '58381201-Lever-Leg-Press-(plate-loaded)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:23.987963+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Leg Press. 2. Position your feet on the platform and release the safety. 3. Lower the weight by bending your knees, then press back up powerfully. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 88, 7, 9, TRUE, FALSE, 'leg_press', 'Lever Leg Press', 'squat, hack_squat, lunge', TRUE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('399d33fe-6d95-4d0c-8308-8f89a26ebf17', 'Cross Arms Triceps Extension', 'Arms', 'Bodyweight', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'Elevate your training with this extension exercise that develops speed, power, and coordination. You''ll also feel your shoulders, core working to support the movement. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '82691201', '82691201-Cross-Arms-Triceps-Extension-(male)_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:29.837118+00', '1. Extend at the elbow until your arm is straight, squeezing the tricep. 2. Lower with control, keeping your upper arm stationary. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'tricep_extension', 'Cross Arms Triceps Extension', 'tricep_pushdown, close_grip_bench', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('39a6fc7f-32bf-4488-8bac-6719047e4f2a', 'Elevated Row (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Cable Elevated Row is a rowing exercise that builds thickness in your upper back. Secondary activation of your biceps, rear delts provides additional muscle engagement. Cable resistance creates smooth, continuous muscle engagement. Back development is crucial for pulling strength and overall upper body function.', '10461201', '10461201-Cable-Elevated-Row_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Adjust the cable machine to the correct height and attachment for Cable Elevated Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 80, 7, 8, TRUE, TRUE, 'general_exercise', 'Elevated Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('39abb604-5071-401b-90bd-8d1b811af2cb', 'Horizontal Pallof Press (Resistance Band)', 'Core', 'Resistance Band, Anchor Point', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This pressing exercise engages your core for improved core stability and strength. Secondary activation of your obliques provides additional muscle engagement. Resistance bands provide accommodating resistance that increases through the range of motion. Building core stability helps with everything from heavy deadlifts to daily activities.', '80441201', '80441201-Resistance-Band-Horizontal-Pallof-Press-(female)_W.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band Horizontal Pallof Press. 2. Execute the pressing motion for Resistance Band Horizontal Pallof Press, extending through the target muscles. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'pallof_press', 'Horizontal Pallof Press', 'woodchop, plank, dead_bug', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('39b5bbe4-1ea5-4b26-b7b8-19fbf10cc383', 'Romanian Deadlift (Plate Loaded Machine)', 'Legs', 'Machine', '{"Hamstrings"}'::text[], '{"Glutes","Lower Back"}'::text[], 'Build leg strength with this hip hinge movement focusing on your hamstrings/glutes. Your glutes, lower back work as secondary movers, adding to the training stimulus. The machine guides your movement path for safer, more controlled repetitions. Lower body strength improves everything from walking to heavy compound lifts.', '87121201', '87121201-Lever-Romanian-Deadlift-(plate-loaded)-(male)_Hips.mp4', 'male', FALSE, '2025-12-03 23:26:28.260518+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Romanian Deadlift. 2. Push your hips back, lowering the weight along your legs with a flat back. 3. Lower until you feel a stretch in your hamstrings. 4. Drive hips forward to stand, squeezing glutes at the top. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, FALSE, NULL, 'Strength', 93, 7, 9, TRUE, FALSE, 'romanian_deadlift', 'Lever Romanian Deadlift', 'deadlift, leg_curl, hip_thrust', FALSE, 'machine', FALSE, 4, 120, 6, 80, 75, 20, 88),
('39bab578-d7ea-440a-9414-f35b07ff97b6', 'Seated Open Knee Leg Raise (Chair)', 'Core', 'Chair', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this raising movement that works your abs. Secondary activation of your hip flexors provides additional muscle engagement. The seated position helps isolate the target muscles by removing momentum. A strong core improves posture, protects your spine, and enhances all other lifts.', '83131201', '83131201-Seated-Open-Knee-Leg-Raise-on-a-Chair-(male)_Waist.mp4', 'male', FALSE, '2025-12-03 23:26:25.87243+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Keeping legs mostly straight, raise them toward the ceiling. 4. Lower with control, stopping just before touching down. 5. Repeat for the prescribed number of repetitions. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 57, 5, 7, FALSE, TRUE, 'leg_raise', 'Seated Open Knee Leg Raise On A Chair', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('39bb2060-80b4-4f54-88bc-87e986fc721f', 'Iron Cross Plank', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Elevate your training with this stabilization exercise that develops speed, power, and coordination. Secondary activation of your shoulders, core provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '11931201', '11931201-Iron-Cross-Plank_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:27.805708+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Complete all reps with control before resting. Start with lighter weight to perfect your form. Beneficial for overall plyometrics development.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 5, 7, 8, TRUE, TRUE, 'plank', 'Iron Cross Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('39c5a3b2-d613-4caa-bf73-a7cb2c0cffe1', 'Kneeling Plank Tap Shoulder', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Strengthen your midsection with this stabilization movement that works your abs. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. Kneeling helps eliminate lower body momentum from the movement. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention.', '32391201', '32391201-Kneeling-Plank-Tap-Shoulder-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:23.466497+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Hold your body in a straight line from head to heels. 3. Don''t let your hips sag or pike up—engage your core and glutes. 4. Breathe steadily while maintaining the position. 5. Repeat for the prescribed number of repetitions. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Kneeling Plank Tap Shoulder', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('39d74a50-1dbd-4c86-979f-f40556164562', 'Side Crunch (Against Wall)', 'Core', 'Wall', '{"Obliques"}'::text[], '{"Hip Flexors","Abs"}'::text[], 'The Side Crunch Against Wall is a core crunching exercise that primarily targets your abs. Secondary activation of your abs provides additional muscle engagement. A strong core improves posture, protects your spine, and enhances all other lifts.', '76771201', '76771201-Side-Crunch-against-Wall-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:26.93819+00', '1. Position yourself at the appropriate distance from a wall. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Repeat for the prescribed number of repetitions. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 62, 5, 7, FALSE, TRUE, 'crunch', 'Side Crunch Against Wall', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('39da5ed3-c551-45e5-8eb8-16b3687f41ca', 'Lying Back Of The Head Triceps Extension (Barbell)', 'Arms', 'Barbell, Flat Bench', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'Build stronger triceps with this extension exercise for bigger arms. Performing this lying down removes momentum for stricter form. The barbell allows you to handle heavier loads for maximum strength gains. Arm strength supports grip, pulling, and pushing in compound movements.', '17201201', '17201201-Barbell-Lying-Back-Of-The-Head-Tricep-Extension_Up.mp4', 'male', FALSE, '2025-12-03 23:26:27.805708+00', '1. Grip a barbell with hands at the appropriate width for Barbell Lying Back Of The Head Triceps Extension. 2. Lie down in the appropriate position for Barbell Lying Back Of The Head Triceps Extension. 3. Raise your torso by extending at the lower back/hips. 4. Lower with control, maintaining tension. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'tricep_extension', 'Lying Back Of The Head Triceps Extension', 'tricep_pushdown, close_grip_bench', TRUE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('39df918d-c1ad-46d6-ac29-0a40c888a4bf', 'Shuffle Hops', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'Build leg strength with this movement movement focusing on your full body. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '55121201', '55121201-Shuffle Hops_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:25.233728+00', '1. Set up in the starting position for Shuffle Hops. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 35, 9, 8, TRUE, TRUE, 'shuffle', 'Shuffle Hops', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('39e68acd-12ff-4dde-8863-a4473f34f03f', 'Kneeling Body Mobilization (Stability Ball)', 'Core', 'Stability Ball', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your core for improved core stability and strength. The kneeling position adds a core stability challenge. Using a ball requires constant core engagement to maintain balance. Building core stability helps with everything from heavy deadlifts to daily activities.', '98261201', '98261201-Kneeling-Body-Mobilization-on-Exercise-Ball-(male).mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. Position the stability ball as needed for Kneeling Body Mobilization On Exercise Ball. 2. Kneel on the floor (use a pad for comfort if needed). 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 30, 2, 6, FALSE, TRUE, 'mobility', 'Kneeling Body Mobilization On Exercise Ball', 'squat, leg_extension, lunge', FALSE, 'stability_ball', TRUE, 1, 30, 2, 70, 88, 95, 65),
('39e6aaae-00da-43a4-8e8c-268f5f8d01f5', 'Reverse Crunch (Cable)', 'Core', 'Cables', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Cable Reverse Crunch, focusing on your abs. Your hip flexors work as secondary movers, adding to the training stimulus. Cables provide constant tension throughout the full range of motion. Building core stability helps with everything from heavy deadlifts to daily activities.', '8731201', '08731201-Cable-Reverse-Crunch_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:28.968567+00', '1. Adjust the cable machine to the correct height and attachment for Cable Reverse Crunch. 2. Lift your hips off the floor by contracting your lower abs. 3. Bring your knees toward your chest, then lower with control. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'crunch', 'Reverse Crunch', 'leg_raise, plank, russian_twist, v_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('39f3241d-39a5-439e-b2ae-ce775bbf87e2', 'Seated Twist (Barbell)', 'Core', 'Barbell, Flat Bench', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Work your side abdominals with this twisting exercise that strengthens your obliques. The abs assist throughout the movement, making this a well-rounded exercise. The seated position helps isolate the target muscles by removing momentum. The barbell allows you to handle heavier loads for maximum strength gains. Building core stability helps with everything from heavy deadlifts to daily activities.', '941201', '00941201-Barbell-Seated-Twist_Waist.mp4', 'male', FALSE, '2025-12-03 23:26:20.392006+00', '1. Grip a barbell with hands at the appropriate width for Barbell Seated Twist. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Rotate your torso through the movement pattern for Barbell Seated Twist. 4. Control the rotation in both directions—avoid using momentum. 5. Repeat for the prescribed number of repetitions. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 64, 5, 7, FALSE, TRUE, 'russian_twist', 'Seated Twist', 'squat, bench_press, deadlift', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('3a1a6f53-f2a1-476f-a0f9-eca5dd251d8d', 'Pushdown - Reverse Grip (Cable)', 'Arms', 'Cables', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This pushing movement isolates your triceps for improved arm development. The cable setup allows you to adjust the angle of resistance. Arm strength supports grip, pulling, and pushing in compound movements. Keep your core engaged throughout the exercise.', '2071201', '02071201-Cable-Reverse-grip-Pushdown_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:28.260518+00', '1. Adjust the cable machine to the correct height and attachment for Cable Reverse Grip Pushdown. 2. Use a reverse grip (opposite of the standard grip for this exercise). 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 60, 5, 7, FALSE, TRUE, 'tricep_pushdown', 'Pushdown - Reverse Grip', 'Pushdown - Reverse Grip', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('3a251c33-3f2c-4da6-a020-f977f774413e', 'Chest Dip (Dip Bars)', 'Chest', 'Dip Bars', '{"Lower Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Target your chest with the Chest Dip, an effective dipping movement for upper body strength. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. A well-developed chest contributes to upper body strength and aesthetics.', '2511201', '02511201-Chest-Dip_Chest.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Lower your body by bending your elbows to about 90 degrees. 2. Push back up until your arms are fully extended. 3. Continue for your target rep count, maintaining good form throughout. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'dip', 'Chest Dip', 'bench_press, tricep_pushdown, push_up', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3a434947-c8ad-46b2-9bcb-7afba1e36ff3', 'Seated Abduction Twist (Chair) - Alternating', 'Core', 'Chair', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Work your side abdominals with this twisting exercise that strengthens your obliques. The abs assist throughout the movement, making this a well-rounded exercise. The seated position helps isolate the target muscles by removing momentum. Core strength is foundational for athletic performance and injury prevention.', '76301201', '76301201-Sitting-Alternate-Abduction-Twist-on-a-Chair-(fema.mp4', 'female', FALSE, '2025-12-03 23:26:37.628647+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Rotate your torso through the movement pattern for Seated Alternate Abduction Twist On A Chair. 4. Control the rotation in both directions—avoid using momentum. 5. Alternate between sides/arms/legs with each repetition. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 35, 5, 7, FALSE, TRUE, 'hip_abduction', 'Seated Abduction Twist On A Chair - Alternating', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('3a447802-4105-4840-8e70-9fa6fba2cb4b', 'Single Arm Bench Fly (Dumbbell)', 'Chest', 'Dumbbells, Flat Bench', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'This flying exercise focuses on your pectorals for improved chest strength and development. Secondary activation of your front delts provides additional muscle engagement. Using dumbbells requires more stabilization than barbell variations. A well-developed chest contributes to upper body strength and aesthetics.', '12851201', '12851201-Dumbbell-One-Arm-Bench-Fly_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:24.307972+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 77, 5, 7, FALSE, TRUE, 'chest_fly', 'Single Arm Bench Fly', 'bench_press, incline_press, push_up', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('3a66e78d-90b2-4bdf-8a42-d6e4ab3e01a1', 'Standing Hamstring And Calf Stretch With Strap (Gymnastic Rings)', 'Legs', 'Gymnastic Rings', '{"Calves"}'::text[], '{}'::text[], 'Build stronger calves with this targeted stretching exercise. Performing this standing challenges your balance and core engagement. Lower body strength improves everything from walking to heavy compound lifts.', '43171201', '43171201-Standing-Hamstring-and-Calf-Stretch-with-Starp-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Stand tall with your feet firmly planted. 2. Set up in the starting position for Standing Hamstring And Calf Stretch With Starp. 3. Execute the movement with proper form, focusing on your calves. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 30, 2, 6, FALSE, TRUE, 'calf_stretch', 'Standing Hamstring And Calf Stretch With Starp', 'stretch_hip, stretch_calf, stretch_back', FALSE, 'gymnastic_rings', TRUE, 1, 30, 2, 68, 85, 85, 70),
('3a6c02dc-c298-442e-9885-239531ececec', 'Front Plank Arm Leg Raise (Dumbbell)', 'Core', 'Dumbbells', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Build a stronger core with the Dumbbell Front Plank Arm Leg Raise, focusing on your abs. You''ll also feel your hip flexors working to support the movement. Using dumbbells requires more stabilization than barbell variations. Building core stability helps with everything from heavy deadlifts to daily activities.', '46271201', '46271201-Dumbbell-Front-Plank-Arm-Leg-Raise_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:23.466497+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Front Plank Arm Leg Raise. 2. Hold your body in a straight line from head to heels. 3. Don''t let your hips sag or pike up—engage your core and glutes. 4. Breathe steadily while maintaining the position. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'leg_raise', 'Front Plank Arm Leg Raise', 'crunch, plank, v_up', TRUE, 'dumbbell', TRUE, 3, 60, 2, 92, 90, 92, 90),
('3a6e5282-9fdf-40cb-b6b4-1a153241bf04', 'Upper Chest Crossovers (Cable)', 'Chest', 'Cables', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'This movement exercise focuses on your pectorals for improved chest strength and development. The front delts assist throughout the movement, making this a well-rounded exercise. The cable setup allows you to adjust the angle of resistance. A well-developed chest contributes to upper body strength and aesthetics.', '24421201', '24421201-Cable-Upper-Chest-Crossovers-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:32.166461+00', '1. Adjust the cable machine to the correct height and attachment for Cable Upper Chest Crossovers. 2. Set up in the starting position for Cable Upper Chest Crossovers. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'chest_fly', 'Upper Chest Crossovers', 'bench_press, incline_press, push_up', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('3a6ec461-4c60-4e11-b35e-2306af5599f2', 'Straight Leg Deadlift (Dumbbell)', 'Back', 'Dumbbells', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'The Dumbbell Straight Leg Deadlift is a lower body hip hinge exercise that targets your hamstrings/glutes. You''ll also feel your glutes, lower back working to support the movement. The dumbbell variation provides freedom of movement and greater range of motion. Leg training boosts metabolism and builds functional, real-world strength.', '101791201', '101791201-Dumbbell-Straight-Leg-Deadlift-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Straight Leg Deadlift. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Repeat for the prescribed number of repetitions. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'romanian_deadlift', 'Straight Leg Deadlift', 'deadlift, leg_curl, hip_thrust', FALSE, 'dumbbell', FALSE, 4, 120, 6, 92, 90, 92, 90),
('3a73463a-ebd1-4a29-9a71-647268b14697', 'Side Lying Knee Circle Kick', 'Hips', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'The Side Lying Knee Circle Kick is a lower body kicking exercise that targets your delts. The lying position provides back support and helps isolate the target muscles. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '65751201', '65751201-Side-Lying-Knee-Circle-Kick-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:37.179953+00', '1. Lie on your side with your body aligned. 2. Set up in the starting position for Side Lying Knee Circle Kick. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Side Lying Knee Circle Kick', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3a8646be-cb91-42ec-88e5-3e8f308bf986', 'Lying Air Punch', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Shoulders"}'::text[], 'The Lying Air Punch is a movement exercise that targets your chest muscles. Your shoulders work as secondary movers, adding to the training stimulus. Performing this lying down removes momentum for stricter form. This bodyweight exercise requires no equipment and can be done anywhere. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '89971201', '89971201-Lying-Air-Punch-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:35.010404+00', '1. Lie down in the appropriate position for Lying Air Punch. 2. Set up in the starting position for Lying Air Punch. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Lying Air Punch', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3a8f0828-8247-431c-b4b4-b3bace6bf8ba', 'Side To Side Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Target your chest with the Side To Side Push Up, an effective pushing movement for upper body strength. Secondary activation of your triceps, front delts provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '54431201', '54431201-Side-to-Side-Push-up-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:37.429219+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout. Keep your core engaged for stability. Include this in your chest training.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Side To Side Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3a96f9d5-c995-4947-88b0-772b82f5e604', 'Bicep Curl - March On Spot', 'Arms', 'Bodyweight', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This dynamic curling movement gets your heart rate up while developing explosive strength. You''ll also feel your hip flexors working to support the movement. No equipment needed—your body provides all the resistance. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '89821201', '89821201-March-on-Spot-Bicep-Curl-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:35.38119+00', '1. Keep your elbows in a fixed position throughout the movement. 2. Curl the weight up by contracting your biceps, squeezing at the top. 3. Lower with control, resisting the weight on the way down. 4. Continue for your target rep count, maintaining good form throughout. Focus on squeezing the target muscle at peak contraction.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Cardio', 80, 5, 7, FALSE, TRUE, 'bicep_curl', 'March On Spot Biceps Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('3aa19964-69f2-4d2e-9cb6-c6886ed7f31e', 'Shoulder Backbend Stretch', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'The Shoulder Backbend Stretch is a stretching exercise that targets your delts for shoulder development. No equipment needed—your body provides all the resistance. Strong shoulders improve overhead strength and support nearly all upper body movements.', '35161201', '35161201-Shoulder-Backbend-Stretch_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:29.837118+00', '1. Set up in the starting position for Shoulder Backbend Stretch. 2. Execute the movement with proper form, focusing on your delts. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Shoulder Backbend Stretch', 'stretch_chest, stretch_tricep, stretch_lat', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('3aa22bb6-8837-47d3-9440-1854be99a283', 'Seated Front Raise (Dumbbell)', 'Shoulders', 'Dumbbells, Flat Bench', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'Build stronger shoulders with this raising movement focusing on your front delts. The seated position helps isolate the target muscles by removing momentum. The dumbbell variation provides freedom of movement and greater range of motion. Shoulder development enhances both performance and upper body aesthetics. Works well as both a primary exercise or accessory movement. Consistency with this movement will yield noticeable results.', '22351201', '22351201-Dumbbell-Seated-Front-Raise-(female)_Shoulders.mp4', 'female', FALSE, '2025-12-03 23:26:33.034396+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Seated Front Raise. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Raise the weight in front of you to shoulder height. 4. Lower with control, maintaining tension throughout. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 84, 5, 7, FALSE, TRUE, 'front_raise', 'Seated Front Raise', 'shoulder_press, lateral_raise, rear_delt_fly', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('3aa69f71-e35e-43e8-ba7e-da06d8ffdd2e', 'Seated High Triceps Extension (Cable)', 'Arms', 'Cables', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This extension movement isolates your triceps for improved arm development. The seated position helps isolate the target muscles by removing momentum. Cable resistance creates smooth, continuous muscle engagement. Dedicated arm training builds both strength and muscular definition.', '97271201', '97271201-Cable-Seated-High-Triceps-Extension-(female)_Upper.mp4', 'female', FALSE, '2025-12-03 23:26:32.054831+00', '1. Set the cable pulley to the highest position and attach your preferred handle. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Extend at the elbow until your arm is straight, squeezing the tricep. 4. Lower with control, keeping your upper arm stationary. 5. Complete all reps with control before resting. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'tricep_extension', 'Seated High Triceps Extension', 'tricep_pushdown, close_grip_bench', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('3aaf498e-d47d-475b-b393-23706ce82d07', 'Iron Cross Stretch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Use this stretch to open up your full body area and enhance overall flexibility. Regular stretching improves flexibility, reduces injury risk, and aids recovery. Start with lighter weight to master the movement pattern.', '32851201', '32851201-Iron-Cross-Stretch-(female)_Hips-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:34.196858+00', '1. Move into the stretch position for Iron Cross Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 5, 2, 6, FALSE, TRUE, 'stretch_general', 'Iron Cross Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('3aafe915-f2fa-440a-af14-778d0c2d104a', 'Arms Up Rotational Side Step', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Arms Up Rotational Side Step is an explosive exercise that combines cardiovascular training with dynamic rotation movements. Your quads work as secondary movers, adding to the training stimulus. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '85111201', '85111201-Arms-Up-Rotational-Side-Step-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:24.422129+00', '1. Set up a box or step platform at the appropriate height. 2. Rotate your torso through the movement pattern for Arms Up Rotational Side Step. 3. Control the rotation in both directions—avoid using momentum. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 42, 7, 8, TRUE, TRUE, 'woodchop', 'Arms Up Rotational Side Step', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3ab15a9d-4ef5-428f-a1e7-c4cbac9a6715', 'Step Up On Stepbox (Step Platform)', 'Legs', 'Step Platform', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Bodyweight Step Up On Stepbox is a stepping exercise that primarily loads your quadriceps. You''ll also feel your glutes, hamstrings working to support the movement. Leg training boosts metabolism and builds functional, real-world strength.', '45791201', '45791201-Bodyweight-Step-up-on-Stepbox_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:21.608253+00', '1. Set up a box or step platform at the appropriate height. 2. Step one foot onto the elevated surface. 3. Drive through that foot to lift your body up onto the platform. 4. Step back down with control and repeat. 5. Repeat for the prescribed number of repetitions. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'step_up', 'Step Up On Stepbox', 'lunge, split_squat, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3abc3535-c561-4518-9d86-698b1620c280', 'Hand Spring Wrist Curl (Gymnastic Rings)', 'Arms', 'Gymnastic Rings', '{"Forearms"}'::text[], '{}'::text[], 'Build grip strength and forearm size with this curling exercise. Your forearms work as secondary movers, adding to the training stimulus. Arm strength supports grip, pulling, and pushing in compound movements.', '33451201', '33451201-Hand-Spring-Wrist-Curl_Hands_.mp4', 'male', FALSE, '2025-12-03 23:26:28.968567+00', '1. Keep your elbows in a fixed position throughout the movement. 2. Curl the weight up by contracting your biceps, squeezing at the top. 3. Lower with control, resisting the weight on the way down. 4. Complete all reps with control before resting. Focus on maintaining proper breathing throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 58, 5, 7, FALSE, TRUE, 'wrist_curl', 'Hand Spring Wrist Curl', 'tricep_pushdown, tricep_extension, hammer_curl, preacher_curl', FALSE, 'gymnastic_rings', FALSE, 3, 60, 2, 68, 85, 85, 70),
('3ac0cad0-7014-4c96-9c80-65e5667778d8', 'Wide Stance Thoracic Rotation', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Work your side abdominals with this rotation exercise that strengthens your obliques. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '90741201', '90741201-Wide-Stance-Thoracic-Rotation-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:40.146812+00', '1. Rotate your torso through the movement pattern for Wide Stance Thoracic Rotation. 2. Control the rotation in both directions—avoid using momentum. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'spinal_stretch', 'Wide Stance Thoracic Rotation', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3ac1e1ec-3f25-4431-abc3-05e4d9bf06f0', 'Sun Salutation B', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Target your full body with this movement stretch that helps restore range of motion. Include this in your routine for better mobility and reduced muscle tension. Perfect for including in both strength and hypertrophy programs. This exercise pairs well with complementary movements for balanced training.', '59811201', '59811201-Sun-Salutation-B-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Move into the stretch position for Sun Salutation B. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Stretch', 15, 7, 8, TRUE, TRUE, 'yoga', 'Sun Salutation B', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3accbe17-c089-4951-a887-8dc56befdb20', 'Hammer Preacher Curl (Dumbbell)', 'Arms', 'Dumbbells, Preacher Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. Your forearms work as secondary movers, adding to the training stimulus. Using dumbbells requires more stabilization than barbell variations. Arm strength supports grip, pulling, and pushing in compound movements.', '43371201', '43371201-Dumbbell-Hammer-Preacher-Curl-(female)_Forearms_.mp4', 'female', FALSE, '2025-12-03 23:26:32.735372+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Hammer Preacher Curl. 2. Use a hammer/neutral grip with palms facing each other throughout. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'preacher_curl', 'Hammer Preacher Curl', 'tricep_pushdown, tricep_extension, bicep_curl, hammer_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('3ad7aaed-c739-446a-b6e1-10aba050e664', 'Ring Inverted Row Parallel To The Floor (Gymnastic Rings)', 'Back', 'Gymnastic Rings', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. The biceps assist throughout the movement, making this a well-rounded exercise. A strong back improves posture, prevents injury, and balances pressing movements. Maintain proper breathing - exhale during the effort phase.', '76551201', '76551201-Ring-Inverted-Row-parallel-to-the-floor-(male)_Bac.mp4', 'male', FALSE, '2025-12-03 23:26:27.384461+00', '1. Position yourself on the floor for Ring Inverted Row Parallel To The Floor. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 53, 7, 8, TRUE, TRUE, 'general_exercise', 'Ring Inverted Row Parallel To The Floor', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'gymnastic_rings', FALSE, 3, 90, 4, 68, 85, 85, 70),
('3ae62edd-4f58-4989-8ae2-f49850295476', 'Leg Raise From Reverse Plank Position - Alternating', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'The Alternate Leg Raise From Reverse Plank Position is a core raising exercise that primarily targets your abs. You''ll also feel your hip flexors working to support the movement. No equipment needed—your body provides all the resistance. Building core stability helps with everything from heavy deadlifts to daily activities.', '51991201', '51991201-Alternate-Leg-Raise-from-Reverse-Plank-Position-(f.mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Alternate between sides/arms/legs with each repetition. 5. Repeat for the prescribed number of repetitions. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Leg Raise From Reverse Plank Position - Alternating', 'crunch, plank, v_up', FALSE, 'bodyweight', TRUE, 3, 60, 2, 70, 88, 95, 65),
('3b088f31-b247-4bdd-b6d6-38597f5336f6', 'Incline Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'The Incline Push Up is a pushing exercise that targets your chest muscles. You''ll also feel your triceps, front delts working to support the movement. Using an incline changes the angle of resistance for varied muscle recruitment. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '4931201', '04931201-Incline-Push-up_Chest.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Repeat for the prescribed number of repetitions. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 73, 7, 8, TRUE, TRUE, 'push_up', 'Incline Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3b090305-a3da-4eca-ab11-932ec6f44eeb', 'Side Hip - On Parallel Bars (Dip Bars)', 'Core', 'Dip Bars', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. A strong core improves posture, protects your spine, and enhances all other lifts. Start with lighter weight to master the movement pattern.', '7091201', '07091201-Side-Hip-(on-parallel-bars)_Waist-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Set up in the starting position for Side Hip. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'dip', 'Side Hip', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3b0b5a81-d896-49b9-bb11-201d27f8fe14', 'Seated Back Press', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger back with this pressing movement targeting your core. The seated position helps isolate the target muscles by removing momentum. Back development is crucial for pulling strength and overall upper body function.', '89381201', '89381201-Seated-Back-Press-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:22.644637+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Execute the pressing motion for Seated Back Press, extending through the target muscles. 3. Complete all reps with control before resting. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 72, 7, 8, TRUE, TRUE, 'back_exercise', 'Seated Back Press', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3b1744fd-969e-4747-a6d3-fe544d5a9470', 'Seated Isometric Hold Pull Up (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'The Seated Isometric Hold Pull Up is a pulling exercise that targets your latissimus dorsi for a wider back. The biceps, upper back assist throughout the movement, making this a well-rounded exercise. The seated position helps isolate the target muscles by removing momentum. Back development is crucial for pulling strength and overall upper body function.', '93171201', '93171201-Seated-Isometric-Hold-Pull-up_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:27.145158+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Pull yourself up by driving your elbows down and back. 3. Continue until your chin clears the bar, then lower with control to a full hang. 4. Hold the position for the prescribed time, maintaining tension.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 67, 7, 8, TRUE, TRUE, 'pull_up', 'Seated Isometric Hold Pull Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'pull_up_bar', TRUE, 3, 90, 4, 70, 88, 95, 65),
('3b1bb9c6-97ce-4d6a-92ae-c12683ed351a', 'Frog Reverse Hyperextension Tap On Floor', 'Back', 'Bodyweight', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Frog Reverse Hyperextension Tap On Floor is a hip-dominant extension exercise that targets your glutes. Secondary activation of your hamstrings, lower back provides additional muscle engagement. Strong legs are the foundation for athletic performance and functional fitness.', '54751201', '54751201-Frog-Reverse-Hyperextension-Tap-on-Floor-(male)_Hi.mp4', 'male', FALSE, '2025-12-03 23:26:23.987963+00', '1. Position yourself on the floor for Frog Reverse Hyperextension Tap On Floor. 2. Raise your torso by extending at the lower back/hips. 3. Lower with control, maintaining tension. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 65, 5, 7, FALSE, TRUE, 'back_extension', 'Frog Reverse Hyperextension Tap On Floor', 'good_morning, bird_dog, superman', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('3b200d2a-0a40-4827-bf4a-6b621d0d8aab', 'Lying Back Extension', 'Back', 'Bodyweight', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build leg strength with this extension movement focusing on your lower back. Your glutes work as secondary movers, adding to the training stimulus. The lying position provides back support and helps isolate the target muscles. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '32081201', '32081201-Lying-Back-Extension-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.133808+00', '1. Lie down in the appropriate position for Lying Back Extension. 2. Raise your torso by extending at the lower back/hips. 3. Lower with control, maintaining tension. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'back_extension', 'Lying Back Extension', 'good_morning, bird_dog, superman', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('3b2fe3a8-5fc8-48c3-87a1-9adf7c1e97c0', 'Lateral Raise - Chest Supported (Machine)', 'Shoulders', 'Machine', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'Target your lateral delts with the Lever Lateral Raise With Chest Support, an effective shoulder raising exercise. Machine exercises are great for isolating muscles and training to failure safely. Shoulder development enhances both performance and upper body aesthetics.', '65361201', '65361201-Lever-Lateral-Raise-with-Chest-Support-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:29.483269+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Lateral Raise With Chest Support. 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 88, 5, 7, FALSE, TRUE, 'lateral_raise', 'Lever Lateral Raise With Chest Support', 'shoulder_press, front_raise, rear_delt', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('3b4bf026-82fc-40e7-bdf0-76d3d2f7d834', 'Lying Hamstring Curl (Dumbbell)', 'Legs', 'Dumbbells, Gymnastic Rings, Flat Bench', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'Strengthen the back of your thighs with this curling exercise. Your forearms work as secondary movers, adding to the training stimulus. The lying position provides back support and helps isolate the target muscles. Using dumbbells requires more stabilization than barbell variations. Strong legs are the foundation for athletic performance and functional fitness.', '42921201', '42921201-Dumbbell-Lying-Hamstring-Curl_Thighs.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Lying Hamstring Curl. 2. Lie down in the appropriate position for Dumbbell Lying Hamstring Curl. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_curl', 'Lying Hamstring Curl', 'romanian_deadlift, hip_thrust', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('3b4d330e-fdb5-42bd-ac17-7af2586cea61', 'Weighted Hyperextension (Hyperextension Bench)', 'Back', 'Hyperextension Bench', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Develop your posterior chain with this extension movement that emphasizes the glutes. The hamstrings, lower back assist throughout the movement, making this a well-rounded exercise. Leg training boosts metabolism and builds functional, real-world strength.', '57821201', '57821201-Weighted-Hyperextension-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:40.037451+00', '1. Raise your torso by extending at the lower back/hips. 2. Lower with control, maintaining tension. 3. Complete all reps with control before resting. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'back_extension', 'Weighted Hyperextension', 'good_morning, bird_dog, superman', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('3b52b631-8557-4901-908c-11737f7d7b8c', 'Cobra To Side Shoulder Stretch', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'This stretch specifically works on your shoulders, promoting flexibility and reducing muscle tightness. You''ll also feel your upper back working to support the movement. Include this in your routine for better mobility and reduced muscle tension.', '103651201', '103651201-Cobra-to-Side-Shoulder-Stretch-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:23.586683+00', '1. Move into the stretch position for Cobra To Side Shoulder Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 4. Switch sides and repeat for equal time.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'shoulder_stretch', 'Cobra To Side Shoulder Stretch', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('3b64904c-1ef2-4d7b-9b26-89258355017a', 'Single Curtsy Lunge', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this lunging movement that develops leg drive and power. Secondary activation of your glutes, hamstrings provides additional muscle engagement. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength. Perfect for including in both strength and hypertrophy programs.', '63181201', '63181201-Single-Curtsy-Lunge-(female)_Hips-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:37.429219+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Repeat for the prescribed number of repetitions. Maintain consistent tempo throughout the set. Include this in your legs training.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'lunge', 'Single Curtsy Lunge', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3b6ccd0e-cb4e-4ef0-8e65-0acf07934afe', 'Leg Curl - Single Leg (Machine)', 'Legs', 'Machine', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'The Lever Seated One Leg Curl targets your hamstrings through a controlled curling motion. Secondary activation of your calves provides additional muscle engagement. The seated position helps isolate the target muscles by removing momentum. The machine guides your movement path for safer, more controlled repetitions. Lower body strength improves everything from walking to heavy compound lifts.', '57271201', '57271201-Lever-Seated-One-Leg-Curl-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Seated One Leg Curl. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Curl your heels toward your glutes by bending at the knees. 4. Squeeze your hamstrings at peak contraction. 5. Extend legs back out with control. 6. Complete all reps on one side, then switch to the other side. 7. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'leg_curl', 'Lever Seated Single Leg Curl', 'romanian_deadlift, hip_thrust', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('3b7e2779-3db2-42a4-895a-9a689e85e497', 'Side Camel', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Hip Flexors","Abs"}'::text[], 'The Side Camel provides a deep stretch for your chest, ideal for recovery and mobility work. Secondary activation of your hip flexors, abs provides additional muscle engagement. Include this in your routine for better mobility and reduced muscle tension.', '89511201', '89511201-Side-Camel-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:21.732034+00', '1. Move into the stretch position for Side Camel. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 4. Switch sides and repeat for equal time. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Side Camel', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3ba0355a-7194-4a45-b5e1-2def5bae7e52', 'Neck Stretch With Hand Assisted', 'Neck', 'Bodyweight', '{"Neck"}'::text[], '{"Traps"}'::text[], 'Designed to lengthen your neck, the Neck Stretch With Hand Assisted helps improve mobility and prevent stiffness. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '67651201', '67651201-Neck-Stretch-with-Hand-Assisted-(female)_Neck_.mp4', 'female', FALSE, '2025-12-03 23:26:35.532804+00', '1. Move into the stretch position for Neck Stretch With Hand Assisted. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'neck_stretch', 'Neck Stretch With Hand Assisted', 'stretch_hip, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('3ba47611-cf4c-4d62-b4d7-39cdb4290700', 'Seated Scapular Adduction (Stability Ball)', 'Back', 'Stability Ball', '{"Inner Thighs"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build leg strength with this movement movement focusing on your adductors. The seated position helps isolate the target muscles by removing momentum. Using a ball requires constant core engagement to maintain balance. Lower body strength improves everything from walking to heavy compound lifts.', '84821201', '84821201-Sitting-Scapular-Adduction-on-Stability-Ball-(male.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Position the stability ball as needed for Seated Scapular Adduction On Stability Ball. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 42, 7, 8, TRUE, TRUE, 'hip_adduction', 'Seated Scapular Adduction On Stability Ball', 'plank, crunch, leg_raise', FALSE, 'stability_ball', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3ba50c1b-17ee-4fa7-a12a-cc9a6a75aeb3', 'Bulgarian Split Squat (Plate Loaded Machine)', 'Legs', 'Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. The fixed path allows you to focus purely on muscular effort. Leg training boosts metabolism and builds functional, real-world strength.', '87131201', '87131201-Lever-Bulgarian-Split-Squat-(plate-loaded)-(male)_.mp4', 'male', FALSE, '2025-12-03 23:26:30.099411+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Bulgarian Split Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 93, 7, 9, TRUE, FALSE, 'split_squat', 'Lever Bulgarian Split Squat', 'split_squat, lunge, leg_press', FALSE, 'machine', FALSE, 4, 120, 5, 80, 75, 20, 88),
('3baee0dd-7a4e-4ba6-b84d-88ad9bc1dcde', 'Forearm Pronation (Cable)', 'Arms', 'Cables', '{"Forearms"}'::text[], '{}'::text[], 'The Cable Forearm Pronation strengthens your forearms and grip through a movement motion. Cables provide constant tension throughout the full range of motion. Dedicated arm training builds both strength and muscular definition. A staple exercise that belongs in most training programs.', '88811201', '88811201-Cable-Forearm-Pronation-(male)_Forearms-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:27.67144+00', '1. Adjust the cable machine to the correct height and attachment for Cable Forearm Pronation. 2. Set up in the starting position for Cable Forearm Pronation. 3. Execute the movement with proper form, focusing on your forearms. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'arm_exercise', 'Forearm Pronation', 'plank, crunch, leg_raise', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('3bc4445a-9542-461e-a2a7-fc3691afd53d', 'Plank Hands Tap Feet Tap', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Build a stronger core with the Plank Hands Tap Feet Tap, focusing on your abs. Your shoulders, lower back work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '81811201', '81811201-Plank-Hands-Tap-Feet-Tap-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.123147+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Complete all reps with control before resting. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Plank Hands Tap Feet Tap', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3bc799c7-d3ae-407d-9e21-9c3ed863be65', 'Single Leg Squat (TRX)', 'Legs', 'TRX', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. The TRX allows you to adjust difficulty by changing your body angle. Leg training boosts metabolism and builds functional, real-world strength.', '11011201', '11011201-Suspender-Single-Leg-Squat-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:39.472701+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Single Leg Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pistol_squat', 'Suspender Single Leg Squat', 'squat, bench_press, deadlift', TRUE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('3bd2c90e-d07a-46a3-962b-726f35ee098b', 'Glute Bridge Two Legs (Chair)', 'Legs', 'Chair', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'The Glute Bridge Two Legs With Chair is a hip-dominant bridging exercise that targets your glutes. Secondary activation of your hamstrings provides additional muscle engagement. Strong legs are the foundation for athletic performance and functional fitness.', '71381201', '71381201-Glute-Bridge-Two-Legs-with-Chair-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:33.778367+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'glute_bridge', 'Glute Bridge Two Legs With Chair', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3bd78227-fd79-48a1-ab70-3e51b897a69f', 'Circles Elbow Arm', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'The Circles Elbow Arm is a movement exercise that targets your delts for shoulder development. No equipment needed—your body provides all the resistance. Shoulder development enhances both performance and upper body aesthetics.', '2561201', '02561201-Circles-Elbow-Arm-(female)_Shoulders.mp4', 'female', FALSE, '2025-12-03 23:26:32.374165+00', '1. Set up in the starting position for Circles Elbow Arm. 2. Execute the movement with proper form, focusing on your delts. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'arm_exercise', 'Circles Elbow Arm', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3bdd85b0-0b4b-4224-98fa-f4fc64bc3e24', 'Plank On Elbows Toe Tap', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'This stabilization exercise engages your abs for improved core stability and strength. You''ll also feel your shoulders, lower back working to support the movement. No equipment needed—your body provides all the resistance. Building core stability helps with everything from heavy deadlifts to daily activities.', '103691201', '103691201-Plank-on-Elbows-Toe-Tap-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:27.504261+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Complete all reps with control before resting. Engage your stabilizer muscles for better control. Great for building strength in your abs.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Plank On Elbows Toe Tap', 'side_plank, dead_bug, hollow_hold', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
